INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2159, 'Lirdnolu Dhuurniv', 28, NULL, 'PV : 50 (10 DV)\nDrow femelle Prêtre de Lolth 10\nCM Humanoïde de taille moyenne (elfe)\nInitiative : +3\nSens : vision dans le noir 36m ; Perception auditive +5, Détection +5\nLangues : Commun, Langue des signes drow, Elfique, Commun des profondeurs\nClasse d\'armure : 23, contact 13, pris au dépourvu 20\nImmunités : aux effets de sommeil magique\nRM : 21\nJets de sauvegarde : Vig +6, Réf +7, Lutte +10 (+12 contre les sorts, les capacités similaires aux sorts et les enchantements)\nVulnérabilités : à la lumière\nVitesse de déplacement : 6m (4 cases) dans le plastron, vitesse de base 9m\nMêlée : de maître dague +6 (1d4+1/19-20 plus poison) ou\nMêlée : masse légère de maître +9/+4 (1d6+1)\nDistance : dague de maître +12/+6 (1d4+2/19-20 plus poison)\nAttaque de base : +7/+2\nLutte : +8\nOptions de combat : poison (poison drow, DD 13, inconscient 1 minute/inconscient 2d4 heures)\nActions spéciales : Intimidation des mort-vivants 3/jour (+2, 2d6+6, 10ème), Intimidation des araignées 3/jour (+2, 2d6+6, 10ème), incantation spontanée (sorts de Blessure) (+7 toucher en mêlée)\nÉquipement de combat : 2 doses de poison drow, insigne de la Maison Dhuurniv*\nSorts de clercs préparés (NLS 10ème) :\n5ème - Blessure légère de groupe, Forme arachnide, Rejet du bienD, Injonction suprême\n4ème - Armure des ténèbres†, Blessure critique, Ténèbres mauditesD, Vermine géanteD, Puissance divine\n3ème - Ténèbres profondes†, Cercle magique contre le bienD (NLS 11ème, DD 16), Prière, Protection contre les énergies destructives (DD 16)\n2ème - Immobilisation de personne, Soins modérés (2), Sagesse du hibou, Silence (DD 15), Nuée grouillanteD, Sombre trait\n1er - Blessure légère (x2), Soins légers, EntraveSC (DD 14), Sanctuaire (DD 14), Pattes d\'araignéesD\n0 - Création d\'eau, Détection de la magie, Détection du poison, Purification de nourriture et d\'eau\n† déjà lancé\nD : sort de domaine. Déité Lolth. Domaines : Mal, araignéeFRCS\nCapacités de type sort (NLS 6e) :\n1/jour - Clairaudience/clairvoyance, Lumières dansantes, Ténèbres, Détection du bien, Détection du mensonge (DD 14), Détection de la magie, Dissipation de la magie, Lueur féerique, Lévitation, Suggestion (DD 13)\nCaractéristiques : For 13, Dex 16, Con 10, Int 12, Sag 17, Cha 10\nParticularités : capacité à remarquer les portes secrètes ou dissimulées, utilisation de poison\nDons : Magie de guerre, Drow de haute naissance* , Bénédiction de Lolth, Extension de portée\nCompétences : Concentration +7 (+11 lancer défensif), Diplomatie +7, Connaissances (religion) +7, Perception auditive +5, Fouille +3, Art de la magie +8, Détection +5\nPossessions : équipement de combat plus cuirasse +2, bouclier d’acier léger +2, dague de maître +1, masse légère de maître, 23 po, 1 pa\nVulnérabilité à la lumière (Ext). Une exposition brutale à une lumière vive (comme la lumière du soleil ou un sort de lumière du jour) rend Lirdnolu aveugle pendant 1 round. De plus, elle subit une pénalité de circonstance de -1 aux jets d’attaque, aux sauvegardes et aux tests lorsqu’elle évolue dans une lumière vive\n* voir page 150 et 151 du scénario', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2159);

