-- 2167 — Destrier d’Istivin
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2167, 'Destrier d’Istivin', 21, NULL, 'PV : 76 (8 DV)\nAberration ailéeLE\nNM Aberration de taille énorme\nInitiative : +1\nSens : vision dans noir 18m ; Perception auditive +0, Détection +11\nLangues : Aberration ailée «appels d’animaux», liée à son maître comme le compagnon animal d’un druide\nClasse d\'armure : 17, contact 9, pris au dépourvu 16\nJets de sauvegarde : Vig +7, Réf +3, Vol +6\nVitesse de déplacement : 6m (4 cases), Vol 9m (médiocre)\nMêlée : 3 morsures +13 chacune (1d8+9) et 2 griffes +8 chacune (2d4+4)\nEspace : 4,5m ; Allonge 3m.\nAttaque de base/lutte : +6/+23\nOptions de combat : drain de sang\nAttaques spéciales : souffle, écrasement\nCaractéristiques : For 28, Dex 12, Con 20, Int 7, Sag 10, Cha 5\nDons : #Attaque en vol#, #Vol stationnaire#, #Virage sur l\'aile#\nCompétences : Escalade +17, Détection +11\nDrainage sanguin (Ext). Une aberration ailée peut utiliser ses trois longues langues tubulaires pour drainer le sang d’une victime qu’elle a coincée avec son attaque d’écrasement. S’il réussit son test d’agrippement, il inflige 1d4 points de dégâts de Constitution\nSouffle (Sur). L’arme à souffle d’une ailée est un cône d’acide de 9m qui brûle les yeux et la peau ex- posée des adversaires. Chaque créature située dans le cône doit réussir une sauvegarde Réflexes DD 19 ou être aveuglée et étourdie pendant 1 round\nÉcraser (Ext). Cette attaque spéciale permet à une aberration ailée d’atterrir sur ses adversaires comme action standard, en utilisant tout son corps pour les écraser. Les attaques d’écrasement ne sont efficaces que contre les adversaires de petite taille ou plus petits (bien qu’il puisse tenter des attaques normales de débordement ou d’agrippement contre des adversaires plus grands).\nUne attaque d’écrasement affecte autant de créatures qu’il est possible d’en placer sous le corps de l’aberration ailée. Les créatures situées dans la zone affectée doivent réussir un jet de sauvegarde Réflexes DD 19 ou être clouées au sol, subissant automatiquement des dégâts contondants au cours du round suivant, à moins que l’aberration ailée ne s’en éloigne. Si l’aber- ration ailée choisit de maintenir l’épingle, traitez là comme une attaque de grappin normale. Les adversaires coincés subissent des dégâts d’écrasement à chaque round s’ils ne s’échappent pas. Une attaque d’écrasement inflige 2d8+13 points de dégâts', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2167);

-- 2168 — Chauve-souris fiélonne
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2168, 'Chauve-souris fiélonne', 23, NULL, 'PV : 30 (4 DV) ; RD 5/magie\nNM bête magique de grande taille (extraplanaire) Init +6\nSens : perception aveugle sur 12m, vision dans noir sur 18m ; Perception auditive +12. (+8 si la perception aveugle est annulée), Détection +8 (+4 si la perception aveugle est annulée)\nClasse d\'armure : 20, contact 15, pris au dépourvu 14 Résistance au froid 5, au feu 5 ;\nRM : 9\nJets de sauvegarde : Vig +7, Réf +10, Lutte +6\nVitesse de déplacement : 6m (4 cases), Vol 12m (bon)\nMêlée : Morsure +5 (1d8+4) Espace 3m ; Allonge 1,5 m. Attaque de base +3\nLutte : +10\nOptions de combat : combat smite good 1/jour (+4 dégâts)\nCaractéristiques : For 17, Dex 22, Con 17, Int 3, Sag 14, Cha 6\nDons : #Vigilance#, #Discret#\nCompétences : Détection +4, Discrétion +4, Perception auditive +12 (+8 si la perception aveugle est annulée), Déplacement silencieux +11, Fouille +8 (+4 si la perception aveugle est annulée)\nChâtiment du bien (Sur). Une fois par jour, une chauve-souris fiélonne peut effectuer une attaque de mêlée normale pour infliger 4 points de dégâts sup- plémentaires à un ennemi bon', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2168);

-- 2169 — Gormauthator
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2169, 'Gormauthator', 11, NULL, 'PV 255 (34 DV) ; RD 5/contondant\nAncien dragon rouge squelettique mâle N Mort-vivant gargantuesque\nInit +4 ; Sens : perception aveugle sur 60 m, vision dans le noir sur 120 m, Sens aiguisés ; Perception + 0, Détection + 0\nAura présence effrayante (90m, DD 34)\nLangues comprend les ordres du créateur\nCA 12, contact 6, pris au dépourvu 12\nImmunités au froid, au feu, aux morts-vivants\nVig +19, Réf +19, Lutte +19\nVitesse 12m (8 cases)\nMorsure +44 (4d6+14) et 2 griffes +39 (2d8+7) et 2 ailes +39 (2d6+7) et coup de queue +39 (2d8+21) Espace 6m ; Allonge 15 ft (6m avec morsure) Attaque de base +34 ; Lutte +60\nOptions de combat balayage de la queue Caractéristiques For 39, Dex 10, Con -, Int -, Sag 10, Cha 24\nParticularités. des morts-vivants\nDons Science de l\'initiative\nPrésence effrayante (Ext). Gormauthator peut inspirer la terreur en chargeant ou en attaquant. Les créatures situées à moins de 300 pieds du dragon et ayant 33 HD ou moins doivent tenter un jet de sauvegarde de Vol DD 34. Une réussite indique que la cible est immunisée contre la présence effrayante de Gormauthator pendant 24 heures. En cas d’échec, les créatures de 4 HD ou moins sont paniquées pendant 4d6 rounds. Celles de 5 HD ou plus sont secouées pendant 4d6 rounds\nBalayage de la queue (Ext). Demi-cercle de 9m de diamètre ; les adversaires de petite taille ou moins subissent 2d6+21 points de dégâts contondants (Ré- flexes DD 27 à moitié)', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2169);

-- 2170 — Goelier de Syluné
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2170, 'Goelier de Syluné', 25, NULL, 'PV 127 (15 DV) ; RD 10/magie\nNishruuLF\nLost Empires of Faerun\nCN Extérieur de grande taille (chaotique) Faiblesses Init +4 ; Sens vision dans noir 18m ; Perception auditive +16, Détection +16\nCA 9, contact 9, pris au dépourvu 9\nImmunités aux coups critiques, aux sorts et caractéristiques affectant l’esprit, au poison\nRésistance au froid 10 Vig +12, Réf +9, Lutte +13 vulnérabilités\nVitesse Vol 6m (4 cases) (parfaite)\nMêlée essaim de morsures (3d6)\nEspace 3m ; Allonge 1,5m\nAttaque de base +15 ; Lutte -\nOptions de combat absorption de la magie, distraction, nuée de morsures\nCaractéristiques For -, Dex 10, Con 16, Int 13, Sag 15, Cha 14\nParticularités. charge magique, forme gazeuse dons caractéristiques (absorber la magie), Vigilance, science de l\'initiative, arme naturelle supérieure (nuée de morsures), volonté de fer, science de la Robustesse\nCompétences Concentration +21, Connaissances (arcanes) +19, Connaissances (histoire) +19, Connaissances (plans) +19, Perception auditive +22, Déplacement silencieux +18, Fouille +19, Art de la magie +21, Détection +22, Survie +2 (+4 sur les autres plans)\nAbsorption de la magie (Sur). Si un nishruu est la cible d’un sort qui inflige des points de vie, il absorbe le sort et gagne en permanence un nombre de points de vie égal aux dégâts qu’il aurait subis. Les seules exceptions sont les sorts de froid et de feu, qui infligent des dégâts (réduits dans le cas des sorts de froid) puis se dissipent au bout d’un round.\nSi un nishruu est la cible d’un sort sans dégâts, il ab- sorbe le sort et gagne 1 point de vie par niveau de sort. Si un objet magique doté de charges est en contact avec un nishruu, la créature absorbe 1d4 charges lors du premier contact et autant tous les deux rounds par la suite.\nSi un nishruu est en contact avec un objet magique sans charge, l’effet de l’objet est annulé tant qu’il reste en contact avec le nishruu et pendant 1d4 rounds par la suite.\nUn lanceur de sorts perd un sort préparé ou un emplacement de sort, déterminé aléatoirement, au premier contact avec un nishruu. Chaque round suivant où les deux restent en contact, le lanceur de sorts perd un sort supplémentaire choisi au hasard. Chaque fois qu’il perd un sort de cette manière, il doit effectuer un jet de sauvegarde de Vol DD 21 ou subir l’effet d’un sort d’esprit faible\nDistraction (Ext). Toute créature vivante vulnérable à une attaque d’essaim qui commence son tour avec un nishruu dans sa case est nauséeuse pendant 1 round (Vigueur DD 20 annule). Lancer des sorts ou se concentrer sur des sorts au contact d’un nishruu nécessite un test de Concentration (DD 20 + niveau du sort). De même, l’utilisation de toute compétence impliquant de la patience ou de la concentration nécessite un test de Concentration DD 20\nEssaim de morsures (Ext). Un nishruu inflige des dégâts automatiques à toute créature dont il occupe l’Espace à la fin de son déplacement, sans qu’aucun jet d’attaque ne soit nécessaire. Un nishruu ne menace pas les créatures qui se trouvent dans sa case et ne peut pas non plus lancer d’attaque d’opportunité avec son attaque d’essaim de morsures\nVulnérabilités (Sur). Une baguette d’absorption ou un anneau de détournement de sort mis en contact avec un nishruu a 5 % de chances de le détruire im- médiatement. Si l’objet n’absorbe pas le nishruu, il est annulé de la même manière que les autres objets magiques. Une poignée de sel jetée inflige 2d10 points de dégâts à un nishruu\nMagie de charge (Sur). Lorsqu’un nishruu est tué, son corps se dissipe. Tout objet magique chargé en contact avec lui au moment de sa mort gagne 1d6 charges supplémentaires. Le bonus d’amélioration d’un objet magique qui porte le coup fatal à un nishruu augmente de 1 pendant 1d6 jours', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2170);

