INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2171, 'Naug-Adar', 28, NULL, 'PV : 32 chacun (9 DV)\nHumain Vaasien Mage 9\nLM Humanoïde de taille moyenne\nInitiative : +6 ; Perception auditive +5, Détection +5\nLangues : Commun, Damarien, Draconique\nClasse d\'armure : 17, contact 13, pris au dépourvu 15\nRésistances : aux énergies destructrices\nJets de sauvegarde : Vig +4 (+6 si familier à 1,5m ou -), Réf +5, Vol +5\nVitesse de déplacement : 9m (6 cases)\nMêlée : dague +1 +3 (1d4/19-20/×2)\nAttaque de base/lutte : +4/+3\nSortilèges préparés du mage #1 (NLS 7ème) :\n5ème - $Arrêt cardiaque $(DD 17)\n4ème - $Tentacules noirs d\'Evard$ (+15 au test de lutte), $Orbe de froid$, $Confusion$ (DD 17)\n3ème - $Convocation de mort-vivants III$ (3)\n2ème - $Modification d\'apparence$†, $Détection de pensées$ (DD 16), $Détection faussée$†, $Détection de l\'invisiblilité$\n1er - $Résistances aux énergies destructives$†, $Armure de mage$†, $Projectile magique$, $Son imaginaire$ (silencieux, DD 13), $Coup au but$\n0 - $Détection de la magie$, $Son imaginaire$ (DD 13), $Manipulation à distance$, $Message$\nSorts préparés du mage #2 (NLS 7e) :\n5ème - $Téléportation$\n4ème - $Tentacules noirs d\'Evard$ (+15 au test de lutte), $Orbe de froid$, $Confusion$ (DD 17)\n3ème - $Boule de feu$ (2) (DD 16), image majeure (2) (DD 16)\n2ème - $Modification d\'apparence$†, $Détection de pensées$ (DD 16), $Détection faussée$†, $Détection de l’invisibilité$\n1er - $Résistances aux énergies destructives$†, $Armure de mage$†, $Projectile magique$, $Manipulation à distance$ (silencieux), $Coup au but$\n0 - $Détection de la magie$, $Son imaginaire$ (DD 13), $Manipulation à distance$, $Message$\n† déjà lancé\nÉquipement de combat : &baguette de projectiles magiques& (25 charges, NLS 7e)\nCaractéristiques : For 8, Dex 14, Con 12, Int 16, Sag 10, Cha 13\nParticularités : familier (rat), partage de sorts\nDons : #Vigilance# (si familier à moins de 1,5m), #Magie de guerre#, #Science de l\'initiative#, #Écriture de parchemins#, #Talent# (déguisement), #Incantation silencieuse#, #École renforcée# (divination)\nCompétences : Art de la magie+17 , Bluff +4, Concentration +13 (+17 pour les incatations sur la défensive), Connaissances (arcanes) +15, Déguisement +7 (+17 pour les jets de modification d’identité), Détection +5, Perception auditive +7, Psychologie +3\nPossessions : équipement de combat plus dague +1, &anneau de protection& +1, 12 po, 5 pa', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2171);

