SELECT 2174, 'Molosse satanique', 25, NULL, 'PV : 22 (4 DV)\nLM Extérieur de taille moyenne (maléfique, extraplanaire, feu, Loyal)\nInitiative : +5\nSens : vision dans le noir 18m, odorat ; Perception auditive +7, Détection +7\nClasse d\'armure : 16, contact 11, pris au dépourvu 15\nImmunités : au feu\nJets de sauvegarde : Vig +5, Réf +5, Lutte +4\nFaiblesse : vulnérabilité au froid\nVitesse de déplacement : 12m (8 cases)\nMêlée : Morsure +5 (1d8+1 plus 1d6 feu)\nAttaque de base/lutte : +4/+5\nOptions de combat : souffle\nCaractéristiques : For 13, Dex 13, Con 13, Int 6, Sag 10, Cha 6\nDons : #Science de l\'initiative#, #Course#, #Pistage#\nCompétences : Discrétion +13, Saut +12, Perception auditive +7, Détection +7, Survie +7 (+15 repérage par les sens)\nSouffle (Sur). cône de 3m, une fois tous les 2d4 rounds, dégâts 2d6 feu, Réflexes DD 13 demi', NULL, 88, 5, 1, 1, 1
