-- 2175 — Traqueur de Baine
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2175, 'Traqueur de Baine', 24, NULL, 'PV : 52 chacun (8 DV)\nRD : 10/argent\nBête de Baine* traqueur invisible LM élémentaire de grande taille (air, extraplanaire)\nInitiative : +8\nSens : vision dans le noir à 18m ; Perception auditive +13, Détection +13\nAura : présence effrayante (9m, DD 16)\nLangues : Auran, comprend le commun\nClasse d\'armure : 17, contact 13, pris au dépourvu 13\nImmunités : Peur, immunités élémentaires\nJets de sauvegarde : Vig +4, Réf +10, Vol +4\nVitesse de déplacement : Vol 9 m (6 cases) (parfait)\nMêlée : 2 coups +10 chacun (3d6+4)\nEspace : 3m ; Allonge 3m\nAttaque de base/lutte : +6/+14\nOptions de combat : Châtiment du bien 1/jour (+8 dégâts)\nActions spéciales : Se nourrir\nCaractéristiques : For 18, Dex 19, Con 14, Int 14, Sag 15, Cha 15\nParticularités : traits élémentaires, invisibilité naturelle, #Pistage# amélioré\nDons : #Attaques réflexes#, #Science de l\'initiative#, #Arme de prédilection# (coup)\nCompétences : Perception auditive +13, Déplacement silencieux +15, Fouille +13, Détection +13\nSe nourrir (Sur). Lorsqu’un Traqueur de Baine tue un adversaire humanoïde, il peut se nourrir du cadavre, dévorant à la fois la chair et la force vitale, en tant qu’action d’un tour complet. Se nourrir détruit le corps de la victime et empêche toute forme d’élévation ou de résurrection nécessitant une partie du cadavre. Il y a 50 % de chances qu’un souhait, un miracle ou un sort de résurrection véritable puisse ramener à la vie une victime dévorée. Si le test échoue, la victime dévorée ne peut être ramenée à la vie par la magie mortelle.\nLa créature progresse en Dé de vie en consommant des cadavres de cette manière. Pour chaque tranche de trois cadavres convenables dévorés par la créature, elle gagne 1 Dé de Vie. Son bonus à l’attaque et ses sauvegardes s’améliorent normalement pour une créature de son type et de son Dé de vie, et elle gagne des points de compétence, des prouesses et des améliorations de score de capacité normalement\nPrésence effrayante (Ext). Effet sonore d’un rayon de 9 m, DD inférieur à celui de la créature, Vol DD 16 ou silence magique. Lorsque la créature active ce pou- voir, ses yeux brillent d’un vert émeraude éclatant\nInvisibilité naturelle (Sur). Cette capacité est permanente, permettant à la créature de rester invisible même lorsqu’elle attaque. Cette capacité est inhérente et n’est pas soumise à un sort de négation de l’invisibilité\nPistage amélioré (Ext). La créature est un pisteur accompli et effectue des tests de Détection au lieu des habituels tests de Survie pour retracer le passage d’une créature', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2175);

