INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2176, 'Siar Egloth', 28, NULL, 'PV : 26 (10 DV)\nDrow mâle Magicien 14\nCM Humanoïde taille de moyenne (elfe)\nInitiative : +7\nSens : vision dans noir 36m ; Perception auditive +6, Détection +4\nLangues : Commun, draconique, langage des signes drow, Elfique, Commun des profondeurs ; lien empathique\nClasse d\'armure : 21, contact 13, pris au dépourvu 18\nImmunités : aux effets de sommeil magique\nRM : 20\nJets de sauvegarde : Vig +3, Réf +6, Lutte +7 (+9 contre les sorts, les capacités similaires aux sorts et les enchantements)\nVulnérabilités : à la lumière\nVitesse de déplacement : 9m (6 cases)\nMêlée : rapière de maître +9/+4 (1d6-1/18-20 plus poison)\nDistance : Arbalète à main de maître +8 (1d4/19-20 plus poison)\nAttaque de base : +7/+2\nLutte : +6\nMatériel de combat 4 doses de poison drow, insigne de la Maison Dhuurniv* , parchemin de boule de feu (NLS 10ème), baguette de mur de feu\n7ème (2/jour) - Rayon prismatique, Renvoi des sorts\n6ème (3/jour) - Défense magique, Brume acide, Dissipation suprême\n5ème (3/jour) - Débilité, Téléportation, Mur de force\n4ème (4/jour) - Confusion, Peau de pierre‡, Ténèbres des damnés, Terreur\n3ème (5/jour) - éclair (DD 17) (x2), Boule de feu (x2)\n2ème (5/jour)- Image miroir‡, Rayon ardent (2; +8 toucher à distance), Toile d\'araignée (x2)\n1er (5/jour) - Alarme†, Brume de dissimulation, Projectile magique, Rayon affaiblissant (+6 toucher à distance), Coup au but\n0 (6/jour)-aspersion acide (+6 toucher à distance), détection de la magie, détection du poison, main de mage, message, rayon de givre (+6 toucher à distance), lecture de la magie\n† déjà lancé ‡ déjà lancé si pas surpris\nCapacités de type sort (NLS 10ème) :\n1/jour - Lumières dansantes, Détection du bien, Détection de la magie, Ténèbres, Lueur féerique, Lévitation\nCaractéristiques : For 8, Dex 16, Con 10, Int 16, Sag 10, Cha 18\nParticularités : capable de remarquer les portes secrètes ou dissimulées, familier (araignée velue), utilisation du poison, partage des sorts\nDons : VigilanceB (si familier dans un rayon de 1,5m), Magie de guerre, Drow de haute naissance, Science de l\'initiative, Extension d’effet\nCompétences : Bluff +13, Concentration +17 (+21 pour les jets défensifs), Diplomatie +6, Déguisement +4 (+6 pour agir dans le personnage), Intimidation +6, Connaissances (arcanes) +11, Perception auditive +2, Fouille +4, Art de la magie +17, Détection +3\nPossessions : équipement de combat plus chemise en mithral +4, rapière de maître, arbalète de main de maître avec 20 carreaux, baguette de mur de feu, Anneau de lames d\'Akkabar, 53 po, 24 pa\nVulnérabilité à la lumière (Ext). Voir Lirdnolu\n* voir page 151', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2176);

