-- 2189 — Keevosen Nihili
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2189, 'Keevosen Nihili', 28, NULL, '66 PV (+11 dans l\'obscurité ou les ombres) (11 DV) ; guérison rapide 2\nFemme humaine refletFR roublard 2/magicien 5/adepte des ombres 4\nNM Humanoïde de taille moyenne\nInitiative : +6\nSens : vision nocturne, vision dans le noir 18 m ; Perception auditive +3, Détection +3\nLangues : Commun, draconique, nain, elfique\nClasse d\'armure : 27, contact 24, pris au dépourvu 21 dans les ténèbres ou les ombres ; Esquive ou CA 23, contact 20, pris au dépourvu 17 ; Esquive\nRésistances : à l\'évasion ; RM 22 (dans les ténèbres ou les ombres uniquement)\nJets de sauvegarde : Vig +10 (+14 dans les ténèbres ou les ombres), Réf +17 (+21 dans les ténèbres ou les ombres), Vol +13 (+17 dans les ténèbres ou les ombres) ; +1 contre les enchantements, les illusions, la nécromancie et les sorts ayant le descripteur ténèbres\nFaiblesse : perd ses capacités liées aux ombres (vision dans le noir, vitesse accrue, saut d\'ombre, guérison rapide, contrôle de la lumière, invisibilité, image d\'ombre) lorsqu\'il n\'est pas dans les ténèbres ou les ombres\nVitesse de déplacement : 9 m (6 cases), 15 m dans les ténèbres ou les ombres ; Saut d\'ombre\nMêlée : Épée courte +2 +15 (1d6+4/19-20) dans les ténèbres ou les ombres ou\nMêlée : Épée courte +2 +13 (1d6+2/19-20)\nDistance : arc court de maître +13 (1d6+2/×3) dans l\'obscurité ou les ombres ou\nDistance : arc court de maître +11 (1d6/×3)\nAttaque de base/lutte : +5/+5\nOptions d\'attaque : attaque sournoise +1d6\nActions spéciales : bouclier d\'ombres\nÉquipement de combat : potion de soins importants\nSorts de magicien préparés (NLS 9) :\n5e - $Magie des ombres$ (DD 18)\n4e - $Convocation d\'ombre$ (DD 18), $Puit d\'ombre$ (voir page 144)\n3e - $Lueur noire$ (DD 16), $Dissipation de la magie$, $Danse d\'acier$ (voir page 144), $Suggestion$ (DD 16)\n2e - $grâce féline$†, $Ténèbres$, $Invisibilité$, $Flèche acide de Melf$, $Image miroir$\n1er - $Alarme$†† (2), $Frayeur$ (DD 14), $Déguisement$, $Projectile magique$\n0 - $Détection de la magie$, $Son imaginaire$, $Manipulation à distance$, $Ouverture/fermeture$\n† déjà lancé\nCapacités de type sort (NLS 11e) :\n1/round - $Invisibilité$ (dans les ténèbres ou les ombres uniquement)\n3/jour - image fantôme (comme image miroir, 1d4+4 images, dans les ténèbres ou les ombres uniquement)\nCaractéristiques : For 10, Dex 22, Con 15 (17 dans les ténèbres ou les ombres), Int 17, Sag 8, Cha 14 (16 dans les ténèbres ou les ombres)\nParticularités : familier (aucun pour le moment), détection des pièges\nDons : #Esquive#, #Extension de durée#, #Magie insidieuse#B, #Magie pernicieuse#B, #Incantation rapide#, #Écriture de parchemins#B, #Magie de la Toile d\'ombre#, #Incantation silencieuse#, #Magie tenace# B, #Attaque en finesse#\nCompétences : Estimation +6, Équilibre +13, Bluff +13, Concentration +16, Diplomatie +11, Désamorçage +8, Renseignements +7, Discrétion +19, Intimidation +4, Saut +2, Connaissances (mystères) +11, Connaissances (plans) +14, Perception auditive +3, Déplacement silencieux +19, Crochetage +11, Fouille +8, Psychologie +4, Art de la magie+19, Détection +3, Acrobaties +11\nPossessions : équipement de combat plus bracelets d\'armure +3, épée courte +2, arc court de maître avec 20 flèches, &cape de résistance& +2, anneau du bélier, clé des portes de la loge. Remarque toutes les possessions de Keevosen sont des objets magiques de la Toile d\'ombre (voir encadré au chapitre 5, page 112)\nGrimoire Sorts préparés plus 0 — tous ; 1er niveau — charme-personne, armure de mage, filet d\'ombres, Lame persistante de Shelgarn, image silencieuse, convocation de monstres I, coup au but ; 2e niveau : griffes d\'ombres, détection faussée, masque d\'ombres, jet d\'ombres, convocation de monstres II ; 3e niveau : antidétection, renvoi de projectiles, convocation de monstres III ; 4e niveau : convocation de monstres IV ; 5e niveau : brume mortelle, convocation d\'ombres suprême, Gris manteau de Grimwald, main d\'ombres, convocation de monstres V\nGuérison rapide (Ext). Keevosen gagne 2 points de dégâts chaque round, à condition qu\'elle soit encore en vie et dans les ténèbres ou les ombres\nSaut d\'ombre (Mag). Dans une zone d\'illumination ombragée, Keevosen peut disparaître de l\'endroit où elle se trouve et réapparaître dans n\'importe quelle zone ombragée dans un rayon de 300 pieds, une fois tous les 2 rounds, en tant qu\'action de déplacement\nContrôle de la lumière (Mag). Lorsque Keevosen se trouve dans une zone d\'ombre, elle peut réduire le niveau de lumière dans un rayon de 30 mètres jusqu\'à 100 %. Cet effet réduit la portée effective globale de la vision mystique des personnages et des créatures dépendants de la lumière du même pourcentage. Un personnage se trouvant dans la zone affectée bénéficie d\'un bonus de +1 aux tests de Discrétion pour chaque réduction de 25 % de la lumière\nBouclier d\'ombres (Su). Keevosen peut s\'entourer d\'un globe de force violet-noir en tant qu\'action standard. Ce bouclier fonctionne comme un sort de $bouclier$, accordant un bonus de bouclier de +4 à la CA et absorbant les projectiles magiques lancés contre elle. De plus, il offre une dissimulation contre les attaques de mêlée et à distance. Elle peut l\'utiliser jusqu\'à 11 rounds par jour, mais ces rounds ne doivent pas nécessairement être consécutifs\nSpécial. Keevosen bénéficie d\'un bonus racial de +4 aux tests de Perception auditive et de Détection dans les ténèbres ou les ombres, ainsi que d\'un bonus racial de +8 aux tests de Discrétion et de Déplacement silencieux. Elle ne subit aucune pénalité due à un mauvais éclairage', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2189);

