INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2190, 'Loups-garou (forme hybride)', 28, NULL, 'PV : 45 (6 DV)\nRD : 10/argent\nLoup-garou humain mâle ou femelle, roublard 2/guerrier 2\nCM Humanoïde de taille moyenne (change de forme)\nInitiative : +5\nSens : vision nocturne, odorat ; Perception auditive +9, Détection +0\nLangues : commun ; empathie avec les loups\nClasse d\'armure : 25, contact 15, pris au dépourvu 20 ; Esquive, Souplesse du serpent\nRésistances : à l\'évasion\nJets de sauvegarde : Vig +10, Réf +12, Lutte +5\nVitesse de déplacement : 9 m (6 cases)\nMêlée : épée courte +1 +10 (1d6+4/19-20) et morsure +5 (1d6+1) ou\nMêlée : 2 griffes +9 chacune (1d4+3) et morsure +5 (1d6+1)\nDistance : arc court composite de maître +10 (1d6+2/×3)\nAttaque de base/lutte : +4/+7\nOptions d\'attaque : Combat en aveugle ; malédiction de la lycanthropie, attaque sournoise +1d6\nÉquipement de combat : potion de soins importants\nCaractéristiques : For 16, Dex 20, Con 16, Int 10, Sag 15, Cha 8\nCapacités spéciales détection des pièges\nDons : #Combat en aveugle#, #Esquive#, #Volonté de fer#, #Souplesse du Serpent#, #Pistage#, #Attaque en finesse#, #Arme de prédilection# (morsure)\nCompétences : Équilibre +7, Bluff +4, Escalade +5, Diplomatie +1, Renseignements +4, Discrétion +10, Intimidation +1, Saut +7, Perception auditive +9, Déplacement silencieux +10, Détection +9, Survie +2 (+6 pistage par odorat), Acrobaties +10, Utilisation d\'objets magiques +4\nPossessions : équipement de combat plus cuirassé clouté +1, bouclier +1, épée courte +1, arc court composite de maître (+2 bonus de Force) avec 20 flèches, cape de résistance +1\nMalédiction de la lycanthropie (Sur). Tout humanoïde ou géant touché par l\'attaque de morsure d\'un loup-garou doit réussir un jet de Vigueur DD 15 ou contracter la lycanthropie', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2190);

-- 2191 — Darcassan l'Habile
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2191, 'Darcassan l\'Habile', 28, NULL, 'PV : 56 (20 DV)\nRD : 10/+3 (100 PV max, Renvoi des projectiles)\nElfe du soleil mâle magicien (devin) 18 / expert 2\nCB Humanoïde de taille moyenne\nInitiative : +9\nSens : vision nocturne ; Perception auditive +17, Détection +17\nLangues : chondathien, commun, elfique, géant, gnome, sylvestre ; télépathie 18m\nClasse d\'armure : 26 (28 avec Invisibilité suprême), contact 18 (20 avec Invisibilité suprême), pris au dépourvu 26 (28 avec Invisibilité suprême)\nChance d\'échapper à une attaque 50 % (existence fantomatique)\nImmunités : aux effets de sommeil magiques\nJets de sauvegarde : Vig +4, Réf +9, Vol +14 ; +2 contre les enchantements\nVitesse de déplacement : 9 m (6 cases), vol 9 m (parfait)\nMêlée : épée longue +4 d\'&alerte& +11/+6 (1d8+4) avec arme magique suprême\nDistance : arc long +4 +16/+11 (1d6+4) avec arme magique suprême\nAttaque de base/lutte : +7/+7\nÉquipement de combat : plume de Quaal (fouet) (x2)\nSorts de magicien préparés : (NLS 18 ; 1d20+20 pour surmonter la RM)\n9e - (2+1) $Arrêt du temps$, $Main broyeuse de Bigby$, $Prémonition$\n8e - (3+1) Poing de Bigby, $Protection contre les sorts$, Anneau de foudre, $Moment de prescience$\n7e - (3+1) $œil prismatique$ (+6 au toucher à distance, DD 19), $Poigne de Bigby$, $Renvoi des sorts$,$Scrutation suprême$\n6e - (5+1) $Tempête acide$ (DD 22), $Zone d\'antimagie$, $Dissipation suprême$, $Flèche acide de Melf$ (2) (accélérée, +12 au toucher à distance), $Vision lucide$†\n5e - (5+1) $Main interposée de Bigby$, $Domination$ (DD 21), $Débilité$ (DD 21), $Matrice de sorts mineure$† (), $Télékinésie$ (+12 au toucher à distance, DD 21), $Lien télépathique de Rary$\n4e - (5+1) $Tentacules noirs d\'Evard$, $Invisibilité suprême$† (2), $Ecran de dissipation d’Otiluke$, $poussière d\'ombres$ (accru) (DD 21), $Cri$ (DD 20), $Lance Tonnerre$ (+13/+5 en mêlée)\n3e - (5+1) $Rapidité$, Eclair (2) (DD 19), $Arme magique suprême$ (2)†† , $Antidétection$ (jet de niveau du lanceur de sorts DD 28), $Renvoi des projectiles$†\n2e - (6+1) $Bélier$, $Lumière du jour$†, $Flèche acide de Melf$ (+12 en contact à distance), Brûlure (2)(DD 17), $Détection de l\'invisiblilité$, $Détection de pensées$ (DD 17)\n1er - (6+1) $Alarme$, $Projectile magique$ (4), $Bouclier$, $Esprit de l\'archer$\n0 - $Détection de la magie$, $Son imaginaire$ (DD 15), $Manipulation à distance$,$Fatigue$\n† déjà lancé\nÉcole interdite nécromancie\nCapacités magiques : (niveau d\'enchantement 20) :\nÀ volonté - $Clairaudience/clairvoyance$\nCaractéristiques : For 10, Dex 20, Con 11, Int 22, Sag 16, Cha 17\nDons : #Vigilance#, Augmentation d\'intensité, #Science de l\'initiative#, #Incantation rapide#, Écriture de parchemin, #Talent# (Bluff), #Attaque spéciale renforcée# (Psychologie), #École renforcée# (illusion), #Efficacité des sorts accrue#,#Magie de guerre#\nCompétences : Bluff +8, Concentration +26 (+30 pour lancer des sorts), Artisanat (reliure) +10, Artisanat (métallurgie) +10, Artisanat (taille de pierre) +10, Décryptage +25, Diplomatie +5, Discrétion +14, Connaissances (mystères) +25, Connaissances (histoire) +25, Perception auditive +21, Profession (scribe) +13, Fouille +14, Psychologie +10, Art de la magie+20, Détection +17\nPossessions : équipement de combat plus &amulette d\'armure naturelle& +3, &bracelets d\'armure& +5, &anneau de protection& +3, épée longue d\'alerte +1 (+4 avec arme magique suprême), arc long de maître (+4 avec arme magique suprême) avec 20 flèches, gants de dextérité +2, bandeau d\'intelligence +2, outils d\'artisan de maître\nExistence dans l\'ombre (Sur). Le mage Darcassan est à la fois semi-matériel et partiellement réel. Il peut traverser les objets physiques (mais pas les effets de force) tout comme une créature intangible. Toutes les attaques, même les sorts (à l\'exception des effets de force), ont 50 % de chances d\'échouer. Une arme spectral annule cette chance d\'échec. Une créature qui interagit avec lui peut tenter un jet de sauvegarde de Volonté DD 24 pour ne pas croire à la projection. Si elle y parvient, les attaques physiques de la projection (mais pas les sorts) n\'infligent que 80 % de leurs dégâts normaux. Vous pouvez calculer les dégâts réduits ou utiliser les valeurs suivantes : épée longue 1d8+2, arc long 1d6+2, attaque à mains nues 1d3–1. Dans une zone d\'antimagie, Darcassan perd sa vitesse de vol, sa capacité à traverser les objets solides, son bonus de déviation à la classe d\'armure et sa chance d\'échec. Il perd également son bonus racial de +8 aux tests de Perception auditive, de Fouille, de Détection et de Discrétion (voir ci-dessous).\nCompétences. Darcassan bénéficie d\'un bonus racial de +8 aux tests de Perception auditive, Fouille, Détection et Discrétion grâce à sa nature semi-matérielle. En tant qu\'elfe, il bénéficie d\'un bonus de +2 aux tests de Perception auditive, Fouille et Détection', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2191);

-- 2192 — Sombre tourmenteur avancé
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2192, 'Sombre tourmenteur avancé', 1, NULL, 'PV : 136 (16 DV)\nRD : 15/argent et magie\nCM Mort-vivant de taille moyenne\nInitiative : +12\nSens : vision dans le noir 18 m ; Perception auditive +23, Détection +23\nAura : profanation 6 m\nLangues : chondathien, commun, elfique ; télépathie 30 m\nClasse d\'armure : 33, contact 20, pris au dépourvu 25 ; Esquive\nImmunités : des morts-vivants\nRM : 24\nJets de sauvegarde : Vig +7, Réf +15, Lutte +16 avec aura de profanation\nFaiblesse : aversion pour la lumière du jour, ne peut être ressuscité, détruit à 0 PV ou moins\nVitesse de déplacement : 12m (8 cases), vol 18m (bon)\nMêlée : 2 griffes +18 chacune (1d6+9) avec aura de profanation et morsure +15 (1d6+4) avec aura de profanation et coup de queue +15 (2d4+4) avec aura de profanation\nAttaque de base/lutte : +8/+17\nOptions d\'attaque : Attaques réflexes ; absorption d\'énergie, saisie améliorée\nActions spéciales : invocation de morts-vivants\nCapacités magiques : (niveau de lanceur de sorts 16)\nA volonté - $ténèbres profondes$, détection de la magie, $détection de l\'invisibilité$, $flétrissement végétal$ (DD 18)\n3/jour - $Contagion$ (DD 18), $Dissipation suprême$, $Rapidité$, $Invisibilité$\n1/jour - $Doigt de mort$ (DD 21), $Immobilisation de monstre$ (DD 19), $Tempête de grêle$, $Changement de plan$ (DD 21)\nCaractéristiques : Force 29, Dex 27, Con -, Int 14, Sag 18, Cha 18\nParticularités : traits de mort-vivant\nDons : #Expertise du combat#, #Attaques réflexes#, #Esquive#, #Science de l\'initiative#, #Attaques multiples#, #Arme de prédilection# (griffe)\nCompétences : Équilibre + Concentration +23, Discrétion +27, Saut +20, Perception auditive +23, Détection +23, Acrobaties +29\nPossessions : bracelets d\'armure +3, anneau de protection +2, cape de Charisme +2, ceinture de force géante\nAversion pour la lumière du jour (Ext). S\'il est exposé à la lumière naturelle du jour (et non simplement à un sort de lumière du jour), un sombre tourmenteur subit une pénalité de -4 à tous ses jets d\'attaque, ses jets de sauvegarde et ses tests de compétence\nAura de profanation (Sur). Un sombre tourmenteur irradie dans un rayon de 6 mètres une aura de profanation totale, imprégnant son environnement d\'énergie négative. Cette capacité fonctionne de manière similaire au sort profanation, sauf que la malveillance du sombre tourmenteur est si grande qu\'il est considéré comme le sanctuaire d\'une puissance maléfique. Toutes les créatures mort-vivantes situées à moins de 20 pieds du sombre tourmenteur (y compris la créature elle-même) bénéficient d\'un bonus profane de +2 aux jets d\'attaque, aux jets de dégâts et aux jets de sauvegarde, ainsi que de +2 points de vie par dé de vie. (Les entrées relatives aux dés de vie, aux attaques et aux jets de sauvegarde du sombre tourmenteur indiquées ici incluent ces bonus profanes.) Les jets de Charisme effectués pour repousser les morts-vivants dans cette zone subissent une pénalité de -6.\nContrairement aux autres capacités surnaturelles, un sort de rejet du Mal ou un effet similaire peut dissiper l\'aura de profanation. Si l\'effet est dissipé, le sombre tourmenteur peut le réactiver en tant qu\'action gratuite lors de son prochain tour. Si le sombre tourmenteur pénètre dans une zone consacrée ou sanctifiée, son aura de profanation et l\'effet de consécration ou de sanctification sont supprimés tant qu\'il reste dans cette zone\nAbsorption d\'énergie (Su). Toute créature vivante contre laquelle le sombre tourmenteur remporte un test de lutte gagne deux niveaux négatifs. Le DD du jet de Vigueur pour supprimer un niveau négatif est de 20\nSaisie améliorée (Ex). Pour utiliser cette capacité, un sombre tourmenteur doit toucher un adversaire de taille Grande au maximum avec ses deux attaques de griffes. Il peut ensuite tenter d\'engager une lutte en tant qu\'action gratuite sans provoquer d\'attaques d\'opportunité. S\'il remporte le test de lutte, il établit une prise et peut utiliser son attaque d\'absorption d\'énergie\nInvocation de morts-vivants (Sur). Un sombre tourmenteur peut invoquer des créatures mortes-vivantes une fois par nuit : 3 à 6 ombres, 2 à 4 spectres ou 1 ombre supérieure. Les morts-vivants arrivent en 1d10 rounds et servent pendant 1 heure ou jusqu\'à ce qu\'ils soient libérés', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2192);

-- 2193 — Âme-en-peine vénérable
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2193, 'Âme-en-peine vénérable', 1, NULL, 'PV : 104 (16 DV)\nLM Mort-vivant de grande taille (immatériel)\nInit +12\nSens vision dans le noir 18 m, détection de la vie 18 m ; Perception auditive +25, Détection +25\nAura surnaturelle 9 m\nLangues commun, infernal\nCA 25, contact 25, pris au dépourvu 17 ; Esquive, Souplesse du serpent\nImmunités : des morts-vivants ; ne peut être blessé que par d\'autres créatures incorporelles, des armes magiques, des sorts, des capacités magiques ou des capacités surnaturelles\nRésistances : 50 % de chances d\'ignorer tout dégât provenant d\'une source corporelle (à l\'exception des effets de force et des attaques effectuées avec des armes spectrales)\nVig +5, Réf +13, Vol +14\nFaiblesse : ne peut pas être réanimé, impuissant à la lumière du soleil, détruit à 0 point de vie ou moins\nDéplacement vol 18m (12 cases) (bon) ; Attaque éclair ; peut traverser les objets solides (mais pas les effets de force) à volonté, déplacement silencieux (ne peut être entendu avec un test de Perception auditive sauf s\'il le souhaite)\nMêlée contact intangible +15 au contact (2d6 plus 1d8 points de Constitution)\nEspace 3 m\nAllonge : 3 m\nAttaque de base/lutte : +8/+12\nOptions d\'attaque Combat en aveugle, Attaques réflexes ; les attaques ignorent l\'armure naturelle, les armures et les boucliers (mais les bonus de déviation et les effets de force fonctionnent normalement), Drain de Constitution\nActions spéciales Création de rejetons\nParticularités traits de mort-vivant, traits d\'incorporé\nDons #Vigilance#, #Combat en aveugle#, #Attaques réflexes#, #Esquive#, #Science de l\'initiative#, #Arme naturelle supérieure# (contact incorporel), #Souplesse du Serpent#, #Attaque éclair#\nCompétences Diplomatie +12, Discrétion +23, Intimidation +25, Connaissances (religion) +20, Perception auditive +25, Fouille +22, Psychologie +23, Détection +25, Survie +6 (+8 après le pistage)\nDrain de Constitution (Sur). Une créature vivante touchée par l\'attaque de contact incorporelle d\'une âme-en-peine vénérable doit réussir un jet de Vigueur DD 25 ou subir 1d8 points de drain de Constitution. À chaque attaque réussie, l\'âme-en-peine vénérable gagne 5 points de vie temporaires\nCréation de rejetons (Sur). Un humanoïde tué par une âme-en-peine vénérable se relève après 1d4 rounds sous la forme d\'un spectre contrôlé par l\'âme-en-peine vénérable. Son corps reste intact et inanimé, mais son esprit est arraché de son cadavre et transformé. Il ne possède plus aucune des capacités qu\'il avait de son vivant\nImpuissance à la lumière du soleil (Ext). Les âmes-en-peine vénérables sont impuissantes à la lumière naturelle du soleil (et pas seulement à un sort de lumière du jour) et s\'enfuient lorsqu\'elles y sont exposées\nPerception de la vie (Sur). Une âme-en-peine vénérable détecte et localise les créatures vivantes dans un rayon de 18 mètres, comme si elle possédait le pouvoir de vision aveugle. Elle détecte également automatiquement la force de leur force vitale, comme si elle avait lancé perception de la mort\nAura surnaturelle (Sur). Les animaux, sauvages ou domestiques, peuvent sentir la présence surnaturelle d\'une âme-en-peine vénérable à une distance de 9 mètres. Ils ne s\'approchent pas volontairement à moins de cette distance et paniquent s\'ils y sont contraints ; ils restent paniqués tant qu\'ils se trouvent dans ce rayon', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2193);

-- 2194 — Darcassan le guerrier
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2194, 'Darcassan le guerrier', 28, NULL, 'PV : 136 (20 DV) avec la $transformation de Tenser$\nRD : 10/adamantite avec peau de pierre\nElfe du soleil mâle magicien (devin) 18 / expert 2\nCB Humanoïde de taille moyenne\nInitiative : +10\nSens : vision nocturne ; Perception auditive +17, Détection +17\nLangues : chondathien, commun, géant, gnome, elfique, sylvestre ; télépathie 18m\nClasse d\'armure : 30, contact 19, pris au dépourvu 30\nChance d\'échapper à une attaque 50 % (existence fantomatique)\nImmunités : aux effets de sommeil magiques\nJets de sauvegarde : Vig +13, Réf +12, Lutte +12 avec rapidité et transformation de Tenser ; +2 contre les enchantements\nVitesse de déplacement : 18 m (12 cases), vol 18 m (parfait) avec rapidité\nMêlée : épée à deux mains d\'alerte +4 +28/+28/+23/+18 (2d6+8) avec rapidité, arme magique suprême et transformation de Tenser\nDistance : arc long de force +4 +30/+30/+25/+20 (1d6+8) avec rapidité, arme magique suprême et transformation de Tenser\nAttaque de base : +20 avec la transformation de Tenser\nLutte : +24 avec la transformation de Tenser\nÉquipement de combat : anneau de contre-sorts (débilité)\nSorts de magicien préparés : (NLS 18 ; 1d20+20 pour surmonter la RM)\n9e - (2+1) $Arrêt du temps$, $Main broyeuse de Bigby$, $Prémonition$\n8e - (3+1) Poing de Bigby, $Protection contre les sorts$, Anneau de foudre, $Moment de prescience$\n7e - (3+1) $œil prismatique$ (+6 au toucher à distance, DD 19), $Poigne de Bigby$, $Renvoi des sorts$,$Scrutation suprême$\n6e - (5+1) $Tempête acide$ (DD 22), $Zone d\'antimagie$, $Dissipation suprême$, $Flèche acide de Melf$ (2) (accélérée, +12 au toucher à distance), $Vision lucide$†\n5e - (5+1) $Main interposée de Bigby$, $Domination$ (DD 21), $Débilité$ (DD 21), $Matrice de sorts mineure$† (Renvoi des projectiles), $Télékinésie$ (+12 au toucher à distance, DD 21), $Lien télépathique de Rary$\n4e - (5+1) $Tentacules noirs d\'Evard$, $Invisibilité suprême$† (2), $Ecran de dissipation d’Otiluke$, $poussière d\'ombres$ (accru) (DD 21), $Cri$ (DD 20), $Lance Tonnerre$ (+13/+5 en mêlée)\n3e - (5+1) $Rapidité$, Eclair (2) (DD 19), $Arme magique suprême$ (2)†† , $Antidétection$ (jet de niveau du lanceur de sorts DD 28), $Renvoi des projectiles$†\n2e - (6+1) $Bélier$, $Lumière du jour$†, $Flèche acide de Melf$ (+12 en contact à distance), Brûlure (2)(DD 17), $Détection de l\'invisiblilité$, $Détection de pensées$ (DD 17)\n1er - (6+1) $Alarme$, $Projectile magique$ (4), $Bouclier$, $Esprit de l\'archer$\n0 - $Détection de la magie$, $Son imaginaire$ (DD 15), $Manipulation à distance$,$Fatigue$\n† déjà lancé\nÉcole interdite nécromancie\nCapacités de type sort (NLS 15) :\nÀ volonté - $clairaudience/clairvoyance$\nCaractéristiques : Force 19, Dex 23, Con 19, Int 22, Sag 12, Cha 13 avec la transformation de Tenser\nDons : #Vigilance#, Augmentation d\'intensité, #Science de l\'initiative#, #Incantation rapide#, Écriture de parchemin, #Talent# (Bluff), #Attaque spéciale renforcée# (Psychologie), #École renforcée# (illusion), #Efficacité des sorts accrue#,#Magie de guerre#\nCompétences : Bluff +8, Concentration +26 (+30 pour lancer des sorts), Artisanat (reliure) +10, Artisanat (métallurgie) +10, Artisanat (taille de pierre) +10, Décryptage +25, Diplomatie +5, Discrétion +14, Connaissances (mystères) +25, Connaissances (histoire) +25, Perception auditive +21, Profession (scribe) +13, Fouille +14, Psychologie +10, Art de la magie+20, Détection +17\nPossessions : équipement de combat plus amulette d\'armure naturelle +3, bracelets d\'armure +5, anneau de protection +3, épée à deux mains d\'alerte +1 (+4 avec arme magique suprême), arc long de maître de force (+4) (+4 avec arme magique suprême) avec 20 flèches, gants de dextérité +2, bandeau d\'intelligence +2\nExistence dans l\'ombre (Sur). Le mage Darcassan est à la fois semi-matériel et partiellement réel. Il peut traverser les objets physiques (mais pas les effets de force) tout comme une créature intangible. Toutes les attaques, même les sorts (à l\'exception des effets de force), ont 50 % de chances d\'échouer. Une arme spectral annule cette chance d\'échec. Une créature qui interagit avec lui peut tenter un jet de sauvegarde de Volonté DD 24 pour ne pas croire à la projection. Si elle y parvient, les attaques physiques de la projection (mais pas les sorts) n\'infligent que 80 % de leurs dégâts normaux. Vous pouvez calculer les dégâts réduits ou utiliser les valeurs suivantes : épée longue 1d8+2, arc long 1d6+2, attaque à mains nues 1d3–1. Dans une zone d\'antimagie, Darcassan perd sa vitesse de vol, sa capacité à traverser les objets solides, son bonus de déviation à la classe d\'armure et sa chance d\'échec. Il perd également son bonus racial de +8 aux tests de Perception auditive, de Fouille, de Détection et de Discrétion (voir ci-dessous).\nCompétences. Darcassan bénéficie d\'un bonus racial de +8 aux tests de Perception auditive, Fouille, Détection et Discrétion grâce à sa nature semi-matérielle. En tant qu\'elfe, il bénéficie d\'un bonus racial de +2 aux tests de Perception auditive, Fouille et Détection', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2194);

-- 2195 — Bralani avancé
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2195, 'Bralani avancé', 25, NULL, 'PV : 86 (10 DV)\nRD : 10/fer froid ou mal\nCB Extérieur de taille moyenne (chaotique, extraplanaire, bon)\nInitiative : +7\nSens : vision dans le noir 18 m, vision nocturne ; Perception auditive +17, Détection +17\nLangues : céleste, draconique, infernal ; don des langues (NLS 14e)\nClasse d\'armure : 19, contact 13, pris au dépourvu 16\nImmunités : à l\'électricité, la pétrification\nRésistances : au froid 10, au feu 10\nRM : 17\nJets de sauvegarde : Vig +11, Réf +12, Lutte +9\nVitesse de déplacement : 12m (8 cases), vol 30m (parfait)\nMêlée : cimeterre +1 béni +15/+10 (1d6+7/18-20)\nDistance : arc long composite +1 béni +14/+9 (1d8+1/×3)\nAttaque de base/lutte : +10/+14\nOptions d\'attaque : #Combat en aveugle#\nActions spéciales : transformation, coup de vent\nCaractéristiques : magiques (niveau d\'enchantement 6) :\nÀ volonté - $flou$, $charme-personne$ (DD 14), $bourrasque$ (DD 15), $image miroir$, $mur de vent$\n2/jour - $éclair$ (DD 16), $soins importants$ (DD 16)\nCaractéristiques : Force 18, Dex 16, Con 19, Int 13, Sag 14, Cha 14\nDons : #Vigilance#, #Combat en aveugle#, #Science de l\'initiative#, #Réflexes surhumains#\nCompétences : Équilibre +5, Concentration +15, Diplomatie +4, Évasion +13, Dressage +12, Discrétion +13, Saut +16, Perception auditive +17, Déplacement silencieux +13, Équitation +15, Psychologie +12, Détection +17, Acrobaties +15\nPossessions : cimeterre béni +1, +1 arc long composite béni (+4 bonus de Force) avec 20 flèches\nTransformation (Sur). Un bralani peut passer de sa forme humanoïde à sa forme cyclone en tant qu\'action standard à volonté. Cette capacité fonctionne comme un sort de métamorphose lancé sur lui-même (niveau de lanceur de sorts 6), sauf qu\'un bralani ne regagne pas de points de vie lorsqu\'il change de forme et ne peut prendre que la forme d\'un cyclone.\nSous sa forme humanoïde, il ne peut ni voler ni utiliser son souffle cyclone, mais il peut utiliser ses capacités magiques et ses armes. Sous sa forme cyclone, il peut voler, effectuer des attaques de choc et des attaques de souffle cyclone, et utiliser ses capacités magiques. Un bralani reste sous une forme jusqu\'à ce qu\'il choisisse d\'en prendre une nouvelle. Un changement de forme ne peut être dissipé, et le bralani ne reprend pas une forme particulière lorsqu\'il est tué. Un sort de vision lucide révèle les deux formes simultanément\nCoup de vent (Sur) Sous sa forme cyclone, un bralani peut attaquer avec une rafale de vent dévastatrice, infligeant 3d6 points de dégâts dans une ligne de 6 mètres (réflexe DD 19 demi-dégâts).', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2195);

-- 2196 — Ghaele
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2196, 'Ghaele', 25, NULL, 'PV : 65 (10 DV)\nRD : 10/fer froid et mal\nCB Extérieur de taille moyenne (chaotique, extraplanaire, bon)\nInitiative : +4\nSens : vision dans le noir 18 m, vision nocturne ; Perception auditive +16, Détection +16\nAura : protectrice 6 m\nLangues : céleste, draconique, infernal ; don des langues (NLS 14e)\nClasse d\'armure : 24, contact 10, pris au dépourvu 24\nImmunités : contre l\'électricité, la pétrification\nRésistances : au froid 10, au feu 10 ; RM 28\nJets de sauvegarde : Vig +9, Réf +7, Lutte +10\nVitesse de déplacement : 15m (10 cases), vol 45m (parfait)\nMêlée : épée à deux mains +4 &bénie& +21/+16 (2d6+14/19-20)\nDistance : 2 rayons de lumière +10 contact à distance (2d12, aucune RD sur ces dégâts)\nAttaque de base/lutte : +10/+17\nOptions d\'attaque : Science du désarmement, Science du croc-en-jambe\nActions spéciales : transformation, regard\nSorts de prêtre préparés (NLS 14 ; jet de sauvegarde DD 13 + niveau du sort) :\n7e - $Régénération$, résurrection, mot du chaosD (DD 20, NLS 15)\n6e - Chaîne d\'éclairsD (DD 19), Premiers secours (2), $Festin des héros$\n5e - $Rejet du Mal$ (+17 en mêlée, DD 18), Dissipation de la loiD (+17 en mêlée, DD 18, NLS 15e), Cercle de guérison, $Force du colosse$\n4e - $Marteau du chaos$D (DD 17, NLS 15e), $Soins intensifs$ (2, DD 17), $Liberté de mouvement$, $Neutralisation du poison$\n3e - soins importants (2, DD 16), $Lumière du jour$, négation de l’invisibilité, $Cercle magique contre le Chaos$D (NLS 15e), $Prière$\n2e - $Consécration$, $Soins modérés$ (2, DD 15), brise-arme, $Silence$, $Arme spirituelle$ (2, +17 en mêlée, +10 à distance)\n1er - $Bénédiction$ (2), $Soins légers$ (2, DD 14), $Faveur divine$, $Protection contre la loi$ (NLS 15e), $Bouclier de la foi$\n0 - $Soins superficiels$ (2, DD 13), $Assistance divine$ (2), $Réparation$, $Lecture de la magie$\nD : sort de domaine. Divinité : aucune. Domaines : air, chaos\nCapacités de type sort (NLS 12) :\nÀ volonté - $aide$, $charme-monstre$ (DD 18), $couleurs dansantes$ (DD 15), $compréhension des langues$, $flamme éternelle$, $soins légers$ (DD 15), $lumières dansantes$, $détection du Mal$, $détection de pensées$ (DD 16), $déguisement$, $dissipation de la magie$, $immobilisation de monstre$ (DD 19), $invisibilité suprême$ (sur soi uniquement), $image accomplie$ (DD 17), $détection de l\'invisibilité$, $téléportation suprême$ (sur soi-même et 25 kg d\'objets uniquement)\n1/jour - $éclair multiple$ (DD 20), $rayon prismatique$ (DD 21), $Mur de force$\nCaractéristiques : Force 25, Dex 10, Con 15, Int 16, Sag 17, Cha 18\nDons : #Expertise du combat#, #Science du désarmement#, #Science de l\'initiative#, #Science du Croc-en-jambe#\nCompétences : Concentration +15, Diplomatie +6, Évasion +13, Dressage +17, Discrétion +13, Connaissances (histoire) +16, Connaissances (religion) +16, Perception auditive +16, Déplacement silencieux +13, Équitation +15, Psychologie +16, Détection +16\nPossessions : épée à deux mains +4 &bénie&\nRegard (Sur). Sous forme humanoïde uniquement. Tue les créatures maléfiques de 5 DV ou moins, portée 18 mètres, jet de Volonté DD 18 pour annuler. Même en cas de jet de sauvegarde réussi, la cible est affectée par l’équivalent du sort terreur pendant 2d10 rounds. Les créatures qui ne sont pas mauvaises (ou celles qui le sont mais ont plus de 5 DV) sont affectées par l’effet de terreur si elles ratent leur jet de Volonté (DD 18). Dans le cas contraire, le regard du ghaele ne leur fait rien. Les DD de sauvegarde sont liés au Charisme.\nRayon de lumière (Ext). Sous forme de globe lumineux, le ghaele peut tirer des rayons de lumière (portée 90 mètres). Cette attaque ignore tous les type de réduction des dégâts.\nTransformation (Sur). Le ghaele peut passer de sa forme d’humanoïde à celle de globe lumineux (et inversement) par une action simple. Sous forme humanoïde, il ne peut ni voler ni tirer des rayons de lumière. Par contre, il peut attaquer physiquement et faire appel à son attaque de regard, à ses pouvoirs magiques et à ses sorts. Sous forme de sphère lumineuse, il peut voler, projeter des rayons de lumière et utiliser ses pouvoirs magiques, mais pas se servir de son attaque de regard ni de ses sorts.\nLe ghaele conserve la forme choisie aussi longtemps qu’il le souhaite. Ses transformations ne peuvent pas être dissipées et il ne change pas de forme en mourant. Par contre, le sort vision lucide révèle ses deux aspects simultanément, superposés l’un à l’autre.\nAura de protection (Sur). Toute créature à moins de 6 mètres du ghaele bénéficie d’un bonus de parade de +4 à la CA et d’un bonus de résistance de +4 aux jets de sauvegarde contre les attaques et effets créés par des créatures d’alignement mauvais. Cette aura combine par ailleurs les effets des sorts $cercle magique contre le Mal$ et $globe d’invulnérabilité partielle$, chacun sur une zone de 6 mètres de rayon (niveau de lanceur de sorts égal au nombre de DV du ghaele). L’aura peut être dissipée, mais le ghaele n’a besoin que d’une action libre pour la réactiver dès son prochain tour de jeu. (Les bonus conférés par le cercle ne sont pas inclus dans le profil ci-dessus.)\nDon des langues (Sur). Les ghaeles peuvent converser avec toute créature parlant un langage, quel qu’il soit, comme s’ils bénéficiaient constamment du sort don des langues (niveau 14 de lanceur de sorts). Ce pouvoir fonctionne en permanence.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2196);

-- 2197 — Tigre sanguinaire
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2197, 'Tigre sanguinaire', 23, NULL, 'PV : 120 (16 DV)\nRD : 10/magie\nCM bête magique de grande taille (animal amélioré, extraplanaire)\nInitiative : +2\nSens : vision dans le noir 18 m, vision nocturne, odorat ; Perception auditive +6, Détection +7\nLangues : —\nClasse d\'armure : 17, contact 11, pris au dépourvu 15\nRésistances : au froid 10, au feu 10 ; RM 21\nJets de sauvegarde : Vig +13, Réf +12, Lutte +6\nVitesse de déplacement : 12m (8 cases) ; Course\nMêlée : 2 griffes +20 chacune (2d4+8) et morsure +14 (2d6+4)\nEspace occupé/allonge : 3m/1,5m\nAttaque de base : +12 ; Grp +24\nOptions d\'attaque : bond, étreinte, pattes arrière 2d4+4, Châtiment du bien 1/jour (+16 dégâts)\nCaractéristiques : Force 27, Dex 15, Con 17, Int 3, Sag 12, Cha 10\nDons : #Vigilance#, #Arme naturelle supérieure# (morsure), #Arme naturelle supérieure# (griffe), #Course#, #Discret#, #Arme de prédilection# (griffe)\nCompétences : Discrétion +7 (+11 dans les hautes herbes ou les broussailles épaisses), Saut +16, Perception auditive +6, Déplacement silencieux +11, Détection +7, Natation +10\nBond (Ext). Lorsque le tigre sanguinaire charge un adversaire, il peut porter une attaque à outrance, y compris deux coups de pattes arrière\nÉtreinte (Ext). Pour utiliser ce pouvoir, le tigre sanguinaire doit réussir une attaque de morsure. Il peut alors tenter d’engager une lutte par une action libre sans provoquer d’attaque d’opportunité. S’il remporte le test de lutte opposé, il agrippe sa victime, qu’il peut lacérer avec ses pattes arrière\nPattes arrière (Ext). Bonus à l’attaque +18 corps à corps, dégâts 2d4+4\nCompétences. Le tigre sanguinaire bénéficie d’un bonus racial de +4 aux tests de Déplacement silencieux et de Discrétion. * Dans les épais fourrés ou les hautes herbes, le bonus aux tests de Discrétion passe à +8', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2197);

-- 2198 — Our céleste
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2198, 'Our céleste', 23, NULL, 'PV : 105 (12 DV)\nRD : 10/magie\nLG Grande bête magique (animal augmenté, extraplanaire)\nInitiative : +1\nSens : vision dans le noir 18m, vision nocturne, odorat ; Perception auditive +10, Détection +10\nLangues : —\nClasse d\'armure : 17, contact 10, pris au dépourvu 16\nRésistances : à l\'acide 10, au froid 10, à l\'électricité 10 ; RM 17\nJets de sauvegarde : Vig +12, Réf +9, Lutte +9\nVitesse de déplacement : 12m (8 cases) ; Course\nMêlée : 2 griffes +19 chacune (2d4+10) et morsure +13 (2d8+5)\nEspace occupé/allonge : 3m/1,5m\nAttaque de base : +9 ; Grp +23\nOptions d\'attaque : étreinte, Châtiment du mal 1/jour (+12 dégâts)\nCaractéristiques : Force 31, Dex 13, Con 19, Int 3, Sag 12, Cha 10\nDons : #Vigilance#, #Endurance#, #Course#, #Robustesse#, #Arme de prédilection# (griffe)\nCompétences : Perception auditive +10, Détection +10, Natation +13\nÉtreinte (Ext). Pour utiliser cette capacité, un ours redoutable doit toucher avec une attaque de griffe. Il peut alors tenter d\'engager une lutte en tant qu\'action gratuite sans provoquer d\'attaques d\'opportunité', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2198);

