-- 2200 — Crocgivre
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2200, 'Crocgivre', 23, NULL, 'PV : 279 (18 DV) ; guérison rapide 5\nLoup arctique légendaire, avancé\nNM bête magique (froid) de Très grande taille\nInitiative : +7\nSens : vision dans le noir 18m, vision nocturne, odorat; Perception auditive +15, Détection +15\nAura : présence effrayante (6m, DD 21)\nLangues : géant, commun\nClasse d\'armure : 24, contact 11, pris au dépourvu 21\nImmunisé contre le froid, la terreur, les sorts et capacités affectant l\'esprit\nJets de sauvegarde : Vig +24, Réf +17, Lutte +13\nFaiblesse : vulnérabilité au feu\nVitesse de déplacement : 15m (10 cases)\nMêlée : morsure +30 (2d6+21 plus 1d6 de froid)\nEspace : 4,5m ; Allonge 3m\nAttaque de base/lutte : +18/+40\nOptions d\'attaque : Science du renversement, Attaque en puissance, Croc-en-jambe\nActions spéciales : Souffle\nCaractéristiques : Force 39, Dex 17, Con 30, Int 11, Sag 15, Cha 14\nDons : #Vigilance#, #Science de l\'initiative#B, #Science du renversement#, #Volonté de fer#, #Attaques multiples#B, #Attaque en puissance#, Charge en en puissance, #Discret#, #Pistage#\nCompétences : Discrétion +8 (+15 dans la neige et la glace), Perception auditive +12, Déplacement silencieux +15, Détection +15, Survie +10 (+14 pistage par l\'odorat)\nSouffle (Sur). Cône de froid de 4,5 m, une fois toutes les 1d4 rounds, dégâts 4d6 de froid, DD de Réflexions 29 pour moitié\nPrésence effrayante (Ext). Crocgivre peut inspirer la terreur en grognant ou en hurlant. Les créatures situées à moins de 20 pieds du loup arctique qui ont 17 DV ou moins doivent tenter un jet de Volonté DD 21. En cas de succès, la cible est immunisée contre la présence effrayante du Frostbite pendant 24 heures. En cas d\'échec, les créatures avec 4 DV ou moins sont paniquées jusqu\'à ce que Frostbite soit hors de portée. Celles avec 5 DV ou plus sont secouées jusqu\'à ce que Frostbite soit hors de portée\nCroc-en-jambe (Ext) Si Frostbite touche avec une attaque de morsure, il peut tenter de faire trébucher un adversaire (+22 au jet de sauvegarde) en tant qu\'action gratuite sans effectuer d\'attaque de contact ni provoquer d\'attaque d\'opportunité. Si la tentative échoue, l\'adversaire ne peut pas réagir pour faire trébucher Frostbite', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2200);

