INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2201, 'Gardien de la croisée des chemins', 26, NULL, 'PV : 88 (16 DV)\nRD : 5/fer froid\nCM fée (incorporelle) de Très Grande taille\nInitiative : +1\nSens : vision nocturne ; Perception auditive +25, Détection +25\nLangues : télépathie 30 m\nClasse d\'armure : 11, contact 11, pris au dépourvu 10 ; Esquive, Souplesse du serpent\nChance de manquer 50 % (incorporel)\nJets de sauvegarde : Vig +7, Réf +11, Vol +16\nFaiblesse : Doit rester à moins de 15 mètres du carrefour\nVitesse de déplacement : 6m (4 cases), vol 12m (parfait), natation 6m\nMêlée : contact incorporel +9 (1d12)\nEspace : 4,5m ; Allonge 4,5m\nAttaque de base : +8 ; Grp —\nOptions d\'attaque : Attaques réflexes\nActions spéciales : invoquer des satyres\nCaractéristiques : Force —, Dex 13, Con 14, Int 15, Sag 18, Cha 15\nDons : #Vigilance#, #Attaques réflexes#, #Expertise du combat#, #Esquive#, #Volonté de fer#, #Souplesse du Serpent#\nCompétences : Bluff +21, Décryptage +21, Diplomatie +6, Déguisement +2 (+4 pour agir dans le personnage), Intimidation +23, Connaissances (nature) +23, Perception auditive +25, Psychologie +23, Détection +25, Survie +23 (+25 en environnement naturel au-dessus du sol)\nInvocation de satyres (Ext) Une fois par jour, un gardien de carrefour peut tenter d\'invoquer 1d3 satyres avec des flûtes, avec 35 % de chances de réussite. Cette capacité dure 1 heure', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2201);

