INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2202, 'Azalar Fauconnier', 26, NULL, 'PV : 31 (7 DV)\nHumain mâle féérique rodeur 7\nNB Fée de taille moyenne\nInitiative : +4\nSens : vision nocture ; Perception +9, Détection +9\nLangues : Chondathien, Commun, Sylvanien\nClasse d\'armure : 15, contact 10, pris au dépourvu 15\nImmunités : sorts et capacités affectant l\'esprit\nRésistances : aux énergies destructrices\nJets de sauvegarde : Vig +5, Réf +5, Vol +4\nVitesse de déplacement : de déplacement 12m avec grand pas (8 cases), base 30m ; woodland stride\nMêlée : +1 épée longue +9/+4 (1d8+3/19-20) et +1 épée courte +9/+4 (1d6+1/19-20)\nDistance : Arc long composite +7/+2 (1d8+3/×3)\nAttaque de base/lutte : +7/+10\nOptions d\'attaque : s ennemi juré Zhentarim +4, ennemi juré bêtes magiques +2\nSorts de rôdeur préparés (NLS 3e) :\n1er - résistance aux énergies destructrices†, $grand pas$†\n† déjà lancé\nCapacités de type sort (NLS 7e) :\n1/jour - charme personne (DD 13)\nCaractéristiques : For 16, Dex 10, Con 11, Int 10, Sag 14, Cha 14\nParticularités : compagnon animal (aucun), empathie sauvage +9 (+5 bêtes magiques)\nDons : #Vigilance#, #Endurance#, #Science de l\'Initiative#, #Science du Combat à deux armes# (armure légère uniquement), #Discret#, #Pistage#, #Combat à deux armes# (armure légère uniquement).\nCompétences : Concentration +5, Dressage +8, Discrétion +9, Connaissance (nature) +5, Perception +9, Déplacement silencieux +9, Equitation +7, Fouille +5, Langue parlée (2), Détection +9, Saut +8 (+12 avec grand pas), Survie +7 (+9 en milieu naturel ou pour pister ; +11 pour pister en milieu naturel)\nPossessions : chemise en mithral +', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2202);

