-- 2205 — Satyre
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2205, 'Satyre', 26, NULL, 'Fée de taille M\nPV : 22 (5 DV) ; RD 5/fer froid\nInitiative : +1\nSens : vision nocturne\nClasse d\'armure : 15, contact 11, pris au dépourvu 14\nRéf +5, Vig +2, Lutte +5\nVitesse de déplacement : de déplacement 12m (8 cases)\nMêlée : coup de tête +2 (1d6) et dague -3 (1d4, 19-20/x2)\nDistance : arc court (+3 distance, 1d6/x3)\nAttaque de base/lutte : +2/+2\nAttaques spéciales : flûte de Pan\nCaractéristiques : For 10, Dex 13, Con 12, Int 12, Sag 13, Cha 13\nDons : #Esquive#, #Souplesse du Serpent#, #Vigilance# (S)\nCompétences : Bluff +9, Connaissances (nature) +9, Déguisement +1 (+3 pour tenir un rôle), Déplacement silencieux +13, Détection +15, Diplomatie +3, Discrétion +13, Intimidation +3, Perception auditive +15, Représentation (instruments à vent) +9, Survie +1 (+3 au- dessus de terre)\nFlûte de Pan (Sur). Le satyre peut jouer plusieurs airs enchantés sur sa flûte de Pan. En général, seul un satyre par groupe possède un tel instrument de musique. Dès qu’il se met à jouer, toutes les créatures distantes de 18 mètres ou moins (satyres exceptés) doivent réussir un jet de Volonté (DD 13) pour ne pas être affectées par l’un des effets suivants (niveau 10 de lanceur de sorts ; au choix du satyre) : charme- personne, $sommeil$ ou $terreur$. La flûte ne possède aucun pouvoir entre les mains de quelqu’un d’autre. Toute créature réussissant son jet de Volonté (contre quelque effet que ce soit) ne peut plus être affectée par cette flûte pendant 24 heures. Le DD de sauvegarde est lié au Charisme. Le satyre utilise souvent sa flûte de Pan pour charmer les femmes particulièrement séduisantes, ou pour endormir un groupe d’aventuriers et leur voler leurs objets de valeur.\nCompétences. Le satyre bénéficie d’un bonus racial de +4 aux tests de Déplacement silencieux, Détection, Discrétion, Perception auditive et Représentation', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2205);

-- 2209 — chasseur Maug
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2209, 'chasseur Maug', 3, NULL, 'PV : 69 (7 DV)\nCréature artificielle 2 / guerrier 5\nLN créature artificielle de grande taille (extraplanaire)\nInitiative : +2\nSens : vision dans le noir sur 18m, vision nocture ; Perception auditive + 7, Détection + 7\nLangues : Commun, Draconique, Géant\nClasse d\'armure : 28, contact 10, pris au dépourvu 27\nImmunités : des constructions\nRM : 19\nJets de sauvegarde : Vig +4, Réf +3, Lutte + 1\nFaiblesse : Ne peut pas guérir les dégâts, ne peut pas être relevé ou ressuscité\nVitesse de déplacement : 12m (8 cases) (ne peut pas courir)\nMêlée : Épée +1 à deux lames +12/+7 (2d6+8/19-20) ou Mêlée fronde +10 (1d8+7)\nEspace : 3m ; Allonge 3m\nAttaque de base/lutte : +6/+15\nOptions de combat : Enchaînements, Grande Enchainements, Science de la destruction (avec pulvériser, voir ci-dessous), Attaque en puissance\nActions spéciales : pulvériser, bras de poussée Équipement de combat greffe de maug (bras de poussée)\nCaractéristiques : For 21, Dex 15, Con -, Int 13, Sag 11, Cha 12\nParticularités : constructions, greffes, réparation rapide\nDons : #Vigilance#, #Enchaînement#, Succession d’enchainement, Amélioration de la destruction, #Attaque en puissance#, #Combat à deux armes#, Arme prédilection (épée à deux lames)\nCompétences : Artisanat (forgeron). +9, Artisanat (tailleur de pierre) +14* , Intimidation +8, Saut +7, Connaissance (architecture et ingénierie) +10* , Perception auditive +7, Profession (ingénieur de siège) +5, Fouille +1 (+3 pour les portes secrètes ou les com- partiments cachés), Détection +7, Survie +5 Possessions équipement de combat plus plaque complète +3, épée à deux lames +1\nPulvériser (Sur). Trois fois par jour, sous forme d’action standard, un maug peut toucher un objet et annuler sa dureté pendant 1d4 rounds (Vigueur DD 18 annule). Ce pouvoir peut affecter un objet d’un volume maximal de 1 000 pieds cubes (un cube de 3m) ; si l’objet est plus grand, seul un cube de 3m est affecté. Les objets non magiques sans surveillance ne bénéficient pas de jet de sauvegarde. Si une créature tient, porte ou transporte l’objet, le maug doit réussir une attaque de toucher en mêlée. Cette attaque ne provoque pas d’attaque d’opportunité\nRéparation rapide (Ext). Un maug qui se repose pendant 1 heure complète répare 1 point de dégâts, tant qu’il a au moins 1 point de vie. La réparation rapide ne permet pas au maug de faire repousser ou de rattacher les parties de son corps qu’il a perdues. Un personnage peut aider un maug à s’auto-réparer par un test d’Artisanat (taille de pierre) (DD 15). Si le test est réussi, le maug répare 2 points de vie par heure de repos. Fournir de l’aide compte comme une activité légère pour le personnage aidant, et un personnage ne peut aider qu’un seul maug à la fois. Un maug ne peut pas aider à sa propre réparation.\nGreffe de Maug (bras de poussée) (Ext) Un bras de poussée est un appendice de pierre en forme de piston qui se termine par une main de pierre droite et aplatie. Une fois par round, en tant qu’action d’at- taque, le maug peut effectuer une attaque au toucher en mêlée contre une cible située à moins de 5 pieds qui ne provoque pas d’attaque d’opportunité. S’il touche, le maug et son adversaire font des tests de Force opposés comme si le maug avait effectué une attaque de ruée sur les taureaux. En plus des bonus normaux, le maug ajoute un bonus spécial de +5 à ce jet. Si le maug gagne, le défenseur est repoussé de 5 pieds plus 1 pied supplémentaire par point de plus que le résultat du maug. Le maug ne se déplace pas avec le défenseur bousculé.\nPour bousculer des objets sans surveillance, le bras de bousculade a une force de 31. bras de bousculade a une force de 31. Le bras pousseur peut pousser les créatures et les objets en ligne droite uniquement', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2209);

-- 2224 — Nazrym
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2224, 'Nazrym', 28, NULL, 'PV : 39 (6 DV)\nhumain mâle ; Clerc 6 (de Baine)\nLM Humanoïde de taille moyenne\nInitiative : +5 ; Perception auditive +3, Détection +3\nLangues : Commun\nClasse d\'armure : 18, contact 11, pris au dépourvu 17 Résistance aux énergies destructrices Vig +6, Réf +3, Lutte +8\nVitesse de déplacement : 9 m (6 cases)\nMêlée : fléau +2, +8 (1d8+4)\nAttaque de base/lutte : +4/+6\nActions spéciales : Intimidation des mort-vivants 2/ jour (-1, 2d6+5, 6ème), incantation spontanée (infliger des sorts) (+6 toucher en mêlée)\nÉquipement de combat : parchemin de guérison des blessures graves et de fusion avec la pierre (NLS 6ème), 2 potions de résistance aux énergies destructrices, potion de restauration mineure\nSorts de clercs préparés (NLS 4)\n3ème - cécité/surdité (DD 16), Dissipation de la magie, cercle magique contre bonD (NLS 7ème), invocation de monstre III (molosse satanique, reste 6 rds.)\n2ème - maintien de la personne (DD 15), résistance à l’énergie (10 pts, 60 min), éclatementD (DD 15), Silence (DD 15), invocation de monstre II (1d3 corbeaux fiélons, reste 6 rds)\n1er - Baine (DD 14), résistance aux énergies destructrices†, Protection contre le bienD (NLS 7ème), Bouclier de la foi (bonus de +3), invocation de monstre I (corbeau fiélon, reste 6 cases)\n0 - guérison des blessures légères, Détection de la magie, Détection du poison, Assistance divine, Résistance\nD : sort de domaine. Divinité : Baine. Domaines : Destruction, Mal\n† déjà lancé\nCaractéristiques : For 14, Dex 12, Con 13, Int 10, Sag 16, Cha 8\nParticularités : aura du mal\nDons : Magie de guerre, Initiative améliorée, Maniement d’une arme de guerre (fléau), Science de la robustesse\nCompétences : Bluff +3, Concentration +10 (+14 lancer défensif), Connaissance (religion) +5, Perception auditive +3, Sens moral +12, Détection +3 Possessions équipement de combat plus chemise de maille+1, bouclier en acier léger +1, fléau +2, perle de pouvoir (sort de 1er niveau), 42 po, 10 pa', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2224);

