-- 2226 — Ettin fiélon
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2226, 'Ettin fiélon', 27, NULL, 'PV : 65 (10 DV) ; RD 5/magie\nNE Grand géant (extraplanaire)\nInitiative : -1\nSens : vision nocture, vision dans le noir à 18m ; Perception auditive +10, Détection +10\nLangues : Commun, Ettin\nClasse d\'armure : 19, contact 8, pris au dépourvu 19 ; 25 % de chances d’empêcher les attaques sournoises et les coups critiques (propriété de l’armure)\nRésistances : au froid 10, au feu 10 ; RM 15\nJets de sauvegarde : Vig +9, Réf +2, Lutte +5\nVitesse de déplacement : 9 m (6 cases) en armure de peau, vitesse de base 12 m\nMêlée : 2 morgenstern de maître +13/+8 chacun (2d6+6) ou\nMêlée : fouet +1 de feu +13/+8 (1d4+7 non létal plus 1d6 feu) et fouet +12/+7 (1d4+6 non létal) ou\nMêlée : frappes à mains nues +12/+7 chacune (1d6+6)\nDistance : 2 javelots +5 chacun (1d8+6)\nEspace occupé/allonge : 3m/3m\nAttaque de base/lutte : +7/+17\nOptions de combat : Frappe magique, combat à deux armes supérieur, Châtiment du bien 1/jour (+10 points de dégâts)\nCaractéristiques : For 23, Dex 8, Con 15, Int 6, Sag 10, Cha 11\nDons : #Vigilance#, Maniement d’armes exotiques (fouet), #Science du combat à mains nues#, #Volonté de fer#\nCompétences : Perception auditive +10, Fouille +10, Détection +10\nPossessions : Armure de peau +1 de défense légère, 2 morgensterns de maître, +1 fouet enflammé, fouet non magique, 5 javelots\nFrappe magique (Sur). Les coups à mains nues de l’Ettin sont considérés comme magiques pour ce qui est de surmonter la réduction des dégâts\nCombat à deux armes supérieur (Ext). L’ettin attaque avec une arme dans chaque main à chaque round. Comme chacune de ses deux têtes contrôle un bras, l’ettin ne subit pas de pénalité aux jets d’attaque ou de dégâts s’il attaque avec deux armes', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2226);

-- 2227 — Forthar Helvenstron
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2227, 'Forthar Helvenstron', 28, NULL, 'PV : 102 (14 DV)\nHumain vaasien guerrier 2 / commandeur 10\nLM Humanoïde de taille moyenne\nInitiative : +4 ; Perception auditive +7, Détection +7\nAura : auras majeures de commandeur +2, auras mineures\nLangues : Commun, Damaran, Géant\nClasse d\'armure : 25, contact 11, pris au dépourvu 225\nJets de sauvegarde : Vig +12, Réf +2, Vol +5\nVitesse de déplacement : 6m (4 cases) en plaque complète, vitesse de base 9m\nMêlée : épée longue +3 +18/+13(1d8+4, 18-20/x2 avec l\'aura Frappe précise)\nAttaque de base : +13/+8\nLutte : +10\nOptions de combat : combat montée, Attaque en puissance\nActions spéciales : Inspiration du champ de bataille, action de mouvement 2/jour\nCaractéristiques : For 13, Dex 10, Con 14, Int 12, Sag 8, Cha 19\nDons : #Vigilance#, #Inspiration du champ de bataille#, #Science de l\'initiative#B #Combat monté#, #Négociation#, #Attaque en puissance#, #Talent# (Diplomatie), #Arme de prédilection# (épée longue)\nCompétences : Bluff +12, Diplomatie +21, Déguisement +4 (+6 pour agir dans le personnage), Renseignements +6, Intimidation +16, Connaissances (Route de la Mer de lune) +9, Perception auditive +10, Psychologie +9, Détection +9\nPossessions : Plaque intégrale +2, bouclier d\'acier lourd +1, épée longue +3, anneau de protection +2, &cape de charisme& +2, 108 po, 15 pa\nAuras (Ex). En une action rapide, Forthar peut projeter une aura majeure ou mineure. Il peut maintenir une aura majeure et une aura mineure à la fois. Une aura reste en vigueur jusqu\'à ce qu\'il l’annule par une action libre ou qu\'il choisisse de projeter une autre aura du même type. Les auras affectent les alliés de Forthar, y compris Forthar (sauf exception).\nInspiration du champ de bataille (Ex). En tant qu\'action libre, Forthar peut inspirer du courage à ses alliés. Chaque allié situé à moins de 9m du capitaine de bataille (à l\'exclusion de Forthar) qui peut l\'entendre et possède une Intelligence de 3 ou plus bénéficie d\'un bonus de circonstances de +2 aux jets de sauvegarde contre les effets de peur\nAccorder une action de mouvement. Forthar peut diriger et motiver se troupes à agir immédiatement. une fois par jour, au prix d\'une action simple, il peut conférer une action de mouvement supplémentaire à tout allié dans un rayon de 9 mètres (mais pas à lui-même). Chacun des alliés affectés peut réaliser une action de mouvement, dans l\'ordre de leur initiative. Cette action supplémentaire n\'affecte pas l\'initiative de chacun ; après cette action réaliser, chacun agit normalement durant son tour.\n---\nAuras majeures\n- Motivation de l\'ardeur. Bonus de +2 aux jets de dégâts.\n- Motivation de l\'urgence. Bonus à la vitesse de base au sol égal à 1,50m x bonus d\'aura majeure.\nAuras mineures\n- Art de la guerre. Bonus de +4 aux jets de désarmement, croc-en-jambe, bousculade, renversement et destruction.\n- Frappe précise. Bonus de +2 aux jets de critique.\n- Maître de la tactique. Bonus de +4 aux jets de dégâts lors d\'une prise en tenaille.\n- Puissante charge. Bonus de +4 aux jets de dégâts lors de charge.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2227);

-- 2228 — Ogre War Hulk
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2228, 'Ogre War Hulk', 27, NULL, 'PV : 86 chacun (9 DV)\nOgre mâle barbare 2 / war hulk 3\nLM géant de Grande taille\nInitiative : +0\nSens : vision noire à 18m, vision nocturne ; Écoute +1, Détection +1\nLangues : Commun, Géant ; analphabète\nClasse d\'armure : 19, contact 9, pris dépourvu 19 ; Esquive instinctive\nJets de sauvegarde : Vig +14, Réf +2, Lutte +3\nVitesse de déplacement : 15m (8 cases) dans le plastron, vitesse de base 18m\nMêlée : épée à deux mains en adamantite +16 (3d6+16)\nDistance : rocher +15 (2d8+11)\nEspace : 3m ; Allonge 3m\nAttaque de base/lutte : +5/+20\nOptions de combat : #Enchaînement#, #Succession d’enchaînements#, #Science de la destruction#, #Attaque en puissance#, grand élan, lancer de rocher puissant, rage 1/jour\nÉquipement de combat : huile d\'arme magique suprême +1, potion de vol, sac de six rochers de 20 kg\nCaractéristiques : For 32, Dex 11, Con 18, Int 6, Sag 12, Cha 4\nDons : #Enchaînement#, #Succession d’enchaînements#, #Science de la destruction#, #Attaque en puissance#\nCompétences : Intimidation +9, Écoute +1, Détection +1\nPossessions : équipement de combat plus cuirasse de maître, épée à deux mains en adamantite de maître, 9 po, 19 pa\nBalayage puissant (Ext). Un ogre guerrier peut effectuer de grands balayages avec son épée à deux mains. En tant qu\'action complète, le guerrier peut choisir 3 cases adjacentes à un ennemi (il doit tous les menacer). Son attaque s\'applique à toutes les créatures dans ces cases. Effectuez un jet d\'attaque et appliquez ce jet comme une attaque contre chaque défenseur. Si un ogre utilise une attaque spéciale (telle que désarmement, croc-en-jambe ou destruction), cette attaque spéciale n\'affecte que la première cible ; les autres créatures sont attaquées normalement.\nSi un ogre abat un de ses ennemis avec un Balayage puissant, il peut effectuer une attaque d\'enchaînement normalement. Cependant, il ne peut le faire qu\'une seule fois par Balayage puissant, même s\'il abat plusieurs ennemis---\nLancer de rochers puissant (Ext). Un ogre guerrier peut lancer des rochers qui infligent 2d8 points de dégâts avec une portée de 15m (maximum 75m), en utilisant son modificateur de Force. Chaque rocher pèse environ 20kg\n---\nLorsqu\'il est enragé, l\'ogre war hulk a les statistiques modifiées suivantes :\nPV : augmentée de 18\nClasse d\'armure : 17, contact 7, pris au dépourvu 17\nJets de sauvegarde : Vig +16, Lutte +5\nMêlée : épée à deux mains en adamantite +18 (3d6+19)\nDistance : rocher +17 (2d8+13)\nLutte : +22\nCaractéristiques : For 36, Con 22', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2228);

