-- 2230 — Zvopua l'Aberration Draconique
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2230, 'Zvopua l\'Aberration Draconique', 11, NULL, 'PV : 92 (8 DV)\nDemi-dragon noir avancé, aberration ailée\nNM Très grand dragon (aberration augmentée)\nInitiative : +1\nSens : vision dans le noir à 18 m, vision nocturne ; Perception auditive +5, Détection +11\nLangues : aberration ailé, liés à son maître comme les familiers des druides\nClasse d\'armure : 21, contact 9, pris au dépourvu 20\nImmunités : contre l\'acide, les effets de sommeil magiques, la paralysie\nJets de sauvegarde : Vig +8, Réf +3, Vol +6\nVitesse de déplacement : 6 m (4 cases), vol 12 m (moyenne)\nMêlée : 3 morsures +17 chacune (2d6+13) et 2 griffes +12 chacune (2d4+6)\nEspace : 4,5 m ; Allonge 3 m\nAttaque de base/lutte : +6/+27\nOptions d\'attaque : Drain de sang\nAttaques spéciales : Souffle, écrasement\nCaractéristiques : Force 36, Dex 12, Con 22, Int 9, Sag 10, Cha 7\nDons : #Attaque en vol#, #Vol stationnaire#, #Virage sur l\'aile#\nCompétences : Escalade +27, Intimidation +8, Perception auditive +10, Déplacement silencieux +11, Psychologie +8, Détection +11\nDrain de sang (Ext). Le zvopua peut utiliser ses trois longues langues tubulaires pour drainer le sang d\'une victime qu\'il a immobilisée avec son attaque d\'écrasement. S\'il réussit un test de lutte, il inflige 1d4 points de dégâts de Constitution\nSouffle (Sur). Cône de gaz de 9 m, une fois toutes les 1d4 rounds, aveuglement et étourdissement pendant 1 round, DD de Réflexes 20 pour moitié ; ou ligne d\'acide de 18 m, une fois par jour, dégâts 6d8 d\'acide, DD de Réflexes 20 pour moitié\nÉcrasement (Ext). Cette attaque spéciale permet au Zvopua d\'atterrir sur ses adversaires en tant qu\'action standard, utilisant son corps pour les écraser. Les attaques d\'écrasement ne sont efficaces que contre des adversaires de taille Petite ou inférieure (bien qu\'il puisse tenter des attaques de renversement ou de lutte normales contre des adversaires plus grands).\nUne attaque d\'écrasement affecte autant de créatures que peuvent tenir sous le corps de Zvopua. Les créatures dans la zone affectée doivent réussir un jet de réflexe DD 20 ou être immobilisées, subissant automatiquement des dégâts contondants pendant le round suivant, à moins que Zvopua ne s\'éloigne d\'elles. Si Zvopua choisit de maintenir l\'immobilisation, considérez-la comme une attaque de lutte normale. Les adversaires immobilisés subissent des dégâts d\'écrasement chaque round s\'ils ne s\'échappent pas. Une attaque d\'écrasement inflige 2d8+19 points de dégâts', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2230);

