INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2231, 'Eregul l\'Indépendant', 28, NULL, 'PV : 50 (14 DV) ; RD 10/adamantite (peau de pierre, 127 points au total)\nHumain vaasien magicien 9/ magiciel zhentarim 5\nHumanoïde de taille moyenne\nInitiative : +1\nSens : Perception auditive +2, Détection +8\nLangues : Commun, chondathien, damaran, draconique, géant, orque\nClasse d\'armure : 21, contact 11, pris au dépourvu 18\nRésistances : endurance aux énergies destructives\nJets de sauvegarde : Vig +8, Réf +5, Vol +8\nVitesse de déplacement : 9 m (6 cases) ; Attaque en vol, Attaque au galop\nMêlée : lance +2 de tonerre +9/+3 (1d8+2/×3, double dégâts à cheval sur une monture de charge, plus 2d8 soniques en cas de coup critique) ou\nMêlée : dague +2 +8/+2 (1d4+1/19–20)\nEspace : 1,5 m ; Allonge 1,5 m (3 m avec une lance)\nAttaque de base/lutte : +6/+5\nOptions d\'attaque : Combat monté\nÉquipement de combat : Parchemin de brume acide (NLS 11), parchemin de charme-monstre (NLS 7), parchemin d\'$éclair$(NLS 5), parchemin de téléportation (NLS 9), parchemin de mur de glace (NLS 7), baguette de boule de feu (NLS 10, 25 charges), baguette de tempête de grêle (25 charges)\nSorts de magicien préparés (NLS 12 ; 10 % de chances d\'échec des sorts profanes) :\n7e — $invisibilité de groupe$, $Mot de pouvoir aveuglant$\n6e — $éclair multiple$ (2) (DD 23), $Globe d\'invulnérabilité renforcée$, $Champ de force$ (DD 22)\n5e — $brume mortelle$ (DD 21), $Domination$ (DD 21), $Communication à distance$, $Débilité$ (DD 21)\n4e — $tempête de grêle$, $Brouillard dense$, $Cri$ (DD 21), $Peau de pierre$†\n3e — $dissipation de la magie$, $Boule de feu$ (DD 20), $Vol$, éclair (DD 20), $Suggestion$ (DD 19)\n2e — $détection de pensées$ (DD 18), $Bourrasque$ (DD 19), $Invisibilité$, $Rayon ardent$ (2) (+7 au toucher à distance), détection de l\'invisibilité\n1e — endurance aux énergies destructives†, $Feuille morte$, $Bouclier$, $Disque flottant de Tenser$, $Coup au but$ (2)\n0e — $lumières dansantes$, $détection de la magie$, $message$, prestidigitation\n† déjà lancé\nCaractéristiques : Force 8, Dex 13, Con 12, Int 22, Sag 10, Cha 14\nParticularités : monture volante, familier (aucun pour le moment)\nDons : #Vigilance#, #Magie de guerre#, Création d\'armes et armures magiques, #Création de baguettes magiques#, Extension d\'effet, #Extension de portée#, #Attaque en vol# (monture uniquement), #Volonté de fer#, Maniement d\'une arme de guerre (lance), #Combat monté#, #Attaque au Galop#, Copie de parchemin, #Talent# (Équitation), #École renforcée# (évocation)\nCompétences : Concentration +16 (+20 pour lancer des sorts défensifs), Diplomatie +4, Dressage +4, Connaissances (mystères) +11, Connaissances (géographie) +11, Perception auditive +2, Équitation +16, Art de la magie+20, Détection +6, Survie +0 (+2 pour éviter de se perdre et les dangers naturels)\nPossessions : équipement de combat plus cotte de mailles en mithril +2, lance +3 de tonnerre, dague +2, &Amulette d\'armure naturelle& +3, bandeau de l\'intelligence +4, Anneau de la Tour du Hurlevent* , selle militaire exotique, 123 po\n* voir page 153\nLivre de sorts. Eregul ne porte pas son livre de sorts avec lui lorsqu\'il est en patrouille', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2231);

-- 2232 — Balhannoth
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2232, 'Balhannoth', 21, NULL, 'PV : 147 (14 DV)\nRD : 15/magie\nCM Aberration de grande taille\nInitiative : +7\nSens : aveugle, vision magique 120 m ; Perception auditive +6\nLangues : —\nAura : verrou dimensionnel\nClasse d\'armure : 21, contact 12, pris au dépourvu 18\nImmunités : aux attaques de regard, aux illusions et aux effets visuels\nRM : 18\nJets de sauvegarde : Vig +10, Réf +9, Vol +12\nVitesse de déplacement : 15m (10 cases), Escalade 15m\nMêlée : 2 coups violents +18 chacun (2d6+9/19–20) et morsure +13 (1d8+4)\nEspace occupé/allonge : 3m/3m (4,5m avec tentacules)\nAttaque de base/lutte : +10/+23\nOptions d\'attaque : Attaque en puissance, constriction +1d8, saisie améliorée, frappe magique\nActions spéciales : Lutte antimagique\nCaractéristiques : Force 28, Dex 17, Con 23, Int 3, Sag 12, Cha 8\nParticularités : camouflage\nDons : #Science du critique# (coup violent), #Science de l\'initiative#, #Volonté de fer#, #Réflexes surhumains#, #Attaque en puissance#\nCompétences : Escalade +17, Discrétion +16, Saut +17, Perception auditive +6, Déplacement silencieux +13\nVision anti-magie (Sur). Un balhannoth peut détecter la présence et la position des auras magiques dans un rayon de 36m autour de lui, ainsi que la puissance et l\'école de chacune d\'entre elles Il peut localiser avec précision toute créature sur laquelle un sort est en cours, qui porte des objets magiques ou qui utilise la magie, et il peut remarquer tout ce qui se trouve dans la zone d\'effet d\'un sort (y compris son propre verrou dimensionnel). Cette capacité fonctionne comme le sens aveugle.\nVerrou dimensionnel (Su). Comme le sort, rayon de 6m centré sur le balhannoth, niveau d\'équivalent de lanceur de sorts 10. Cet effet se déplace avec la créature\nConstriction (Ext). Un balhannoth inflige 1d8 points de dégâts avec un jet de lutte réussi, en plus des dégâts de son attaque de coup violent.\nSaisie améliorée (Ext). Pour utiliser cette capacité, un balhannoth doit toucher un adversaire de taille Grande au maximum avec une attaque de coup violent. Il peut ensuite tenter d\'engager une lutte en tant qu\'action gratuite sans provoquer d\'attaques d\'opportunité. S\'il remporte le test de lutte, il établit une prise et peut étrangler.\nLutte antimagique (Sur). Lorsqu\'un balhannoth lutte contre un adversaire, toutes les propriétés magiques des objets magiques de cet adversaire sont supprimées. De plus, une créature luttant contre un balhannoth ne peut pas lancer de sorts ni utiliser de capacités magiques ou surnaturelles\nCamouflage (Ext). La peau d\'un balhannoth change de couleur pour se fondre dans son environnement. Il peut ainsi utiliser la compétence Discrétion dans n\'importe quel type de terrain naturel', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2232);

