INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2233, 'Jezz l\'Estropié', 28, NULL, 'PV : 50 (13 DV)\nDrow mâle éclaireur 7 / ensorceleur 6\nCM Humanoïde de taille moyenne (elfe)\nInitiative : +10\nSens : vision dans le noir 36 m ; Perception auditive +16, Détection +16\nLangues : commun, chondathien, draconique, langue des signes drow, elfique, lien empathique, commun des profondeurs\nClasse d\'armure : 24, contact 17, pris au dépourvu 19 ; esquive extraordinaire\nRésistances : à l\'évasion ; RM 24\nJets de sauvegarde : Vig +5, Réf +12, Vol +9 (+11 contre les sorts, les capacités magiques et les enchantements)\nVitesse de déplacement : 12m (8 cases)\nMêlée : kukri +3 acéré +17/+11 (1d4+3, 15-20/x2) plus empoisonnement ou\nMêlée : dague +1 +15/+9 (1d4+1, 20/x2) + poison (poudre d\'assonne : 2d12 PV / -1d6 CON) ou\nMêlée : dague +1 +15/+9 (1d4+1, 20/x2) + poison (Extrait de lotus noir : -3d6 CON / -3d6 CON)\nAttaque de base/lutte : +8/+8\nOptions d\'attaque : poison (poison drow, DD 13, inconscient 1 minute/inconscient 2d4 heures), poison (poudre d\'assonne, DD16, 2d12 PV / -1d6 CON), poison (Extrait de lotus noir, DD20, -3d6 CON / -3d6 CON) , escarmouche\nÉquipement de combat : 4 doses de poison drow, &baume de Keoghtom&, 2 fioles d\'onguent des roches\nSorts d\'ensorceleur connus : (NLS 6e) :\n3e - (4/jour) — $vol$\n2e - (6/jour) $grâce féline$, $Invisibilité$\n1er niveau - (7/jour) déguisement, $Feuille morte$, $Brume de dissimulation$, $Bouclier$\n0 - (6/jour) détection de la magie, $Détection du poison$, $Son imaginaire$(DD 14), $manipulation à distance$, $réparation$, $rayon de givre$ (+13 au contact à distance), lecture de la magie\nCaractéristiques : (NLS 13) :\n1/jour - $Lumières dansantes$, $Ténèbres$, $Lueur féerique$\nCaractéristiques : Force 10, Dex 20, Con 11, Int 16, Sag 14, Cha 19\nParticularités : capable de remarquer les portes secrètes ou dissimulées, vigueur au combat +1, mouvement rapide, utilisation de l\'empoisonnement, partage de sorts, familier (vipère), pas insaisissable, détection des pièges\nDons : #Vigilance# (si familier à moins de 1,5 m), #Adaptation diurne#, Maniement d\'une arme exotique (kukri), #Science de l\'initiative#, #Discret#, #Attaque en finesse#, #Arme de prédilection# (kukri)\nCompétences : Équilibre +12, Bluff +12, Escalade +5 (+7 avec une corde), Concentration +10, Diplomatie +13, Déguisement +9 (+11 pour jouer un personnage), Évasion +5 (+7 avec une corde), Renseignements +6, Discrétion +17, Intimidation +11, Saut +7, Connaissances (mystères) +8, Connaissances (folklore local) +8, Connaissances (nature) +5, Perception auditive +16, Déplacement silencieux +21, Équitation +10, Fouille +10, Psychologie +7, Art de la magie+15 (+17 pour déchiffrer les parchemins), Détection +16, Acrobaties +12, Utilisation d\'objets magiques +9 (+11 avec les parchemins)\nPossessions : équipement de combat plus armure de cuir +5, kukri +3 acéré, 2 dagues +1, 1 dagues de maitre, anneau de protection +2, &gant de rangement&, &cuillère de Murlynd&, corde d\'escalade, 17 po, 15 po, poudre d\'assonne (poison), Extrait de lotus noir\nVigueur au combat (Ex). Bonus aux jets d\'initiative et aux jets de sauvegarde de Vigueur lorsque vous portez une armure légère ou aucune armure et que vous transportez une charge légère. Inclus ci-dessus\nAdaptation à la lumière du jour (Ext). Jezz ne souffre pas de la vulnérabilité à la lumière normale des drows. Il reste toutefois vulnérable aux sorts ou effets liés à la lumière qui affectent toutes les créatures, quelle que soit leur race\nEscarmouche (Ext). Bonus de +2d6 aux jets de dégâts et +2 à la CA lors de tout round où Jezz se déplace d\'au moins 3 m', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2233);

