-- 2235 — Le Gardien
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2235, 'Le Gardien', 21, NULL, 'PV : 118 (11 DV) ; guérison rapide 2\nNaga de Baine, théurge mystique 4\nLM Aberration très grande\nInitiative : +5\nSens : vision dans le noir 18 m ; Perception auditive +14, Détection +14\nLangues : Commun, damaran, draconique, géant, gobelin, infernal, orque\nClasse d\'armure : 14, contact 9, pris au dépourvu 13\nImmunités : contre l\'acide, l\'empoisonnement\nRésistances : +3 contre la pétrification, endurance aux énergies destructives\nJets de sauvegarde : Vig +10, Réf +4, Vol +13\nVitesse de déplacement : 9 m (6 cases), natation 9 m\nMêlée : dard +15 (2d6+10 plus empoisonnement) et morsure +10 (1d8+5 plus empoisonnement)\nAttaque de base/lutte : +7/+25\nOptions d\'attaque : empoisonnement (blessure ou contact, DD DD 20, 2d4 à la Constitution/1d3 heures d\'inconscience), sort (action gratuite)\nÉquipement de combat : collier de boules de feu (2d6, 4d6, 6d6), anneau de contre-sort (boule de feu)\nSorts de prêtre préparés (NLS 10) :\n5e - $Injonction suprême$ (DD 20), $Exécution$ (+15 au toucher en mêlée, DD 20), résistance aux sortsD\n4e - $Soins intensifs$, $Puissance divine$, $Liberté de mouvement$, $Empoisonnement$ (+15 au toucher en mêlée, DD 19), fléau impieD (NLS 11, DD 18)\n3e - $Malédiction$ (+15 en contact au corps à corps, DD 18), $Ténèbres profondes$, $Dissipation de la magie$, $Cercle magique contre le bien$ (NLS 11e), $Prière$\n2e - $profanation$ (2, NLS 11e), $Discours captivant$ (DD 17), nuage de brouillard, $Immobilisation de personne$ (DD 17), $Silence$ (DD 16)\n1er - $Imprécation$ (DD 16), $Injonction$ (DD 16), endurance aux énergies destructives†, $Protection contre le bien$D (NLS 11), $Sanctuaire$ (DD 15), $Bouclier de la foi$\n0 — détection de la magie (2), assistance divine, lumière, lecture de la magie, résistance\nD : sort de domaine. Divinité : Baine. Domaines : Mal, Magie, Eau\nSorts préparés par le magicien (NLS 10) :\n5e — domination (DD 21), $Débilité$ (DD 21), $Vagues de fatigue$\n4e — désespoir foudroyant (DD 20), $Terreur$ (DD 20), $Bouclier de feu$, $Tempête de grêle$\n3e — clignotement, $Boule de feu$ (DD 18), éclair (DD 18), $Baiser du vampire$ (+15 au contact en mêlée)\n2e — simulacre de vie, $Baiser de la goule$ (+15 au contact en mêlée, DD 18), $Effroi$ (DD 18), $Rayon ardent$ (2, +8 au toucher à distance)\n1er — alarme (2)†, $Contact glacial$ (2, +15 en contact au corps à corps, DD 17), $Projectile magique$, $Décharge électrique$ (+15 en contact au corps à corps)\n0 — manipulation à distance, ouverture/fermeture, fatigue (2, +15 en contact au corps à corps, DD 16)\n† déjà lancé\nCaractéristiques : Force 31, Dex 13, Con 24, Int 20, Sag 18, Cha 14\nParticularités : aura maléfique, objets magiques\nDons : #Magie de guerre#, Éviter les objets inanimés, #Science de l\'initiative#, #École renforcée# (nécromancie), École renforcée (enchantement)\nCompétences : Bluff +12, Concentration +17 (+21 pour lancer des sorts défensifs), Diplomatie +11, Déguisement +2 (+4 pour jouer un personnage), Intimidation +14, Connaissances (mystères) +11, Connaissances (religion) +11, Perception auditive +14, Psychologie +9, Art de la magie+17 (+19 pour déchiffrer les parchemins), Détection +14, Natation +26, Utilisation d\'objets magiques +8 (+10 pour les parchemins)\nPossessions : équipement de combat plus symbole sacré en argent, grimoire\nObjets magiques Le Gardien collectionne les objets magiques et les utilise librement. Ses tentacules peuvent porter ou manipuler des amulettes, des anneaux, des baguettes, des bâtons, des potions et autres objets similaires\nSorts. Le Gardien peut lancer un seul sort par round en tant qu\'action gratuite pendant qu\'il attaque\nLivre de sorts. Le livre de sorts du Gardien, caché sous un rocher instable dans la zone D1, contient tous les sorts qu\'il a préparés, plus 3 autres sorts de chaque niveau qu\'il peut lancer (au choix du MJ)', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2235);

-- 2236 — Garde terrifiant
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2236, 'Garde terrifiant', 1, NULL, 'PV : 39 (6 DV)\nRD : 5/contondant\nNM Mort-vivant de taille moyenne\nInitiative : +0\nSens : vision dans le noir 18 m, détection de l\'invisibilité ; Perception auditive +8, Perception +8\nClasse d\'armure : 16, contact 13, pris au dépourvu 16\nImmunités : au froid, immunités des morts-vivants\nJets de sauvegarde : Vig +2, Réf +2, Vol +6\nVitesse de déplacement : 9 m (6 cases)\nMêlée : épée longue de maître +8 (1d8+4/19–20) et griffe +2 (1d4+2) ou\nMêlée : 2 griffes +7 chacune (1d4+4)\nAttaque de base/lutte : +3/+7\nOptions d\'attaque : Combat en aveugle, Attaque en puissance\nCapacités magiques : (niveau d\'enchantement 6) :\n1 / 3 rounds - $projectile magique$\n1 / 10 minutes - $clignotement$\nCaractéristiques : Force 18, Dex 11, Con —, Int 11, Sag 12, Cha 13\nParticularités : traits de mort-vivant\nDons : #Combat en aveugle#, #Magie de guerre#, #Attaque en puissance#\nCompétences : Concentration +0 (+4 pour lancer des sorts en défense), Discrétion +7, Perception auditive +8, Déplacement silencieux +7, Fouille +8, Détection +8\nPossessions : Épée longue de maître\nArmure de force (Ex). Le champ de force sombre et translucide qui entoure un garde terrifiant lui confère un bonus de déviation de +3 à sa CA\nDétection de l\'invisibilité (Sur). Comme le sort ; niveau de lanceur de sorts 13\n---\nDans la zone d\'effet du sort profanation du naga de Baine, les gardes terrifiants ont les caractéristiques suivantes :\nJets de sauvegarde : Vig +3, Réf +3, Lutte +7\nMêlée : épée longue de maître +9 (1d8+5/19-20) et griffe +3 (1d4+3) ou\nMêlée : 2 griffes +8 chacune (1d4+5)', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2236);

