INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2237, 'Seigneur Trystemine (Possédé)', 28, NULL, 'PV : 64 (15 DV)\nHumain chondathien guerrier 11 / champion divin (Shar) 4\nNE Humanoïde de taille moyenne\nInitiative : +6\nSens : Perception auditive +3, Détection +3\nLangues : Commun, Loross, Netherisse\nClasse d\'armure : 21, contact 12, pris au dépourvu 19 ; Esquive, Souplesse du serpent\nJets de sauvegarde : Vig +17, Réf +12, Vol +9 ; +2 contre les capacités magiques et surnaturelles des étrangers et contre les sorts divins\nRM : 26\nVitesse de déplacement : 9 m (6 cases)\nMêlée : possession (voir page 158) ou\nMêlée : épée à deux mains +1 +20/+15/+10 (2d6+7/19–20)\nDistance : arc long composite de maître +18/+13/+8 (1d8+4/×3)\nAttaque de base : +15 ; Lutte : +19\nOptions d\'attaque : Attaques réflexes, Tir à bout portant, Attaque en puissance, Tir de précision, Frapper l\'infidèle 1/jour (+2 attaques, +4 dégâts)\nActions spéciales : Contrôle de la lumière, imposition des mains 8 points/jour, possession\nCapacités de type sort (niveau de lanceur de sorts 15) :\nÀ volonté — $ténèbres$\n1/round — $invisibilité$ (sur soi uniquement)\n3/jour — $image miroir$\n1/jour — $téléportation suprême$ (vers un lieu obscur) ou $changement de plan$ (vers ou depuis le plan des ombres uniquement)\nCaractéristiques : Force 18, Dex 14, Con 14, Int 13, Sag 8, Cha 14\nDons : (ceux qui s\'appliquent) #Attaque spéciale renforcée# (possession), #Combat en aveugle#, #Expertise du combat#, #Esquive#, #Science de l\'initiative#, #Volonté de fer#, #Réflexes surhumains#, #Souplesse du Serpent#, #Tir à bout portant#, #Attaque en puissance#, #Tir de précision#, #Attaque éclair#\nCompétences : Escalade +16, Déguisement +10, Discrétion +23, Intimidation +14, Saut +24, Connaissances (religion) +4, Perception auditive +3, Déplacement silencieux +10, Équitation +14, Détection +3\nPossessions : cotte de mailles en mithril +3, épée à deux mains +1, arc long composite de maître (+4 bonus de Force) avec 20 flèches, amulette d\'armure naturelle +2, illusion du pendentif d\'Ashaba, 128 po, 49 pa\nSi le seigneur Trystemine est libéré de la possession, ses caractéristiques changent comme suit :\nPV : 64 (8 DV)\nGuerrier humain chondathien de niveau 8\nHumanoïde de taille moyenne\nInitiative : +2 ; Perceptions Perception auditive +3, Détection +1\nLangues : Chondathien, commun, elfique\nJets de sauvegarde : Vig +8, Réf +4, Vol +3\nMêlée : Épée à deux mains +1 +15/+10 (2d6+9/19-20)\nDistance : arc long composite de maître +11/+6 (1d8+4/×3)\nAttaque de base : +8 ; Lutte : +12\nOptions d\'attaque : Combat en aveugle, Enchaînement, Succession d\'enchaînements, Attaque en puissance\nCaractéristiques : Force 18, Dex 14, Con 14, Int 12, Sag 12, Cha 12\nDons : #Combat en aveugle#, #Enchaînement#, #Esquive#, Succession d\'enchaînements, #Arme de prédilection# supérieure (épée à deux mains), Mobilité, #Attaque en puissance#, Arme de prédilection (épée à deux mains), #Spécialisation martiale# (épée à deux mains)\nCompétences : Décryptage +2, Diplomatie +8, Perception auditive +3, Équitation +11, Psychologie +5, Détection +1', NULL, 88, 5, 1, 1, 1
