-- 2238 — Scyllua Sombrespoir
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2238, 'Scyllua Sombrespoir', 28, NULL, '123 PV (15 DV)\nHumaine chondathienne paladin déchu 5/ rôdeur 4/ chevalier noir 6 (imprécation)\nLM Humanoïde de taille moyenne\nInitiative : +1\nSens : Perception auditive +7, Détection +11\nAura : désespoir (3 m, les ennemis subissent un malus de -2 aux jets de sauvegarde)\nLangues : commun, chondathien, damaran, orc\nClasse d\'armure : 21, contact 11, pris au dépourvu 20 ; 25 % de chances de coup critique ou de dégâts d\'attaque sournoise normaux (propriété de l\'armure)\nRésistances : endurance aux énergies destructives\nJets de sauvegarde : Vig +19, Réf +11, Vol +11\nVitesse de déplacement : 6 m (4 cases) en armure complète, vitesse de base 9 m ; Attaque au galop\nMêlée : épée bâtarde acérée +3 +19/+14/+9 (1d10+4/17-20 plus empoisonnement)\nAttaque de base/lutte : +15/+16\nOptions d\'attaque : Enchaînement, Science de la destruction, Combat monté, Attaque en puissance, Charge dévastatrice, Ennemi juré Zhentarim +2, empoisonnement (poison mortelame, blessure, DD 20, 1d6 à la Constitution/2d6 à la Constitution), Châtiment du bien 4/jour (+3 en mêlée, +6 aux dégâts), attaque sournoise +2d6\nActions spéciales : imposition des mains 15 points/jour (sur soi-même ou un serviteur démoniaque), intimidation des mort-vivants 6/jour (+5, 2d6+7, NLS 4e)\nÉquipement de combat : 2 doses de poison mortelame\nSorts de rôdeur préparés (NLS 2e) :\n1er — endurance aux énergies destructives†\n† déjà lancé\nSorts de chevalier noir préparés (NLS 6e) :\n3e - $soins importants$\n2e - $force de taureau$, $Splendeur de l\'aigle$\n1er - $corruption d\'arme$, $Faveur divine$\nCapacités de type sort (NLS 6) :\nA volonté - $détection du Bien$\nCaractéristiques : Force 13, Dex 12, Con 16, Int 14, Sag 15, Cha 16\nParticularités : aura maléfique, compagnon animal (aucun), serviteur démoniaque (destrier noir), utilisation de poison, partage de sorts, empathie sauvage +12 (+8 contre les créatures magiques)\nDons : #Enchaînement#, #Endurance#, #Science du critique# (épée bâtarde), #Science de la destruction#, #Volonté de fer#, #Combat monté#, #Attaque en puissance#, #Attaque au Galop#, #Charge dévastatrice#, #Pistage#, #Combat à deux armes# (si armure lourde retirée)\nCompétences : Bluff +8, Concentration +11, Diplomatie +10, Déguisement +5 (+7 pour jouer un personnage), Renseignements +5, Premiers secours +7, Discrétion +1, Intimidation +10, Connaissances (folklore local) +3, Connaissances (nature) +3, Connaissances (religion) +7, Perception auditive +7, Équitation +15, Fouille +7, Psychologie +7, Détection +11, Survie +7 (+9 après avoir suivi des traces)\nPossessions : équipement de combat + armure de plate complète +2 de défense légère, épée bâtarde +3 acérée, anneau de Feuille morte, selle militaire exotique, 4 po', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2238);

-- 2239 — Targaraene
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2239, 'Targaraene', 25, NULL, 'PV : 75 (10 DV)\ndestrier noir\nNM Extérieur de grande taille (maléfique, extraplanaire)\nInitiative : +6\nSens : vision dans le noir 18 m ; Perception auditive +16, Détection +16\nLangues : lien empathique, parler avec son maître\nClasse d\'armure : 27, contact 11, pris au dépourvu 25\nRésistances : esquive extraordinaire\nJets de sauvegarde : Vig +16, Réf +9, Vol +8\nVitesse de déplacement : 12m (8 cases), vol 27m (bon) ; Course\nMêlée : 2 sabots +14 chacun (1d8+5 plus 1d4 feu) et morsure +9 (1d8+2)\nEspace : 3m ; Allonge 1,5m\nAttaque de base/lutte : +10/+19\nOptions d\'attaque : sabots enflammés, Charge en puissance, fumée\nActions spéciales : projection astrale, passage dans l\'éther\nCaractéristiques : Force 20, Dex 15, Con 16, Int 13, Sag 13, Cha 12\nDons : #Vigilance#, #Science de l\'initiative#, #Charge en puissance#, Course Compétences Concentration +16, Diplomatie +3, Intimidation +14, Connaissances (plans) +14, Perception auditive +16, Déplacement silencieux +15, Fouille +14, Psychologie +14, Détection +16, Survie +14 (+16 sur les autres plans et en pistage)\nProjection astrale (Su). Comme le sort, à volonté ; NLS 20.\nPassage dans l\'éther (Su). Comme le sort, à volonté ; NLS 20.\nSabots enflammés (Su). Un coup des sabots de Targaraene enflamme les combustibles.\nFumée (Sur). Dans le feu de l\'action, Targaraene renifle et hennit de rage. Ce reniflement remplit un cône de 4,5 mètres de fumée chaude et sulfureuse qui étouffe et aveugle les adversaires. Toute personne se trouvant dans le cône doit réussir un jet de Vigueur DD 18 ou subir une pénalité de -2 sur tous ses jets d\'attaque et de dégâts jusqu\'à 1d6 minutes après avoir quitté le cône. Le cône dure 1 round, et Targaraene l\'utilise une fois comme action gratuite pendant son tour chaque round. En raison de la fumée qu\'il dégage, Targaraene bénéficie d\'un camouflage contre les créatures situées à 1,5 mètre et d\'un camouflage total contre les créatures situées à 3 mètres ou plus. La fumée n\'obscurcit pas le champ de vision du destrier noir.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2239);

-- 2240 — Erinyes
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2240, 'Erinyes', 25, NULL, 'PV : 85 (9 DV) ; RD 5/bien\nLM Extérieur de taille moyenne (baatezu, mauvais, extraplanaire, loyal)\nInitiative : +5\nSens : vision dans le noir 18 m, vision dans les ténèbres, $vision lucide$ ; Perception auditive +16, Détection +16\nLangues : infernal, céleste, draconique ; télépathie 30 m\nClasse d\'armure : 23, contact 15, pris au dépourvu 18 ; Esquive, Souplesse du serpent\nImmunités : au feu, à l\'empoisonnement\nRésistances : à l\'acide 10, au froid 10\nRM : 20\nJets de sauvegarde : Vig +11, Réf +11, Vol +10\nVitesse de déplacement : 9 m (6 cases), vol 15 m (bon) ; Tir en mouvement\nMêlée : épée longue +14/+9 (1d8+5/19-20)\nDistance : arc long composite enflammé +1 +15/+10 (1d8+6/×3 plus 1d6 de feu) ou\nDistance : arc long composite enflammé +1 +13/+13/+8 (1d8+6/×3 plus 1d6 de feu) avec Tir rapide ou\nDistance : corde +14 (enchevêtrement)\nAttaque de base/lutte : +9/+14\nOptions d\'attaque : Tir à bout portant, Tir de précision, Enchevêtrement\nActions spéciales : Convocation de baatezu\nCapacités magiques : (niveau de lanceur de sorts 12) :\nA volonté - $Charme-monstre$ (DD 19), $Téléportation suprême$ (lui-même plus 22 kg d\'objets uniquement), $Image imparfaite$ (DD 17), $Ténèbres maudites$ (DD 19)\nCaractéristiques : Force 21, Dex 21, Con 21, Int 14, Sag 18, Cha 20\nDons : #Esquive#, #Souplesse du Serpent#, #Tir à bout portant#, #Tir de précision#, #Tir rapide#, #Tir en mouvement#\nCompétences : Concentration +17, Diplomatie +7, Évasion +17, Discrétion +17, Connaissances (religion) +14, Connaissances (plans) +14, Perception auditive +16, Déplacement silencieux +17, Fouille +14, Psychologie +16, Détection +16, Survie +4 (+6 au pistage et sur les autres plans), Maîtrise des cordes +5 (+7 avec des entraves)\nPossessions : épée longue, arc long composite enflammé +1 (+5 bonus de Force) avec 20 flèches\nEnchevêtrement (Ext) Chaque érinyes porte une corde solide d\'environ 15 mètres de long qui enchevêtre les adversaires de toute taille comme le sort corde animée (NLS 16). Une érinyes peut lancer sa corde à 9 mètres sans pénalité de portée. En général, une érinyes enchevêtre un ennemi, le soulève dans les airs et le laisse tomber d\'une grande hauteur\nInvocation de baatezu (Mag) Une fois par jour, une érinyes peut tenter d\'invoquer 2d10 lémures ou 1d4 diables barbus avec 50 % de chances de réussite. Cette capacité équivaut à un sort de niveau 3', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2240);

-- 2241 — diable barbu
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2241, 'diable barbu', 25, NULL, 'PV : 45 (DV 6d8+18); RD 5/argent ou Bien\nExtérieur [Baatezu, Extraplanaire, Loi, Mal] de taille M\nInitiative : +8\nSens : vision dans le noir (18 m), vision dans les ténèbres, Perception auditive +9, Détection +9\nLangages télépathie (30 m)\nClasse d\'armure : 19 (+2 Dex, +7 naturelle), contact 12, pris au dépourvu 17\nImmunités : contre le feu et le poison\nRésistances : acide (10), froid (10)\nRM : 17\nJets de sauvegarde : Vig +8, Réf +7, Vol +5don\nVitesse de déplacement : 12 m (8 cases)\nMêlée : coutille (+9 corps à corps, 1d10+3/x3 et blessure infernale) ; ou griffes (+8 corps à corps, 1d6+2) ou\nMêlée : coutille (+9/+4 corps à corps, 1d10+3/x3 et blessure infernale) ou\nMêlée : 2 griffes (+8 corps à corps, 1d6+2)\nAttaque de base : +8 ; lutte +8\nEspace : occupé 1,50 m ; allonge 1,50 m (3 m avec sa coutille)\nOptions d\'attaque : barbe, blessure infernale, convocation de diables, frénésie guerrière, pouvoirs magiques\nCapacités de type sort (Niveau 12 de lanceur de sorts) :\nA volonté - $Téléportation$ (uniquement lui-même et 25 kg d’objets)\nCaractéristiques : For 15, Dex 15, Con 17, Int 6, Sag 10, Cha 10\nDons : #Arme de prédilection# (coutille), #Attaque en puissance#, Science de l’initiative\nCompétences : Déplacement silencieux +9, Détection +9, Diplomatie +2, Discrétion +11, Escalade +11, Perception auditive +9, Psychologie +9\nBarbe (Ext). Si le diable barbu réussit deux attaques de griffes sur un adversaire dans le même round, il l’amène automatiquement au contact de sa barbe. La victime subit 1d8+2 points de dégâts et doit réussir un jet de Vigueur (DD 16) pour ne pas contracter une terrible maladie appelée diantrespasme (temps d’incubation 1d4 jours, effet : affaiblissement temporaire de 1d4 points de Force). Les effets s’appliquent chaque jour, jusqu’à ce qu’elle meure, qu’elle réussisse trois jets de Vigueur successifs ou que la maladie soit soignée par magie. Le DD de sauvegarde est lié à la Constitution\nBlessure infernale (Sur). Chaque coup porté par la coutille du diable barbu provoque une blessure persistante, qui se traduit par la perte de 2 points de vie supplémentaires par round. La blessure ne se referme pas d’elle-même et résiste aux soins magiques. L’hémorragie peut être stoppée par un test de Premiers secours de DD 16, un sort de soins ou de guérison suprême. Cependant, le personnage lançant un sort de soins ou de guérison suprême sur la victime d’une blessure infernale doit réussir un test de niveau de lanceur de sorts de DD 16 ou le sort n’a aucun effet sur sa cible. Le test de Premiers secours permet de stopper l’hémorragie et de rendre des points de vie. À noter que ce pouvoir surnaturel est propre au diable barbu, pas à son arme. Les DD des tests sont liés à la Constitution\nConvocation de diables (Mag). Une fois par jour, le diable barbu peut tenter d’appeler 2d10 lémures (avec 50% de chances de succès) ou 1 autre diable barbu (avec 35% de chances de succès). Ce pouvoir est équivalent à un sort du 3e niveau\nFrénésie guerrière (Ext). Au combat, le diable barbu peut entrer dans un état de frénésie similaire à la rage de berserker du barbare (+4 en Force et en Constitution, bonus de moral de +2 aux jets de Volonté, mais malus de –2 à la CA). La frénésie dure pendant 6 rounds et le diable barbu ne subit aucun effet négatif quand elle cesse', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2241);

-- 2242 — Tarapion (Sanglier)
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2242, 'Tarapion (Sanglier)', 22, NULL, 'PV : 78\nDés de vie : 11d8+12\nAnimal de taille M\nInitiative : +2\nVitesse de déplacement : 12 m (8 cases)\nClasse d\'armure : 20, contact 12, pris au dépourvu 18\nAttaque de base/lutte : +2/+4\nMêlée : défenses +12 (1d8+4) ou\nMêlée : défenses +12 /+7 (1d8+4)\nEspace occupé/allonge : 1,50 m/1,50 m\nAttaques spéciales : férocité\nParticularités : odorat, vision nocturne\nJets de sauvegarde : Réf +3, Vig +7, Vol +7\nCaractéristiques : For 19, Dex 14, Con 17, Int 2, Sag 13, Cha 4\nCompétences : Détection +5, Perception auditive +7\nDons : #Robustesse#, #Vigilance#\nFérocité (Ext). Le sanglier est un combattant tellement féroce qu’il continue de se battre sans le moindre malus, même quand il devrait être hors de combat ou quand il est mourant.\nLien (Ext). Un druide peut diriger son compagnon animal par une action libre, ou le pousser par une action de mouvement, et ce même s’il ne possède pas un degré de maîtrise en Dressage de 1 ou plus. Le druide bénéficie d’un bonus de circonstances de +4 sur les tests d’empathie sauvage et de Dressage en rapport avec son compagnon animal.\nTransfert d’effet magique (Ext). Si le druide le souhaite, tout sort (mais pas un pouvoir magique) qu’il lance sur lui-même peut également affecter son compagnon animal. Ce dernier doit se trouver à 1,50 mètre ou moins de distance au moment de l’incantation pour bénéficier des effets du sort. Si le sort a une durée autre qu’instantanée, il cesse d’affecter le compagnon animal si celui-ci s’éloigne de son maître de plus de 1,50 mètre. Dans ce cas, l’effet du sort ne reprend pas même si le compagnon revient à côté du druide. De plus, le personnage peut lancer directement sur son compagnon animal tout sort à portée personnelle (il a alors une portée de contact) au lieu de le lancer sur lui-même. Ce transfert d’effet magique est permis même si, en temps normal, le sort ne devrait pas affecter une entité du type du compagnon (animal).\nEsquive totale (Ext). Lorsque le compagnon animal est soumis à un effet qui autorise un jet de Réflexes pour demi-dégâts, il ne subit aucun dégât s’il réussit son jet de sauvegarde.\nDévotion (Ext). La dévotion du compagnon animal pour son maître est telle qu’il obtient du bonus de moral de +4 sur ses jets de sauvegarde contre les sorts et effets de l’école des enchantements.\nAttaques multiples (Ext). Le compagnon animal obtient automatiquement ce don en tant que don supplémentaire, à condition d’avoir au moins trois attaques naturelles et de ne pas déjà le posséder. Si l’animal ne remplit pas la condition des trois attaques naturelles, il obtient à la place de ce don la possibilité de porter une seconde attaque à l’aide de son arme naturelle principale, mais avec un malus de –5.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2242);

-- 2243 — Licorne ailée
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2243, 'Licorne ailée', 23, NULL, 'Créature magique de taille G, CB\nPV : 132\nDés de vie : 12d10+60\nInitiative : +3\nVitesse de déplacement : 18 m (12 cases), vol 36 m (moyenne)\nClasse d\'armure : 20 (–1 taille, +3 Dex, +8 naturelle), contact 12, pris au dépourvu 17\nAttaque de base/lutte : +4/+13\nMêlée : corne +14/+9 (1d8+8) ou\nMêlée : corne +14 (1d8+8) et 2 sabots +12 (1d4+2)\nEspace occupé/allonge : 3 m/1,50 m\nAttaques spéciales : —\nParticularités : cercle magique contre le Mal, empathie sauvage, immunité contre le charme, la coercition et le poison, odorat, pouvoirs magiques, vision dans le noir (18 m), vision nocturne\nJets de sauvegarde : Réf +7, Vig +9, Vol +6\nCaractéristiques : For 20, Dex 17, Con 21, Int 10, Sag 21, Cha 24\nCompétences : Déplacement silencieux +9, Détection +11, Perception auditive +11, Saut +21, Survie +8*\nDons : #Talent# (Survie), #Vigilance#;#Attaques multiples#.\nCercle magique contre le Mal (Sur). Ce pouvoir produit en permanence l’effet du sort cercle magique contre le Mal. La licorne ne peut pas le réprimer.\nEmpathie sauvage (Ext). Ce pouvoir fonctionne sur le même principe que l’aptitude de druide éponyme, si ce n’est que la licorne bénéficie d’un bonus racial de +6 au test.\nEsquive totale (Ext). Lorsque le compagnon animal est soumis à un effet qui autorise un jet de Réflexes pour demi-dégâts, il ne subit aucun dégât s’il réussit son jet de sauvegarde.\nDévotion (Ext). La dévotion du compagnon animal pour son maître est telle qu’il obtient du bonus de moral de +4 sur ses jets de sauvegarde contre les sorts et effets de l’école des enchantements.\nPouvoirs magiques. La licorne peut jeter à volonté (action libre). Une fois par jour, elle peut lancer $téléportation suprême$ pour réapparaître n’importe où sur son territoire. Elle ne peut pas se téléporter en dehors de sa forêt, ou utiliser ce pouvoir pour y revenir si elle se trouve à l’extérieur.\nEn touchant un blessé à l’aide de sa corne, elle peut lancer $soins légers$(3 fois par jour) et $soins modérés$(1 fois par jour ; niveau 5 de lanceur de sorts). Toujours par le biais de sa corne, elle peut jeter $neutralisation du poison$ (1 fois par jour ; niveau 8 de lanceur de sorts ; DD 21). Le DD de sauvegarde est lié au Charisme.\nCompétences. La licorne bénéficie d’un bonus racial de +4 aux tests de Déplacement silencieux.\n* Elle bénéficie également d’un bonus racial de +3 aux tests de Survie au sein de sa forêt.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2243);

-- 2244 — Aunrae Dhuunirv
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2244, 'Aunrae Dhuunirv', 28, NULL, 'PV : 57 (12 DV)\nPrêtresse drow 12 (Lolth)\nCM Humanoïde de taille moyenne (elfe)\nInitiative : +4\nSens : vision dans le noir 36 m ; Perception auditive +8, Détection +8\nLangues : Abyssal, commun, langue des signes drow, elfique, commun des profondeurs\nClasse d\'armure : 18, contact 10, pris au dépourvu 18\nImmunités : aux effets de sommeil magiques\nRésistances : aux énergies destructives ; RM 23\nJets de sauvegarde : Vig +8, Réf +6, Vol +12 (+14 contre les sorts, les capacités magiques et les enchantements)\nFaiblesse : vulnérabilité à la lumière\nVitesse de déplacement : 6 m (4 cases) avec cuirasse, vitesse de base 9 m\nMêlée : flagelle +2* +11/+6 (1d8 plus 5 têtes de serpent)\nAttaque de base : +9 ; Lutte : +9\nActions spéciales : intimidation des mort-vivants 6/jour (+5, 2d6+15, 12e),\nintimidation des araignées 6/jour (+3, 2d6+15, 12e), lancement spontané de sorts (infliger des sorts) (+9 en contact en mêlée)\nÉquipement de combat : Insigne supérieur de la maison Dhuurniv*\n* voir page 151\nSorts de prêtre préparés (NLS 12) :\n6e - $Dissipation suprême$, $Mise à mal$ (+9 en contact en mêlée, DD 20), $malédiction arachnide$ (DD 20)\n5e - $Colonne de feu$ (DD 19), $Fléau d\'insectes$, $Exécution$ (2) (DD 19)\n4e - $Soins intensifs$ (2), $Puissance divine$, vermin géanteD, $Immunité contre les sorts$\n3e - $Ténèbres profondes$, négation de l’invisibilité, $Prière$, $Protection contre les énergies destructives$ (2), $Suggestion$ (DD 17)\n2e - $Soins modérés$ (2), $Sagesse du hibou$, $Silence$ (2) (DD 16), $nuée grouillante$\n1er - $Imprécation$ (DD 15), $Bénédiction$, $Soins légers$, $Anathème$ (DD 15), endurance aux énergies destructives†, $Sanctuaire$ (DD 15), escalade arachnéenne\n0 - $Création d\'eau$, $Détection de la magie$ (3), $Détection du poison$, $Purification de nourriture et d\'eau$\nD : sort de domaine. Divinité : Lolth. Domaines : Drow, Araignée\n† déjà lancé\nCapacités magiques : (NLS 12) :\n1/jour - $Clairaudience/clairvoyance$, $Lumières dansantes$, $Ténèbres$, $Détection du bien$, $Détection du mensonge$ (DD 7), détection de la magie, $Dissipation de la magie$, $Lueur féerique$, $Lévitation$, $Suggestion$ (DD 16)\nCaractéristiques : Force 10, Dex 10, Con 10, Int 15, Sag 18, Cha 16\nParticularités : capacité à remarquer les portes secrètes ou dissimulées, aura maléfique, utilisation de l\'empoisonnement\nDons : #Vigilance#, #Magie de guerre#, #Drow de haute naissance#* , #Science de l\'initiative#, Réflexes fulgurants, Bénédiction de Lolth*\nCompétences : Concentration +15 (+19 pour lancer des sorts défensifs), Diplomatie +18, Connaissances (religion) +17, Perception auditive +8, Fouille +2, Art de la magie+17, Détection +8\nPossessions : équipement de combat plus une cuirasse +1, un bouclier en acier léger +1, un fouet à crocs* , 37 po, 16 po\nVulnérabilité à la lumière (Ext). Une exposition soudaine à une lumière vive (telle que la lumière du soleil ou un sort Lumière du jour) rend Aunrae aveugle pendant 1 round. De plus, elle subit un malus de -1 aux jets d\'attaque, aux jets de sauvegarde et aux tests lorsqu\'elle se trouve en pleine lumière', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2244);

