-- 2246 — Fantassin d'élite Zhentilar
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2246, 'Fantassin d\'élite Zhentilar', 28, NULL, 'PV : 52 (7 DV)\nHumain Chondathien guerrier 7\nN Humanoïde de taille moyenne\nInitiative : +1 ; Perception auditive + 0, Détection + 0\nLangues : Commun, Chondathien\nClasse d\'armure : 21, contact 11, pris au dépourvu 20\nJets de sauvegarde : Vig +7, Réf +3, Vol + 2\nVitesse de déplacement : 6m (4 cases) en demi-plaque, Vitesse de base 9m\nMêlée : épée longue +2 +14/+9 (1d8+8/19-20/×2)\nAttaque de base/lutte : +7/+10\nOptions de combat : #Enchaînement#, #Tir de loin#, #Succession d’enchainements#, #Tir à bout portant#, #Attaque en puissance#, #Tir de précision#\nÉquipement de combat : potion de soin des blessures modérées (2)\nCaractéristiques : For 17, Dex 13, Con 14, Int 8, Sag 10, Cha 12\nDons : #Enchaînement#, #Succession d’enchainements#, #Attaque en puissance#, #Attaque éclair#, #Arme de prédilection# (épée longue), #Spécialisation martiale# (épée longue), #Science de l\'initiative#, science du critique (épée longue)\nCompétences : Escalade +5, Intimidation +6, Équitation +6\nPossessions : équipement de combat plus armure de demi plaque +1, bouclier d’acier lourd de maître, +1 épée longue, arc court composite +1 (+3 bonus de For) avec 20 flèches, 17 po, 3 pa', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2246);

-- 2247 — Le Susurrus
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2247, 'Le Susurrus', 26, NULL, '184 points de vie (16 DV) ; régénération 5\nRD : 10/magie et 5/fer\nFemelle wendigo Démon touché par Lolth Gigantesque araignée monstrueuse chasseuse\nCM Fée gigantesque (froid, extraplanaire)\nInitiative : +11\nSens : vision dans le noir 18 m, vision nocturne, détection des tremblements 18 m ; Perception auditive +1, Détection +9\nLangues : Sylvestre\nClasse d\'armure : 24, contact 14, pris au dépourvu 17\nChance d\'échapper à une attaque 50 % (lorsqu\'il utilise le marche du vent )\nImmunités : au froid, à la terreur\nRésistances : au feu 10\nRM : 21\nJets de sauvegarde : Vig +17, Réf +14, Vol +8\nFaiblesse : vulnérabilité au feu\nVitesse de déplacement : vol 120 m (parfait) ; marche du vent\nMêlée : morsure +20 (2d8+18/18–20/×3 plus empoisonnement plus maladie plus morsure vorace)\nAttaque de base/lutte : +12/+36\nOptions d\'attaque : murmures affolants, frappe magique, empoisonnement (DD 25, 2d6 Force/2d6 Force), Châtiment du bien 1/jour (+16 dégâts)\nCaractéristiques : Force 35, Dex 25, Con 24, Int 3, Sag 12, Cha 6\nParticularités : coin de l\'œil\nDons : #Science de l\'initiative#, #Science de la robustesse#, #Volonté de fer#, #Réflexes surhumains#, #Charge en puissance#, #Pistage#\nCompétences : Escalade +31, Discrétion +11, Saut +22, Perception auditive +1, Déplacement silencieux +19, Détection +9, Survie +9\nCoin de l\'œil (Sur) Lorsqu\'il traque ses victimes grâce à la marche divine, le Susurrus semble toujours se cacher juste au coin du champ de vision mystique de sa victime. La victime subit une pénalité de -2 à tous ses jets de Sagesse tant que le wendigo la traque\nMaladie (Sur) Toute créature touchée par l\'attaque de morsure du Susurrus doit réussir un jet de Vigueur DD 25 ou être infectée par la faim du wendigo. La période d\'incubation est de 1d3 jours, et la maladie inflige 1d3 points de dégâts de Sagesse. De plus, chaque jour où la victime subit des dégâts de Sagesse dus à la maladie, elle doit réussir un jet de Volonté DD 16 ou être submergée par une faim insatiable pour la chair de sa propre race. La victime traque et tente de tuer le membre le plus proche de sa propre race ; si elle y parvient, elle se nourrit du corps de la victime, puis retourne chez elle sans aucun souvenir de cet événement tragique. Si une victime de cette faim voit sa Sagesse réduite à 0, elle se transforme immédiatement en wendigo et s\'enfuit dans le ciel nocturne à une telle vitesse que ses pieds se transforment en moignons sanglants et carbonisés\nMurmures affolants (Sur). Le Susurrus peut utiliser ses murmures affolants sur une cible dans un rayon de 40m une fois par jour. Le Susurrus peut utiliser cette caractéristique pendant qu\'il utilise marche du vent . Seule la victime élue peut entendre les murmures et les invitations insensées du wendigo. La victime doit réussir un jet de Sauvegarde de Volonté DD 16 ou subir 1d3 points de dégâts de Sagesse\nMorsure vorace (Ex). Une blessure résultant d\'un coup critique saigne pour 3 points de dégâts supplémentaires par round par la suite. Les blessures multiples résultant de telles attaques entraînent une perte de sang cumulative. Le saignement ne peut être arrêté que par un jet de Premiers secours DD 10 ou par l\'application d\'un sort de soin ou d\'un autre sort de guérison (guérison, cercle de guérison, etc.)\nRégénération (Ext). Le feu inflige des dégâts normaux au Susurrus. Si le Susurrus perd un membre ou une partie du corps, la partie perdue repousse en 3d6 minutes. La créature peut rattacher instantanément le membre sectionné en le maintenant contre le moignon\nmarche du vent (Ext). Le Susurrus peut se déplacer à volonté dans le vent, passant de sa forme physique à une forme incorporelle ou inversement en tant qu\'action de déplacement', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2247);

-- 2248 — Sentinelle Saguarao
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2248, 'Sentinelle Saguarao', 30, NULL, 'PV : 138 chacune (12 DV)\nRD : D10/perforant\nN Très grande plante\nInitiative : –1\nSens : vision nocturne ; Perception auditive +3, Détection +8\nLangues : Sylvestre\nClasse d\'armure : 22, contact 7, pris au dépourvu 22\nImmunités : sorts et capacités affectant l\'esprit, empoisonnement, sommeil, paralysie, métamorphose\nJets de sauvegarde : Vig +15, Réf +3, Vol +5\nVitesse de déplacement : 6m (4 cases)\nMêlée : 2 coups +18 chacun (3d6+11)\nEspace : 4,5m ; Portée 4,5m\nAttaque de base/lutte : +9/+28\nOptions d\'attaque : Coup fabuleux, Science de la bousculade, #Attaque en puissance#, Épines, Piétinement 3d6+16\nCaractéristiques : Force 33, Dex 8, Con 25, Int 10, Sag 13, Cha 14\nParticularités : traits végétaux, chair résistante\nDons : #Vigilance#, #Coup fabuleux#, #Science de la bousculade#, #Arme naturelle supérieure#, #Attaque en puissance#\nCompétences : Déguisement +2 (+14 pour ressembler à une plante inanimée), Intimidation +12, Connaissances (nature) +10, Perception auditive +3, Détection +8, Survie +6 (+8 au-dessus du sol)\nChair résistante (Ext). La chair d\'un saguaro sentinelle est robuste et retient l\'eau dans les conditions les plus difficiles. Elle ne subit pas de dégâts supplémentaires dus aux sorts et effets de déshydratation (y compris la flétrissure) comme le font normalement les plantes\nÉpines (Ex). Le corps d\'un saguaro sentinelle est recouvert d\'épines. Celles-ci déchirent toute créature qui les touche, infligeant 1d6 points de dégâts perforants. Les créatures qui frappent un saguaro sentinelle avec des attaques naturelles ou des coups à mains nues subissent ces dégâts, mais pas celles qui frappent avec des armes de mêlée. Une créature poussée contre la plante ou tombant dessus subit également des dégâts\nPiétinement (Ext). Dégâts 3d6+16, Réflexes DD 27 demi-dégâts', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2248);

-- 2253 — Golem de chair draconique
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2253, 'Golem de chair draconique', 3, NULL, 'PV : 205 (30 DV)\nRD : 15/adamantite\nCréature artificielle de très grande taille, N\nInitiative : +0\nSens : vision aveugle 45m, vision dans le noir 18m, vision dans la pénombre, Perception auditive +3, Détection +3\nAura : Présence effrayante 9m\nLangues : ne peut pas parler, comprend le commun\nClasse d\'armure : 24, toucher 7, pris au dépourvu 24\nImmunités : contre les dégâts aux caractéristiques, le drain de caractéristiques, les coups critiques, les effets mortels, la mort par dégâts massifs, les maladies, l\'absorption d\'énergie, l\'épuisement, la fatigue, la magie, les sorts et capacités affectant l\'esprit (charme, contrainte, fantasmes, schémas et effets sur le moral), les effets de nécromancie, les dégâts non létaux, la paralysie, l\'empoisonnement, les effets de sommeil, l\'étourdissement, tout effet nécessitant un jet de Vigueur sauf s\'il fonctionne également sur les objets ; immunité contre la magie\nJets de sauvegarde : Vig +10, Réf +9, Vol +13\nVitesse de déplacement : 12m (8 cases) (ne peut pas courir), vol 36m (mauvais)\nMêlée : morsure +30 (3d6+10) et\n2 griffes +25 chacune (2d6+5) et\n2 ailes +25 chacune (1d8+5) et\ncoup de queue +25 (2d6+15)\nEspace : 4,5m ; Portée 3m (4,5m avec morsure)\nAttaque de base/lutte : +22/+40\nCaractéristiques : Force 30, Dex 9, Con —, Int 4, Sag 17, Cha 17\nParticularités : traits de créature artificielle, immunité à la magie\nPrésence effrayante (Ext). Un golem de chair draconique peut déstabiliser ses ennemis par sa simple présence. Cette capacité s\'active automatiquement lorsqu\'il attaque, charge ou vole au-dessus d\'eux. Les créatures situées à moins de 9 mètres sont soumises à cet effet si elles ont moins de 30 DV. Une créature potentiellement affectée qui réussit un jet de sauvegarde DD 28 reste immunisée contre la présence effrayante du golem pendant 24 heures. En cas d\'échec, les créatures avec 4 DV ou moins sont paniquées pendant 4d6 rounds et celles avec 5 DV ou plus sont secouées pendant 4d6 rounds\nImmunité à la magie (Ext). Un golem de chair draconique est immunisé contre tous les sorts ou capacités magiques qui permettent une résistance à la magie. De plus, certains sorts et effets fonctionnent différemment contre cette créature, comme indiqué ci-dessous. Une attaque magique qui inflige des dégâts de froid ou de feu ralentit le golem (comme le sort lenteur) pendant 2d6 rounds sans jet de sauvegarde. Une attaque magique qui inflige des dégâts de foudre annule tout effet de lenteur sur le golem et lui accorde une guérison suprême égale à 1 point de dégâts pour chaque tranche de 3 points de dégâts que l\'attaque aurait normalement infligés. Un golem de chair draconique ne bénéficie d\'aucun jet de sauvegarde contre les attaques qui infligent des dégâts de foudre\nManuel des Monstre 2\nFigurine : dracoliche', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2253);

-- 2254 — Géants de Phaerlin (Enragés)
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2254, 'Géants de Phaerlin (Enragés)', 27, NULL, 'Monstres de Faerun\nPV : 146 chacun (13 DV)\nGéant de phaerlin mâle ou femelle barbare 5\nNM géant de Très grand taille (terre)\nInitiative : +3\nSens : vision nocturne, odorat ; Perception auditive +6, Détection +7\nAura : Présence effrayante 9 m\nLangues : commun, géant\nClasse d\'armure : 19, toucher 6, pris au dépourvu 19 ; Esquive instinctive supérieure\nRM : 19\nJets de sauvegarde : Vig +16, Réf +2, Vol +4\nVitesse de déplacement : 6m (4 cases) en armure de discrétion, vitesse de base 9m\nMêlée : 2 griffes +18 chacune (2d4+8) et morsure +16 (1d8+4)\nEspace : 4,5 m ; Portée 4,5 m\nAttaque de base/lutte : +11/+23\nOptions d\'attaque : Enchaînement, Attaque en puissance, rage 2/jour (9 rounds)\nCaractéristiques : Force 26, Dex 9, Con 22, Int 8, Sag 8, Cha 9\nParticularités : sens des pièges +1\nDons : #Vigilance#, #Enchaînement#, #Science de la bousculade#, #Science de l\'initiative#, #Attaques multiples#, #Attaque en puissance#\nCompétences : Escalade +13, Saut +9, Perception auditive +6, Détection +7, Survie +2\nPossessions : armure de discrétion\nPrésence effrayante (Ext). Un géant de phaerlin engage le combat par un rugissement effrayant qui sème la terreur dans le cœur de ses ennemis. Les créatures situées à moins de 9 mètres sont soumises à cet effet si elles ont moins de 13 DV. Une créature potentiellement affectée qui réussit un jet de sauvegarde DD 15 reste immunisée contre la présence effrayante du géant pendant 24 heures. En cas d\'échec, la créature est secouée pendant 4d6 rounds', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2254);

-- 2255 — Sentinelles Saguaro
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2255, 'Sentinelles Saguaro', 30, NULL, 'San\nPV : 138 chacune (12 DV) ; RD 10/perforant\nN Plante de Très grande taille\nInit –1\nSens : vision nocturne ; Perception auditive +3, Détection +8\nLangues : Sylvestre\nClasse d\'armure : 22, toucher 7, pris au dépourvu 22\nImmunités : contre les sorts et capacités affectant l\'esprit, l\'empoisonnement, le sommeil, la paralysie, la métamorphose\nJets de sauvegarde : Vig +15, Réf +3, Vol +5\nVitesse de déplacement : 6m (4 cases)\nMêlée : 2 coups +18 chacun (3d6+11)\nEspace : 4,5m ; Portée 4,5m\nAttaque de base/lutte : +9/+28\nOptions d\'attaque : Coup fabuleux, Science de la bousculade, Attaque en puissance, Épines, Piétinement 3d6+16\nCaractéristiques : Force 33, Dex 8, Con 25, Int 10, Sag 13, Cha 14\nParticularités : traits végétaux, chair coriace\nDons : Vigilance, Coup fabuleux, Science de la bousculade, Arme naturelle supérieure, Attaque en puissance\nCompétences : Déguisement +2 (+14 pour ressembler à une plante inanimée), Intimidation +12, Connaissances (nature) +10, Perception auditive +3, Détection +8, Survie +6 (+8 au-dessus du sol)\nÉpines (Ext). Le corps d\'un saguaro sentinelle est recouvert d\'épines. Celles-ci déchirent toute créature qui les touche, infligeant 1d6 points de dégâts perforants. Les créatures qui frappent un saguaro sentinelle avec des attaques naturelles ou à mains nues subissent ces dégâts, mais pas celles qui l\'attaquent avec des armes de mêlée. Une créature poussée contre la plante ou tombant dessus subit également des dégâts\nPiétinement (Ex). DD de réflexes 27 pour moitié', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2255);

-- 2256 — Esclaves génasis de terre
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2256, 'Esclaves génasis de terre', 25, NULL, 'PV : 12 chacun (2 DV)\nGénasis de terre mâle ou femelle expert 1\nN Extérieur de taille moyenne\nInitiative : +0\nSens : Perception auditive -2, Détection -2\nLangues : Commun, Terreux\nClasse d\'armure : 12, toucher 10, pris au dépourvu 12\nJets de sauvegarde : Vig +4, Réf +2, Vol +2 ; +1 contre les sorts et effets liés à la terre\nVitesse de déplacement : 9m (6 cases)\nMêlée : pic de guerre léger +2 (1d4+1/×4)\nAttaque de base/lutte : +1/+2\nCaractéristiques : Force 13, Dex 10, Con 14, Int 11, Sag 7, Cha 8\nParticularités : traits d\'exterieur, fusion avec la pierre\nDons : #Robustesse#\nCompétences : Estimation +4, Escalade +5, Artisanat (forge) +4, Artisanat (taille de pierre) +4, Discrétion +4, Connaissances (architecture et ingénierie) +4, Connaissances (plans) +4, Profession (mineur) +4, Survie +2\nPossessions : Pic de guerre léger\nFusion avec la pierre (Mag). Une fois par jour, un genasi de terre peut lancer Passage sans trace comme un druide de niveau 5', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2256);

-- 2257 — Cube gélatineux
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2257, 'Cube gélatineux', 31, NULL, 'PV : 18 (4 DV)\nN vase de grande taille\nInit –5\nSens : vision aveugle 18 m ; Perception auditive –5, Détection –5\nClasse d\'armure : 4, toucher 4, pris au dépourvu 4\nImmunités : contre l\'électricité, les sorts et capacités affectant l\'esprit, le regard et les attaques visuelles\nJets de sauvegarde : Vig +9, Réf -4, Vol -4\nVitesse de déplacement : 4,5m (3 cases) (immobile dans la fosse)\nMêlée : coup +2 (1d6 plus 1d6 acide)\nEspace : 3m ; Portée 1,5m\nAttaque de base/lutte : +3/+7\nOptions d\'attaque : acide, engloutir, paralysie\nCaractéristiques : Force 10, Dex 1, Con 26, Int —, Sag 1, Cha 1\nParticularités : traits de vase\nAcide (Ext). L\'acide d\'un cube gélatineux ne met pas à mal le métal ou la pierre\nEngloutir (Ext). Un cube gélatineux peut normalement engloutir des créatures de taille Grande ou plus petite en tant qu\'action standard. Le cube gélatineux du piège décrit ici peut engloutir une créature de taille Grande ou inférieure en tant qu\'action gratuite, mais uniquement immédiatement après le déclenchement du piège. Une créature qui tombe sur le vase peut effectuer un jet de réflexes DD 13 pour éviter d\'être engloutie, comme d\'habitude, mais elle ne peut pas choisir d\'effectuer une attaque d\'opportunité à la place du jet de réflexes. Une créature engloutie est soumise à l\'acide et à la paralysie du cube, et est considérée comme étant aux prises avec lui et piégée à l\'intérieur de son corps.\nEn cas de jet de sauvegarde réussi, la créature a réussi à atterrir à la surface du vase sans y tomber. Le cube gélatineux ne peut pas engloutir une telle créature lors d\'un round ultérieur, car il est piégé dans la fosse et incapable de bouger\nParalysie (Ext). Un cube gélatineux sécrète un mucus anesthésiant. Une cible touchée par le coup du cube ou qui a été engloutie doit réussir un jet de DD de Vigueur DD 20 ou être paralysée pendant 3d6 rounds', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2257);

-- 2258 — Nécrophages de poussière (évolués)
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2258, 'Nécrophages de poussière (évolués)', 1, NULL, 'PV : 120 chacun (16 DV) ; guérison rapide 3\nRD : 5/adamantite\nCM Mort-vivant de taille moyenne (terre)\nInitiative : –1\nSens : vision dans le noir 18 m ; Perception auditive +11, Détection +11\nLangues : Terreux\nClasse d\'armure : 23, toucher 10, pris au dépourvu 22\nImmunités : immunités des morts-vivants\nJets de sauvegarde : Vig +7, Réf +5, Vol +10\nFaiblesse : vulnérabilité au renvoi des élémentaires\nVitesse de déplacement : 12m avec rapidité (8 cases) ; vitesse de base 6m\nMêlée : 3 coups +12 chacun (2d6+9/19–20)*\n* Attaque en puissance à 3 points\nAttaque de base/lutte : +8/+14\nOptions d\'attaque : Science de la destruction, Attaque en puissance, Contact fragilisant\nActions spéciales : Nuage pétrifiant\nCapacités magiques : (NLS 16) : 1/jour —invisibilité suprême†, rapidité†\n† déjà utilisé\nCaractéristiques : Force 23, Dex 8, Con —, Int 8, Sag 11, Cha 13\nParticularités : traits de mort-vivant\nDons : #Vigueur surhumaine#, #Science du critique# (coup), #Arme naturelle supérieure# (coup), #Science de la destruction#, #Science de la robustesse#, #Attaque en puissance#\nCompétences : Discrétion +11, Perception auditive +11, Déplacement silencieux +11, Fouille +10, Détection +11\nContact fragilisant (Sur). En plus d\'infliger des dégâts, l\'attaque de coup du nécrophage de poussière affaiblit les objets manufacturés en pierre ou en métal. Chaque fois qu\'une créature est touchée par cette attaque, son armure, si elle est en pierre ou en métal, subit 2d8+10 points de dégâts (Vigueur, DD 23, annule). Si l\'objet est détruit, le monstre gagne 5 points de vie temporaires (valables pendant 1 heure). Le DD de sauvegarde est lié à la Force. L\'attaque de coup du nécrophage de poussière inflige des dégâts doublés contre les créatures et les objets en bois ou en métal, comme le garde animé ou le golem de pierre\nNuage pétrifiant (Sur). Ce monstre est entouré d\'un nuage de grains de poussière. Toute créature vivante située dans un rayon de 1,50 mètre de ce mort-vivant doit réussir un jet de Vigueur (DD 18) sous peine d\'être pétrifiée 1 round plus tard. Cela lui laisse cependant le temps de bénéficier de façonnage de la pierre ou de glissement de terrain pour enrayer la pétrification. Si la victime réussit son jet de sauvegarde, elle ne peut plus être affectée par le nuage de poussière de ce nécrophage pendant 24 heures. Le DD de sauvegarde est lié au Charisme\nVulnérabilité au renvoi des élémentaires (Ext). Un personnage qui peut repousser les morts-vivants et les élémentaires de la Terre bénéficie d\'un bonus de +2 aux tests de renvoi contre les nécrophage de poussière. Un personnage qui peut intimider les morts-vivants et les élémentaires de la Terre bénéficie d\'un bonus de +2 aux tests d\'intimidation contre les nécrophage de poussière\nManuel des monstres 3\nFigurines : squelettes WB à customiser', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2258);

-- 2259 — Holocauste élémentaire
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2259, 'Holocauste élémentaire', 24, NULL, 'PV : 112 chacun (15 DV) ; régénération 5\nRD : 15/magie et bien\nCM élémentaire de petite taille (air, extérieur, feu)\nInitiative : +9\nSens : vision dans le noir 18 m ; Perception auditive +21, Détection +21\nAura : aura de feu 9 m\nLangues : Abyssal, Auran, Ignan\nClasse d\'armure : 16, toucher 16, pris au dépourvu 11\nImmunités : feu, empoisonnement, sommeil, paralysie, étourdissement\nRM : 24\nJets de sauvegarde : Vig +8, Réf +14, Vol +10\nFaiblesse : vulnérabilité au froid\nVitesse de déplacement : vol 15 m (10 cases) (parfait) ; ne peut pas courir\nMêlée : pointe de vent enflammée +18/+13/+8 (1d6/19-20 plus 1d6 de feu) ou\nMêlée : contact +18/+13/+8 (1d6 de feu)\nAttaque de base : +11\nLutte : —\nEspace occupé/allonge : 1,50 m/1,50 m\nOptions d\'attaque : maîtrise de l\'air, brûlure, tornade de feu\nCaractéristiques : Force —, Dex 20, Con 17, Int 14, Sag 16, Cha 15\nParticularités : sous-type aérien, traits élémentaires, sous-type feu, gazeux\nDons : #Attaques réflexes#, #Science du critique# (pointe de vent enflammée), #Science de l\'initiative#, #Volonté de fer#, #Attaque en finesse#, #Arme de prédilection# (pointe de vent enflammée)\nCompétences : Diplomatie +4, Discrétion +17* , Perception auditive +21, Psychologie +21, Détection +21\nAura de feu (Ext). Quiconque se trouve dans un rayon de 9 mètres de l\'holocauste élémentaire doit réussir un jet de Vigueur (DD 20) sous peine de subir 1d6 points de dégâts de feu causés par l\'intense chaleur qu\'il dégage. Traitez cet effet comme un rayonnement que la créature dégage en permanence. Le DD de sauvegarde est lié à la Constitution\nDépart de feu (Ext). Toute créature touchée par une attaque de lance de feu d\'un holocauste élémentaire doit réussir un jet de Réflexes (DD 20) sous peine de s\'enflammer (voir Prendre feu, page 302 du Guide du Maître). Les flammes continuent de brûler pendant 1d4 rounds. Une créature en feu peut éteindre les flammes si elle y consacre une action de mouvement. Le DD de sauvegarde est lié à la Constitution\nLance de feu (Ext). Bien qu\'il ait une forme gazeuse, l\'holocauste élémentaire peut prendre la forme d\'une pique d\'air et de feu surchauffée infligeant 1d6 points de dégâts plus 1d6 points de dégâts de feu. Le monstre peut également porter une attaque de contact au corps à corps pour infliger 1d6 points de dégâts de feu\nTornade de feu (Sur). L\'holocauste élémentaire peut se transformer en tornade de feu une fois toutes les 10 minutes et conserver cette forme jusqu\'à 1 round pour chaque tranche de 2 DV possédée. Sous cette forme, la créature peut se déplacer dans les airs ou à la surface des solides et des liquides à une vitesse de déplacement de 18 mètres par round (manœuvrabilité parfaite). La tornade de feu mesure 1,50 mètre à sa base, 3 à 6 mètres de haut, et 3 à 9 mètres de large en son sommet. Le monstre adopte la taille de son choix tant qu\'elle rentre dans ces paramètres.\nLes créatures prises dans la tornade de feu subissent 3d6 points de dégâts de feu par round. En outre, les créatures de taille G ou inférieure subissent les dégâts dus au vent et peuvent être soulevées dans les airs. Il leur faut donc réussir un jet de Réflexes (DD 20) sous peine de subir 2d6 points de dégâts en raison de la force des vents. Elles doivent en réussir un second sous peine d\'être soulevées et maintenues dans les airs par les vents puissants et les flammes brûlantes. Les créatures volantes ont droit à un jet de Réflexes (DD 20) par round pour fuir la tornade. En cas de succès, elles parviennent à s\'échapper mais subissent tout de même les dégâts.\nL\'holocauste élémentaire peut éjecter les créatures qu\'il renferme dès qu\'il le souhaite, les laissant alors là où il se trouve.\nLes DD de sauvegarde sont liés au Charisme et incluent un bonus racial de +1\nVents embrasés (Sur). Les holocaustes élémentaires dominent les vents d\'une zone donnée à volonté, les emplissant de flammes. Ce pouvoir fonctionne sur le même principe que le sort $contrôle des vents$ (niveau 10 de lanceur de sorts), si ce n\'est que les créatures et objets situés dans la zone d\'effet subissent également 3d6 points de dégâts de feu par round (jet de Réflexes, DD 20, demi dégâts). Le monstre peut user de ce pouvoir ou le réprimer à volonté au prix d\'une action simple, mais seule une application de ce pouvoir peut opérer à un moment donné. Le DD de sauvegarde est lié au Charisme et inclut un bonus racial de +1\nCréature du Feu (Ext). Immunisé contre le feu, mais vulnérable au froid, ce qui signifie qu\'il subit S0 % de dégâts en plus face aux attaques de froid, qu\'un jet de sauvegarde soit autorisé ou pas (et qu\'il soit réussi ou non)\nÉlémentaire (Ext). Immunité contre le poison, les effets de sommeil, la paralysie, l\'étourdissement, les coups critiques et la prise en tenaille. Les holocaustes élémentaires bénéficient de la vision dans le noir sur 18 mètres. Ils ne peuvent pas être rappelés à la vie ou ressuscites (sauf par miracle, résurrection suprême, souhait ou souhait limité)\nGazeux (Ext). Le corps de l\'holocauste élémentaire est naturellement gazeux (comme s\'il était sous l\'effet d\'un sort d\'état gazeux). Malgré tout, il est doué de parole, peut lancer des sorts à composantes verbales et use de pouvoirs surnaturels. Il peut passer par le moindre trou ou la plus petite fissure. Par contre, il est incapable de courir\nMaîtrise de l\'Air (Ext). Les holocaustes élémentaires bénéficient d\'un bonus de +1 aux jets d\'attaque et de dégâts contre les créatures volantes\nRégénération (Ext). Seuls le froid et les armes saintes, bénies ou dotées d\'un bonus d\'altération de +2 au moins infligent des dégâts létaux aux holocaustes élémentaires. Les formes d\'attaque qui n\'infligent pas de points de dégâts ignorent le pouvoir. Enfin, ces monstres ne regagnent pas les points de vie perdus pour cause de malnutrition, de déshydratation ou d\'asphyxie\nCompétences. La chaleur et la lumière que l\'holocauste élémentaire dégage lui imposent un malus de -10 aux tests de Discrétion\n---\n* Il lui est donc presque impossible de se dissimuler, mais dans les zones habitées par les flammes (comme une maison en feu) et les brasiers, il bénéficie d\'un bonus racial de +10 aux tests de Discrétion\nFiend Folio\nFigurine : à définir', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2259);

-- 2260 — Vestige onirique
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2260, 'Vestige onirique', 1, NULL, 'PV : 110 (17 DV)\nRD : 10/—\nCM mort-vivant de Très Grande taille (immatériel)\nInitiative : +9\nSens : vision aveugle 36m, vision dans le noir 18m ; Perception auditive +25, Détection +25\nAura : aura de profanation 6m, présence effrayante 18m, aura déflectrice\nLangues : toutes les langues courantes en Faerûn, y compris le thoross et le netherisse\nClasse d\'armure : 31, contact 31, pris au dépourvu 26\nImmunités : immunités des morts-vivants ; ne peut être blessé que par d\'autres créatures incorporelles, des armes magiques, des sorts, des capacités magiques ou des capacités surnaturelles\nRésistances : 50 % de chances d\'ignorer tout dégât provenant d\'une source corporelle (à l\'exception des effets de force et des attaques effectuées avec des armes spectrales)\nRM : 28\nJets de sauvegarde : Vig +9, Réf +14, Vol +19\nVitesse de déplacement : vol 12m (8 cases) (parfait) ; peut traverser les objets solides (mais pas les effets de force) à volonté, déplacement silencieux (ne peut être entendu avec des tests de Perception auditive sauf s\'il le souhaite) ; Voyage onirique\nMêlée : 4 vrilles +15 chacune (3d6+2 plus absorption de forme)\nEspace occupé/allonge : 4,5m/6m\nAttaque de base/lutte : +8/+16\nOptions d\'attaque : Attaques réflexes, consommation de matière\nCaractéristiques : Force —, Dex 20, Con —, Int 18, Sag 20, Cha 20\nParticularités : voyage dans les songes, traits incorporels, auto-génération, traits de mort-vivant\nDons : #Attaques réflexes#, #Vigueur surhumaine#, #Volonté de fer#, #Science de l\'initiative#, #Réflexes surhumains#, #Attaque en finesse#\nCompétences : Concentration +25, Diplomatie +7, Discrétion +17, Perception auditive, Déplacement silencieux +25, Fouille +24, Psychologie +25, Art de la magie+24, Détection +25, Survie +5 (+7 après pistage)\nAura profane (Sur). Le vestige onirique dégage une émanation de 6 mètres de rayon de profanation totale et imprègne son environnement d\'énergie négative. Ce pouvoir fonctionne sur le même principe que le sort $profanation$, si ce n\'est que le monstre lui-même est considéré comme l\'autel d\'une puissance du Mal. Tous les morts-vivants situés dans un rayon de 6 mètres (ce quiinclucle vestige onirique) bénéficient d\'un bonus de malfaisance de +2 aux jets d\'attaque,jets de dégâts et jets de sauvegarde, mais également de 2 points de vie supplémentaires par dé de vie. Le profil du vestige onirique donné ci-dessus inclut déjà ces bonus de malfaisance. Les tests de Charisme effectués dans la zone pour renvoyer les morts-vivants subissent un malus de - 6.\nL\'aura profane d\'un vestige onirique ne peut pas être dissipée, si ce n\'est par rejet du Mal ou quelque effet similaire. En cas de dissipation, le monstre peut réactiver ce pouvoir au prix d\'une action libre dès que revient son tour de jeu. Son aura est réprimée si le vestige onirique pénètre dans une zone consacrée ou sanctifiée, mais cette dernière l\'est également en raison de la présence du monstre.\nConsommation de forme (Su). Chaque contact avec une vrille d\'un vestige onirique draine une partie de l\'esprit de la victime (bien que les créatures non intelligentes ou dépourvues d\'esprit soient immunisées contre les caresses lascives d\'un vestige onirique). Chaque contact inflige 1d4 points de drain d\'Intelligence à la victime. Lorsqu\'un vestige de rêve draine l\'Intelligence d\'une victime, il gagne 5 points de vie temporaires, quel que soit le nombre de points drainés. Si un vestige de rêve acquiert un nombre de points de vie temporaires égal à son total de points de vie normaux, il se régénère (voir ci-dessous).\nAu début de l\'action suivante d\'un vestige onirique après qu\'une créature a été vidée de son intelligence, le corps de la victime est automatiquement englouti et dissous par le vestige onirique, ne laissant rien derrière lui, pas même de la poussière.\nPrésence terrifiante (Sur). Le vestige onirique inspire la terreur dès qu\'il charge ou attaque. Les créatures affectées doivent réussir un jet de Volonté (DD 23) sous peine d\'être secouées, restant alors dans cet état tant qu\'elles se situent dans un rayon de 18 mètres du monstre. Une cible qui réussit son jet de sauvegarde ne peut plus être affectée par la présence terrifiante de ce vestige onirique pendant 24 heures. Le DD de sauvegarde est lié au Charisme.\nAura de parade (Sur). Ce monstre est protégé par une puissante aura d\'énergie onirique. Celle-ci augmente son bonus de parade à la CA de +13 (en plus de son bonus de parade de +5 dû à son intangibilité), ce qui est inclus dans le profil ci-dessus.\nRejeton spontané (Ext). Dès que le vestige onirique a gagné un nombre de points de vie temporaires égal à son total de points de vie, il crée un rejeton, se divisant ainsi en deux monstres identiques, chacun pourvu d\'autant de points de vie que le monstre original.\nSoif inextinguible. Le vestige onirique a une soif de corps inextinguible (cf. la section Métabolisme des morts-vivants du Chapitre 1), qu\'il assouvit en usant de son pouvoir d\'absorption de forme.\nVoyage onirique (Sur). Au prix d\'une action simple, le vestige onirique peur pénétrer dans le monde des rêves et laisser derrière lui le monde de l\'éveil. Pour chaque minute passée dans le monde des rêves, le monstre parcourt 7,5 kilomètres dans le monde éveillé. S\'il le souhaite, le monstre peut également voyager ainsi entre les plans. Le vestige onirique sait toujours où il va apparaître quand il réintègre le monde éveillé.\nLibris Mortis\nFigurine : socle figurine avec du coton dessus', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2260);

-- 2261 — Skorpiogéant
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2261, 'Skorpiogéant', 3, NULL, 'PV : 235 (17 DV+80)\nRD : 15/—\nLM créature artificielle de très grande taille (augmenté)\nInitiative : +6\nSens : vision dans le noir 18 m, Perception des vibrations 18 m ; Perception auditive +8, Détection +8\nAura : désespoir\nLangues : tlincalli\nClasse d\'armure : 34, contact 15, pris au dépourvu 32\nImmunités : créature artificielle (charmes, coercition, fantasmes, mirages et effets de mora, poison, les effets de sommeil, la paralysie, l’étourdissement, les maladies, les effets de mort et les effets de nécromancie, les coups critiques, les dégâts non-létaux, les affaiblissements temporaires de caractéristique, les diminutions permanentes de caractéristique, l’épuisement et l’absorption d’énergie, les effets nécessitant un jet de Vigueur - sauf quand ils affectent également les objets ou quand ils sont inoffensifs, la mort par dégâts excessifs)\nJets de sauvegarde : Vig +12, Réf +7, Vol +7\nFaiblesses : Ne peuvent soigner les dégâts, mais peuvent être réparées par un certain type d’effet ou par le biais du don Création de créature artificielle. Destruction immédiate lorsque les points de vie chutent à0 ou moins.\nVitesse de déplacement : 6 m (4 cases), vol (18m, moyen)\nMêlée : dard +18 (1d6+9 plus venin) et 2 Lames +18/+18/+13/+8/+3 chacune (2d6+9)\nAttaque de base/lutte : +7/+18\nOptions d\'attaque : ennemi préféré humains +2, venin (DD 16, 1d6 Force/1d6 Force)\nCaractéristiques : Force 28, Dex 14, Con -, Int 6, Sag 14, Cha 16\nParticularités : magie du refuge, perception des vibrations, empathie sauvage +4 (+0 contre les bêtes magiques)\nDons : #Science de l\'initiative#, #Pistage#, #Combat à deux armes#, #Attaque en puissance#, #Science de la bousculade#, #Coup fabuleux#\nCompétences : Discrétion +6, Perception auditive +8, Déplacement silencieux +5, Fouille +4, Détection +8, Survie +5 (+7 après avoir suivi des traces)\nPerception des vibrations (Ext). un skorpiogéant détermine automatiquement la position de toute créature en contact avec le sol et se trouvant à moins de 18 m\nMagie du refuge (Mag). un skorpiogéant peut se déplacer de 6 m vers le haut ou vers le bas à condition de traverser au moins 0,3 m de terre durant ce déplacement. La créature subit 1d3 points de dégâts chaque fois qu\'elle franchit 1,50 m de terre (ou une fraction de cette distance). Si le déplacement programmé d\'un skorpiocentaure le fait arriver au coeur d\'un objet solide, la créature ne se déplace pas mais subit les dégâts indiqués comme si elle s\'était déplacée à travers la masse de terre en question. Les skorpiocentaures utilisent leur magie du refuge pour se déplacer entre des tunnels préparés de longue date et la surface du sol ou des séiies de tunnels situés les uns au-dessus des autres. Le recours à ce pouvoir magique provoque un éclair de lumière rouge et une odeur ressemblant à celle de la peau d\'un insecte brûlée\nDésespoir (Su). À la simple vue d\'un skorpiogéant, le spectateur doit réussir un jet de sauvegarde DD 16 ou être paralysé par la terreur pendant 1d4 rounds. Que le jet soit réussi ou non, cette créature ne peut plus être affectée par la capacité désespoir du même skorpiogéant pendant 24 heures\nCréation personnelle\nFigurine : scorpion géant Roi des Tombes', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2261);

-- 2262 — chats des cryptes
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2262, 'chats des cryptes', 1, NULL, 'PV : 39 chacun (6 DV)\nRD : 5/contusion\nNM Mort-vivant de grande taille\nInitiative : +6\nSens : vision dans le noir 18 m, odorat ; Perception auditive +4, Détection +4\nClasse d\'armure : 18, toucher 11, pris au dépourvu 16\nImmunités : immunités des morts-vivants\nJets de sauvegarde : Vig +2, R?f +4, Vol +6\nFaiblesse : vulnérabilité au feu\nVitesse de déplacement : 12m (8 cases)\nMêlée : 2 griffes +8 chacune (1d6+5 plus infection) et morsure +5 (1d8+2 plus infection)\nEspace : 3m ; Portée 1,5m\nAttaque de base/lutte : +3/+12\nOptions d\'attaque : infection, saisie améliorée, bond, Coups de griffe 1d8+2 plus maladie\nCaractéristiques : Force 21, Dex 14, Con —, Int 2, Sag 12, Cha 12\nParticularités : traits de mort-vivant\nDons : #Science de l\'initiative#, #Attaques multiples#, #Arme de prédilection# (griffe)\nCompétences : Escalade +8, Discrétion +6, Déplacement silencieux +6, Saut +9, Perception auditive +4, Détection +4\nBond (Ext). Si un chat des cryptes charge un ennemi, il peut effectuer une attaque complète, y compris deux attaques de griffes\nSaisie améliorée (Ext). Pour utiliser cette capacité, un chat des cryptes doit toucher avec une attaque de griffe ou de morsure. Il peut alors tenter d\'engager une lutte en tant qu\'action gratuite sans provoquer d\'attaques d\'opportunité. S\'il remporte le jet de lutte, il établit une prise et peut donner des coups de griffes\nCoups de Griffe (Ext). Bonus d\'attaque +8 en mêlée, 1d8+2 plus maladie\nInfection (Ext). Maladie surnaturelle — griffe ou morsure, DD de Vigueur 14, période d\'incubation 1 round ; la blessure devient rouge et enflammée et ne guérit pas complètement ; 1 point de dégâts par jet de sauvegarde manqué. Même la guérison magique n\'est pas capable de totalement guérir ces blessures, et 1 point de dégâts restent par blessure jusqu\'à ce que la cible soit affectée par un sort de Guérison des maladies ou de Guérison suprême. Une seule occurrence d\'un des sorts suffit à traiter l\'ensemble des blessures infectées d\'une personne. Le DD est lié au Charisme et tient compte d\'un bonus racial de +2\nCompétences. Les chats des cryptes ont un bonus racial de +4 aux tests de Discrétion, Déplacement silencieux et Saut', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2262);

-- 2263 — Hurlemort
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2263, 'Hurlemort', 1, NULL, 'MM3\nPV : 135 (18 DV)\nCM Mort-vivant de taille moyenne (intangible)\nInitiative : +11\nSens : vision dans le noir 18 m ; Perception auditive +17, Détection +17\nAura : désespoir\nLangues : thoross\nClasse d\'armure : 28, toucher 28, pris au dépourvu 21\nImmunités : immunités des morts-vivants ; ne peut être mis à mal que par d\'autres créatures intangibles, des armes magiques, des sorts, des capacités magiques ou des capacités surnaturelles\nRésistances : 50 % de chances d\'ignorer tout dégât provenant d\'une source corporelle (à l\'exception des effets de force et des attaques effectuées avec des armes spectrales) ; +4 en résistance aux renvois\nJets de sauvegarde : Vig +8, Réf +13, Vol +15\nFaiblesse : vulnérabilité au silence\nVitesse de déplacement : vol 12 m (8 cases) (bon) ; peut traverser les objets solides (mais pas les effets de force) à volonté, se déplace silencieusement (ne peut être entendu avec des tests de Perception auditive sauf s\'il le souhaite)\nMêlée : toucher intangible +16 au toucher (1d8 Cha)\nAttaque de base/lutte : +9/+9\nOptions d\'attaque : Attaques réflexes, Diminution permanente de Charisme, Râle de mort, Cri de l\'agonisant\nCaractéristiques : Force —, Dex 25, Con —, Int 8, Sag 14, Cha 20\nParticularités : traits intangibles, traits de mort-vivant\nDons : #Attaque spéciale renforcée# (cri de l\'agonisant)\nCompétences : Discrétion +17, Intimidation +19, Perception auditive +17, Fouille +12, Détection +17\nDiminution permanente de Charisme (Sur). Une créature frappée par le hurlemort doit réussir un jet de Vigueur (DD 24) sous peine de subir une diminution permanente de 1d4 points de Charisme (2d4 points en cas de coup critique), chaque fois qu’il réussit cette attaque, le monstre gagne 5 points de vie temporaires (10 en cas de coup critique). Le DD de sauvegarde est lié au Charisme\nRâle de mort (Sur). Quand les points de vie d’un hurlemort chutent à 0, il pousse un dernier cri dévastateur. Les créatures vivantes situées dans une étendue de 90 mètres de rayon doivent réussir un jet de Volonté (DD 24) sous peine de gagner 1d4 niveaux négatifs. Les créatures dépourvues d’ouïe ou situées dans une zone de silence bénéficient d’un bonus de +4 au jet de sauvegarde. Le DD de sauvegarde est lié au Charisme\nDésespoir (Su). À la simple vue d\'un hurlemort, le spectateur doit réussir un jet de Volonté DD 24 ou être paralysé par la terreur pendant 1d4 rounds\nCri de l’agonisant (Sur). Une fois par jour, au prix d’une action complexe, le hurlemort peut pousser un cri à glacer le sang qui dure jusqu’à 3 rounds. Après le premier round, le monstre peut utiliser une action simple pour maintenir le hurlement. Cette attaque affecte toutes les créatures vivantes situées dans une émanation d’un rayon de 9 mètres centrée sur le hurlemort ou dans un cône de 18 mètres de long s’étendant depuis le monstre, au choix de celui-ci. Une fois la forme de l’effet choisie, il ne peut plus en changer pendant les 3 rounds.\nDans le cas d’un cône, le monstre ne peut viser que dans réussi ou non, la créature ne peut plus être affectée par la vision de ce hurlemort pendant 24 heures. Le DD de sauvegarde est lié au Charisme\nVulnérabilité au silence (Ext). Les hurlemorts ne supportent pas le silence d’autant que celui-ci leur nuit. Pour entrer dans le rayon d’un sort de silence, il leur faut réussir un jet de Volonté (DD 12 + niveau de lanceur de sorts). À chaque round passé dans le rayon d’un sort de silence, le monstre subit 1d10 points de dégâts (Volonté, 1/2 dégâts)', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2263);

-- 2264 — Golems de diamant
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2264, 'Golems de diamant', 3, NULL, 'PV : 107 chacun (14 DV)\nRD : 30/adamantite et magie\nN Créature artificielle de grande taille\nInitiative : +1\nSens : vision dans le noir 18 m, vision nocturne ; Perception auditive +1, Détection +1\nLangues : ne peut pas parler, comprend le thoross\nClasse d\'armure : 29, toucher 10, pris au dépourvu 29\nImmunités : immunité contre la magie, créature artificielle (charmes, coercition, fantasmes, mirages et effets de mora, poison, les effets de sommeil, la paralysie, l’étourdissement, les maladies, les effets de mort et les effets de nécromancie, les coups critiques, les dégâts non-létaux, les affaiblissements temporaires de caractéristique, les diminutions permanentes de caractéristique, l’épuisement et l’absorption d’énergie, les effets nécessitant un jet de Vigueur - sauf quand ils affectent également les objets ou quand ils sont inoffensifs, la mort par dégâts excessifs)\nJets de sauvegarde : Vig +4, Réf +5, Vol +5\nFaiblesse : vulnérabilité au ki, ne peuvent soigner les dégâts, mais peuvent être réparées par un certain type d’effet ou par le biais du don Création de créature artificielle. Destruction immédiate lorsque les points de vie chutent à 0 ou moins.\nVitesse de déplacement : 9 m (6 cases) ; ne peut pas courir\nMêlée : 2 coups +19 chacun (2d6+10)\nEspace occupé/allonge : 3 m/3 m\nAttaque de base/lutte : +10/+24\nOptions d\'attaque : dissipation ciblée\nCapacités de type sort : (NLS 15)\nà volonté — $coup au but$\n3/jour — $rayon de soleil$\nCaractéristiques : Force 31, Dex 12, Con —, Int —, Sag 12, Cha 1\nParticularités : traits de créature artificielle, immunité contre la magie\nPossessions : Au cœur d\'un golem de diamant se trouve un diamant parfait d\'une valeur de 10 000 po. Il ne peut être récupéré que si le golem est détruit, auquel cas celui-ci se désagrège en poussière, laissant derrière lui la pierre précieuse\nDissipation ciblée (Sur). Toute créature frappée en combat au corps à corps par le poing d\'un golem de diamant subit un effet magique de dissipation de la magie ciblée qui agit comme s\'il avait été lancé par au niveau 16 de lanceur de sorts\nPouvoirs magiques. Un golem de diamant peut lancer le sort rayon de soleil 1d3 fois par jour. Un golem de diamant peut également lancer, à volonté, le sort coup au but. Niveau 15 de lanceur de sorts\nImmunité contre la magie (Ext). Un golem de diamant est immunisé contre tous les sorts et pouvoirs magiques affectés par la résistance à la magie. De plus, certains sorts et effets spécifiques affectent différemment la créature. Les sorts emprisonnement et fracassement affectent normalement un golem de diamant. Le sort réparation permet à un golem de diamant de récupérer tous les points de dégâts qu\'il a pu subir\nVulnérabilité au ki (Ext). Les golems de diamant peuvent être frappés et endommagés par tout personnage possédant le pouvoir de ki, que les moines obtiennent au niveau 4. Si son attaque porte, l\'assaillant inflige au golem de diamant 1d6 points de dégâts supplémentaire\nMonstres de Faerun\nFigurine : creatures artificielles DD minis à repeindre', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2264);

-- 2265 — Momies
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2265, 'Momies', 1, NULL, 'PV : 55 chacune (8 DV)\nRD : 5/—\nLM Mort-vivant de taille moyenne\nInitiative : +0\nSens : vision dans le noir 18 m ; Perception auditive +8, Détection +8\nAura : désespoir\nLangues : thoross\nClasse d\'armure : 20, toucher 10, pris au dépourvu 20\nImmunités : immunités des morts-vivants\nJets de sauvegarde : Vig +4, Réf +2, Vol +8\nFaiblesse : vulnérabilité au feu\nVitesse de déplacement : 3m (4 cases)\nMêlée : coup +11 (1d6+10 plus putréfaction de momie)\nAttaque de base/lutte : +4/+11\nOptions d\'attaque : putréfaction de momie\nCaractéristiques : Force 24, Dex 10, Con —, Int 6, Sag 14, Cha 15\nParticularités : traits de mort-vivant\nDons : #Vigilance#, #Vigueur surhumaine#, #Robustesse#\nCompétences : Discrétion +7, Perception auditive +8, Déplacement silencieux +7, Détection +8\nDésespoir (Sur). Quiconque aperçoit une momie doit réussir un jet de Volonté (DD 16) pour ne pas être paralysé de désespoir pendant 1d4 rounds. Que le jet de sauvegarde soit réussi ou non, la créature ne peut plus être affectée par la vision de cette momie pendant 24 heures. Le DD de sauvegarde est lié au Charisme\nPutréfaction de momie (Sur). Maladie surnaturelle ; coup, jet de Vigueur (DD 16), temps d’incubation, 1 minute ; effet : affaiblissements temporaires de 1d6 points de Con et 1d6 points de Cha. Le DD de sauvegarde est lié au Charisme.\nContrairement aux maladies normales, celle-ci se poursuit jusqu’à ce que le malade meure (en tombant à 0 de Constitution) ou soit soigné comme cela est décrit ci-dessous.\nLa putréfaction de momie est une puissante malédiction, pas une maladie naturelle. Tout personnage tentant de lancer une invocation (guérison) sur une créature frappée par ce mal doit réussir un test de niveau de lanceur de sorts (DD 20) sans quoi le sort n’a aucun effet.\nPour soigner la putréfaction, il faut briser la malédiction à l’aide d’une annulation d’enchantement ou d’une guérison des maladies (test de niveau de lanceur de sorts, DD 20), après quoi il n’est plus nécessaire d’effectuer de test de niveau de lanceur de sorts pour lancer des sorts de guérison sur la victime. En outre, ce mal peut être soigné comme n’importe quelle maladie normale.\nSi le malade succombe, son corps pourrit très rapidement et se transforme en sable et en poussière emportés au premier coup de vent', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2265);

-- 2266 — Tyramort
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2266, 'Tyramort', 1, NULL, 'FR\nPV 71 (11 DV)\nRD : 5/coups tranchants\nNM Mort-vivant de grande taille\nInitiative : +0\nSens : vision mystique, vision dans le noir 18 m ; Perception auditive +2, Détection +6\nClasse d\'armure : 20, toucher 9, pris au dépourvu 20\nImmunités : des morts-vivants\nRésistances : +2 résistance aux tours\nJets de sauvegarde : Vig +3, Réf +3, Vol +9\nVitesse de déplacement : vol 4,5m (3 cases) (moyenne)\nMêlée : morsure -1 (2d4)\nDistance : 5 rayons oculaires +4 au toucher à distance chacun\nEspace occupé/allonge : 3m/1,5m\nAttaque de base/lutte : +5/+9\nCaractéristiques : Force 10, Dex 10, Con —, Int —, Sag 15, Cha 17\nParticularités : cône antimagie, vol, limité à une seule action, traits de mort-vivant\nDons : —\nCompétences : Perception auditive +2, Fouille +4, Détection +6\nLimité à une seule action (Ext). Les tyramorts ont de mauvais réflexes et ne peuvent exécuter qu’une action de mouvement ou d’attaque par round. Il a donc le choix entre attaquer et se déplacer, et ne peut faire les deux que s’il charge\nCône d\'antimagie (Sur). A moins qu\'il n\'ait plus l\'usage de son œil central (voir plus bas), un tyramort projette en permanence un cône d\'antimagie de 45 m de long droit devant lui. Ce cône a le même effet que le sort zone d\'antimagie lancé par un ensorceleur de niveau 13. Tous les effets magiques et surnaturels sont réprimés à l\'intérieur, y compris les rayons du tyramort. À chaque round, le tyrannœil décide dans quelle direction il se tourne et si le cône est actif ou non (il le désactive en fermant son œil central). Notez qu\'il ne peut mordre que les créatures qui se trouvent devant lui\nRayons occulaires (Sur). De son vivant, le tyramort avait dix petits yeux sur des appendices reliés à son corps, chacun doté d\'un pouvoir surnaturel et un œil central. En général, un tyramort a perdu l\'usage de 1d4+1 de ses yeux, choisis au hasard.\nChacun des yeux survivants peut tirer un rayon magique à chaque round, même quand le tyramort se déplace à pleine vitesse pu attaque avec sa gueule. Il peut tirer tous ses rayons vers le haut, mais ses appendices ne sont pas assez longs pour qu\'il puisse les utiliser tous dans les autres directions. Au cours d\'un round, il ne peut se servir que de trois yeux dans une des directions suivantes ; devant, derrière, à gauche, à droite ou sous lui. Les autres yeux ne peuvent être utilisés que dans les directions restantes ou pas du tout. Un tyramort peut tourner ou incliner son corps à chaque round pour changer les rayons utdisés.\nChaque rayon produit l\'effet d\'un sort lancé par un ensorceleur de niveau 13. Tous ont une portée de 45 m et appliquent les règles des rayons et un DD de sauvegarde de 18\n- $Blessure modérée$. Comme le sort du même nom, 2d8+10 points de dégâts (jet de Volonté, demi-dégâts).\n- $Charme-monstre$. La cible doit réussir un jet de Volonté pour ne pas être affectée par le sort du même nom.\n- $Charme-personne$. La cible doit réussir un jet de Volonté pour ne pas être affectée par le sort du même nom.\n- $Désintégration$. La cible doit réussir un jet de Vigueur pour ne pas être affectée par le sort du même nom.\n- $Doigt de mort$. La cible doit réussir un jet de Vigueur pour ne pas être affectée par le sort du même nom. Même en cas de réussite, elle subit 3d6+13 points de dégâts.\n- $Lenteur$. Fonctionne comme le sort du même nom, mais en n\'affectant qu\'une créature à la fois. La cible doit réussir un jet de Volonté pour résister.\n- $Pétrification$. La cible doit réussir un jet de Vigueur pour ne pas être affectée par le sort du même nom.\n- $Sommeil$. Fonctionne comme le sort du même nom, mais en n\'affectant qu\'une seule créature sans limite de DV. La cible doit réussir un jet de Volonté pour résister.\n- $Tèlékinésie$. Le tyramort peut déplacer créatures et objets pesant jusqu\'à 160 kg comme s\'il utilisait le sort du même nom. lies créatures peuvent résister avec un jet de Volonté.\n- $Terreur$. Fonctionne comme le sort du même nom, mais en n\'affectant qu\'une créature à la fois. La cible doit réussir un jet de Volonté pour ne pas être affectée par le sort du même nom.\nVision à 360° (Ext). Les nombreux yeux du tyramort lui confèrent un bonus racial de +4 aux jets de Détection et de Fouille, tout en empêchant ses ennemis de le prendre en tenaille\nVol (Ext). Le corps des tyramorts flotte naturellement, ce qui leur permet de se déplacer dans les airs à une vitesse de 4,50 mètres. Ils bénéficient également en permanence de l’effet du sort feuille morte à une portée personnelle', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2266);

-- 2267 — Varrangoin, mineur
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2267, 'Varrangoin, mineur', 23, NULL, 'FF\nPV : 32 chacun (5 DV)\nRD : 10/argent\nCM Bête magique moyenne (extraplanaire)\nInitiative : +3\nSens : vision dans le noir 18 m, vision nocturne ; Perception auditive +2, Détection +2\nLangues : Abyssal, commun, varrangoin\nClasse d\'armure : 19, toucher 13, pris au dépourvu 16\nImmunités : électricité\nRésistances : acide 10, froid 10, feu 10 ; RM 12\nJets de sauvegarde : Vig +5, Réf +7, Vol +1\nFaiblesse : sensibilité à la lumière\nVitesse de déplacement : 6m (4 cases), vol 12m (moyenne)\nMêlée : morsure +7 (1d6+2) et 2 griffes +5 chacune (1d4+1) et dard caudal +5 (1d4+1 plus empoisonnement)\nAttaque de base/lutte : +5/+7\nOptions d\'attaque : Attaque en vol, souffle, empoisonnement (DD 13, 1d6 Dex/1d6 Dex), agonie\nCaractéristiques : Force 14, Dex 16, Con 13, Int 11, Sag 11, Cha 8\nParticularités : traits du varrangoin\nDons : #Vigilance#, #Attaque en vol#, #Attaques multiples#\nCompétences : Discrétion +10, Perception auditive +2, Déplacement silencieux +10, Détection +2\nSouffle (Ext). Une fois toutes les 1d4 rounds, ligne de 15 m, dégâts 3d6 Électricité, DD Réflexes 13 pour moitié\nAgonie (Ext). Lorsqu\'il est réduit à -10 points de vie, un varrangoin mineur explose dans un rayon de 6 m qui inflige 3d6 points de dégâts d\'Électricité (DD Réflexes 13 pour moitié)\nSensibilité à la lumière (Ex). L\'exposition à une lumière vive (comme la lumière du soleil ou un sort de lumière du jour) rend les varrangoins aveugles pendant 1 round. Chaque round suivant, ils subissent une pénalité de -1 aux jets d\'attaque, aux jets de sauvegarde et aux tests de compétence tant qu\'ils sont exposés à la lumière vive', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2267);

-- 2268 — géants de phaerlin (en rage)
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2268, 'géants de phaerlin (en rage)', 27, NULL, 'Mon\nPV : 146 chacun (13 DV)\nGéant de phaerlin barbare mâle ou femelle 5\nNM Géant de Très Grande taille (terre)\nInitiative : +3\nSens : vision nocturne, odorat ; Perception auditive +6, Détection +7\nAura : Présence effrayante 9 m\nLangues : Commun, géant\nClasse d\'armure : 19, toucher 6, pris au dépourvu 19 ; Esquive instinctive supérieure\nRM : 19\nJets de sauvegarde : Vig +16, Réf +2, Vol +4\nVitesse de déplacement : 6m (4 cases) en armure de discrétion, vitesse de base 9m\nMêlée : 2 griffes +18 chacune (2d4+8) et morsure +16 (1d8+4)\nEspace : 4,5 m ; Portée 4,5 m\nAttaque de base/lutte : +11/+23\nOptions d\'attaque : Enchaînement, Attaque en puissance, rage 2/jour (9 rounds)\nCaractéristiques : Force 26, Dex 9, Con 22, Int 8, Sag 8, Cha 9\nParticularités : sens des pièges +1\nDons : #Vigilance#, #Enchaînement#, #Science de la bousculade#, #Science de l\'initiative#, #Attaques multiples#, #Attaque en puissance#\nCompétences : Escalade +13, Saut +9, Perception auditive +6, Détection +7, Survie +2\nPossessions : armure de peau\nPrésence effrayante (Ext). Un géant de phaerlin commence le combat par un rugissement terrifiant qui sème la terreur dans le cœur de ses ennemis. Les créatures situées à moins de 9 mètres sont soumises à cet effet si elles ont moins de 13 DV. Une créature potentiellement affectée qui réussit un jet de sauvegarde DD 15 reste immunisée contre la présence effrayante du géant pendant 24 heures. En cas d\'échec, la créature est secouée pendant 4d6 rounds', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2268);

-- 2269 — Tyrannoœil
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2269, 'Tyrannoœil', 21, NULL, 'PV : 93 (11 DV)\nLM Aberration de Grande Taille\nInitiative : +6\nSens : vision mystique, vision dans le noir 18 m ; Perception auditive +18, Détection +22\nLangues : commun, géant, commun des profondeurs\nClasse d\'armure : 26, toucher 11, pris au dépourvu 24\nJets de sauvegarde : Vig +9, Réf +5, Vol +11\nVitesse de déplacement : 1,5 m (1 carré), vol 6m (bon)\nMêlée : morsure +2 (2d4)\nDistance : 10 rayons oculaires +9 au toucher à distance chacun\nEspace : 3 m ; Portée 1,5 m\nAttaque de base/lutte : +8/+12\nOptions d\'attaque : Attaque en vol\nCaractéristiques : Force 10, Dex 14, Con 18, Int 17, Sag 15, Cha 15\nParticularités : cône antimagie, vol\nDons : #Vigilance#, #Attaque en vol#, #Vigueur surhumaine#, #Science de l\'initiative#, #Volonté de fer#\nCompétences : Discrétion +12, Connaissances (mystères) +17, Perception auditive +18, Fouille +21, Détection +22, Survie +2 (+4 après avoir suivi des traces)\nRayons oculaires (Sur). Chacun des dix petits yeux d\'un gauth produit un effet semblable à un sort (niveau 14 de lanceur de sorts). Chaque oeil a une portée de 45 mètres et le DD de sauvegarde est de 17. Les DD de sauvegarde sont liés au Charisme. Les effets des dix rayons sont décrits ci-dessous\n- $Blessure modérée$. Comme le sort du même nom, 2d8+10 points de dégâts (jet de Volonté, demi-dégâts).\n- $Charme-monstre$. La cible doit réussir un jet de Volonté pour ne pas être affectée par le sort du même nom.\n- $Charme-personne$. La cible doit réussir un jet de Volonté pour ne pas être affectée par le sort du même nom.\n- $Désintégration$. La cible doit réussir un jet de Vigueur pour ne pas être affectée par le sort du même nom.\n- $Doigt de mort$. La cible doit réussir un jet de Vigueur pour ne pas être affectée par le sort du même nom. Même en cas de réussite, elle subit 3d6+13 points de dégâts.\n- $Lenteur$. Fonctionne comme le sort du même nom, mais en n\'affectant qu\'une créature à la fois. La cible doit réussir un jet de Volonté pour résister.\n- $Pétrification$. La cible doit réussir un jet de Vigueur pour ne pas être affectée par le sort du même nom.\n- $Sommeil$. Fonctionne comme le sort du même nom, mais en n\'affectant qu\'une seule créature sans limite de DV. La cible doit réussir un jet de Volonté pour résister.\n- $Tèlékinésie$. Le tyramort peut déplacer créatures et objets pesant jusqu\'à 160 kg comme s\'il utilisait le sort du même nom. lies créatures peuvent résister avec un jet de Volonté.\n- $Terreur$. Fonctionne comme le sort du même nom, mais en n\'affectant qu\'une créature à la fois. La cible doit réussir un jet de Volonté pour ne pas être affectée par le sort du même nom.\nCône d\'antimagie (Sur). L\'œil central de ce monstre projette en permanence un cône d\'antimagie de 45 mètres de long. Ce cône a le même effet que le sort $zone d\'antïmagie$ (niveau 13 de lanceur de sorts). Tous les effets magiques et surnaturels sont réprimés à l\'intérieur, y compris les rayons du tyrannœil Chaque round, le tyrannœil décide dans quelle direction il se tourne et si son cône est actif ou non (il le désactive en fermant son œil central)', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2269);

-- 2270 — Serpent ailé
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2270, 'Serpent ailé', 23, NULL, 'Rac\nhp 5 chacun (1 DV)\nN Petite bête magique\nInitiative : +3\nSens : odorat ; Perception auditive +8, Détection +8\nClasse d\'armure : 17, toucher 14, pris au dépourvu 14\nJets de sauvegarde : Vig +2, Réf +5, Vol +1\nVitesse de déplacement : 6 m (4 cases), escalade 6 m, vol 6 m (moyenne)\nMêlée : morsure +5 (1d3–2 plus 1 acide)\nDistance : crachat acide +4 (1 acide)\nAttaque de base : +1 ; Lutte –3\nOptions d\'attaque : Crachat acide, saisie améliorée, constriction 1d3–2\nCaractéristiques : Force 6, Dex 17, Con 11, Int 1, Sag 12, Cha 2\nDons : Vigilance, Finesse avec les armes\nCompétences : Équilibre +11, Escalade +12, Discrétion +12, Perception auditive +8, Détection +8\nPossessions : étui à parchemin (pour transporter des messages)\nCrachat acide (Ext). Une fois par round, un serpent ailé peut cracher de l\'acide comme une attaque de contact à distance jusqu\'à 3 m. L\'acide inflige 1 point de dégâts d\'acide. Un serpent ailé qui mord un adversaire lui inflige automatiquement 1 point de dégâts d\'acide\nSaisie améliorée (Ext). Si un serpent ailé touche avec son attaque de morsure, il peut alors tenter d\'engager une lutte en tant qu\'action gratuite sans provoquer d\'attaques d\'opportunité. S\'il remporte le test de lutte, il établit une prise et peut étrangler sa victime\nConstriction (Ext). 1d3-2 points de dégâts avec un test de lutte réussi contre des créatures de taille Très petite ou inférieure', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2270);

-- 2271 — Sang ardent flétri
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2271, 'Sang ardent flétri', 25, NULL, 'MM4\nPV : 162 (12 DV) ; guérison rapide 5\nNM extérieur de Très Grande taille (vase augmenté, de feu)\nInitiative : +1\nSens : aveugle, vision aveugle 18m ; Perception auditive +0\nAura : Aura d\'énergie négative (3m)\nClasse d\'armure : 17, contact 9, pris au dépourvu 16\nImmunités : contre le feu, les attaques de regard, les illusions, les effets visuels\nRésistances : à l\'acide 15, à l\'électricité 15\nRM : 22 (27 contre l\'énergie positive)\nJets de sauvegarde : Vig +12, Réf +5, Vol +4\nFaiblesse : vulnérabilité au froid\nVitesse de déplacement : 9m (6 cases)\nMêlée : coup +15 (2d6+10/19–20 plus 2d6 de feu)\nEspace : 4,5 m ; Portée 3 m\nAttaque de base/lutte : +9/+24\nOptions d\'attaque : Sang brûlant, Frappe magique, Coup au but 1/jour\nActions spéciales : Forme alternative, Explosion de flammes, Aura d\'énergie négative\nCaractéristiques : Force 24, Dex 13, Con 26, Int 3, Sag 11, Cha 6\nParticularités : extension d\'effet des sorts de feu\nDons : #Attaque spéciale renforcée# (déflagration), Armure naturelle supérieure, #Arme naturelle supérieure# (coup), #Arme de prédilection# (coup)\nCompétences : Évasion +16, Discrétion +8, Perception auditive +0, Déplacement silencieux +16, Psychologie +15\nAura d\'énergie négative (Sur). Toute créature vivante à moins de 3 m d\'un sang ardent flétri perd 1 point de vie par round. Les personnages immunisés contre les effets d\'énergie négative, ainsi que les autres créatures entropiques, ne sont pas affectés par cette aura. S\'il est conscient, le sang ardent flétri peut réprimer cette aura en tant qu\'action standard, mais il subit 1 point de dégâts de Force pour chaque minute complète pendant laquelle l\'aura est inactive\nSang brûlant (Ext). Le corps d\'un sang ardent flétri produit une chaleur intense. Toute créature qui frappe ou touche un sang ardent flétri avec son corps ou une arme, ou qui le lutte, subit automatiquement 2d6 points de dégâts de feu. Une créature ne subit les dégâts de cette caractéristique qu\'une seule fois par round\nCoup au but (Sur). Comme le sort $coup au but$\nForme alternative (Su). En tant qu\'action standard, un sang ardent flétri se rend encore plus hideux, imposant une pénalité de -1 aux jets d\'attaque contre lui\nExplosion de flammes (Su). Un sang ardent flétri peut activer une explosion de flammes en tant qu\'action standard une fois par round. Toute créature à moins de 3 m subit 6d6 points de dégâts de feu (DD de réflexes de 26 pour moitié)\nRayon d\'énergie négative (Sur). Une fois tous les 1d4 rounds ; portée 18 mètres ; +10 au toucher à distance ; 1d4-2 points de dégâts d\'énergie négative. Cette attaque inflige des dégâts aux créatures vivantes et permet la guérison suprême des morts-vivants\nExtension d\'effet des sorts de feu (Su). Tout sort ou capacité magique ayant le descripteur « feu » et lancé à moins de 18m d\'un sang ardent flétrissant est renforcé comme par le don #Extension d\'effet#. Pour déclencher cet effet, le lanceur du sort et le point d\'origine du sort doivent se trouver dans la zone affectée', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2271);

-- 2272 — Culcathrax
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2272, 'Culcathrax', 21, NULL, 'hp 84 (13 DV)\nRD : 10/magie\nPhaerimm adulte\nNM aberration de grande taille\nInitiative : +0\nSens : vision complète (vision magique, détection de l\'invisibilité) 36m, vision nocturne ; Perception auditive +11, Détection +12\nLangues : télépathie 30m\nClasse d\'armure : 33, toucher 9, pris au dépourvu 33\nImmunités : contre la métamorphose, la pétrification, la mort et les effets d\'énergie négative (scarabée)\nRM : 23\nJets de sauvegarde : Vig +6, Réf +6, Vol +13\nVitesse de déplacement : vol 9m (6 cases) (bon)\nMêlée : 4 griffes +12 chacune (1d6+4) et morsure +7 (2d6+2) et dard +7 (1d8+2 plus empoisonnement et implant)\nEspace occupé/allonge : 3m/3m (1,5 m avec morsure)\nAttaque de base/lutte : +9/+17\nOptions d\'attaque : Science du Contresort, empoisonnement (DD 18, paralysie 2d4 rounds/paralysie 1d3 heures)\nÉquipement de combat : baguette de projectiles magiques (5e) (48 charges)\nSorts connus de l\'ensorceleur (NLS 13) :\n6e (4/jour) — $brume acide$, $éclair multiple$ (DD 21)\n5e (7/jour) — $main interposée de Bigby$, $Renvoi$ (DD 20), $Téléportation$\n4e (7/jour) — $énergie négative$ (+8 aux attaques à distance), $Bouclier de feu$, $Globe d\'invulnérabilité partielle$, $Peau de pierre$\n3e (7/jour) — $dissipation de la magie$, $Boule de feu$ (DD 18), $Armure de mage$ supérieure† (voir page 143), $Suggestion$ (DD 18)\n2e (7/jour) — $endurance de l\'ours$, $Sphère de feu$ (DD 17), $Invisibilité$, résistance aux énergies destructives, $Rayon ardent$ (3 rayons, +8 au toucher à distance)\n1er (8/jour) — mains brûlantes (DD 16), $Identification$, $Projectile magique$, $Rapetissement$ (DD 16), $Serviteur invisible$\n0 (6/jour) — $aspersion acide$ (+9 au toucher à distance), $signature magique$, hébétement (DD 15), illumination (DD 15), son imaginaire, lumière, $manipulation à distance$, ouverture/fermeture, lecture de la magie\n† déjà lancé\nUn phaerimm lance ses sorts d\'ensorceleur comme s\'il s\'agissait de capacités semblables à des sorts, ne nécessitant ni composants verbaux, somatiques ou matériels\nCapacités semblables à des sorts (NLS 13) :\n- À volonté — $détection de la magie$\nCaractéristiques : Force 18, Dex 11, Con 14, Int 18, Sag 20, Cha 21\nDons : #Préparation de potions#, Création d\'anneaux magiques, Science du Contresort, #Réflexes surhumains#, #Écriture de parchemins#\nCompétences : Estimation +4 (+6 alchimie, forge, fabrication de pièges), Bluff +14, Concentration +15, Artisanat (alchimie +12), Artisanat (forge) +12, Artisanat (fabrication de pièges) +12, Diplomatie +7, Déguisement +5 (+7 au jeu d\'acteur), Intimidation +7, Connaissances (mystères) +12, Connaissances (exploration souterraine) +12, Connaissances (plans) +12, Perception auditive +11, Art de la magie+19, Détection +12, Survie +5 (+7 sous terre et dans les autres plans)\nPossessions : équipement de combat plus anneau supérieur de résistance aux énergies (feu), scarabée de protection, clé des cages à serpents\nVision complète (Ext). Un phaerimm adulte peut voir les auras magiques jusqu\'à une portée de 36m, comme s\'il était constamment sous l\'effet d\'un sort de $vision magique$', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2272);

