-- 2274 — Percetombe
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2274, 'Percetombe', 3, NULL, 'Mon\nPV : 118 chacun (16 DV)\nRD : 10/adamantite\nN Créature artificielle de grande taille\nInitiative +3\nSens : aveugle, vision aveugle 36m, perception des vibrations 18m ; Perception auditive +16, Détection +16\nLangues : commun, netherisse, commun des profondeurs, télépathie 30m\nClasse d\'armure : 23, contact 12, pris au dépourvu 21\nImmunités : contre le feu, les attaques de regard, les illusions, les effets visuels, les dégâts aux capacités, le drain de capacités, les coups critiques, les effets mortels, la mort par dégâts massifs, les maladies, l\'absorption d\'énergie, l\'épuisement, la fatigue, la magie, les sorts et capacités affectant l\'esprit (charme, contrainte, fantasmes, schémas et effets sur le moral), effets de nécromancie, dégâts non létaux, paralysie, empoisonnement, effets de sommeil, étourdissement, tout effet nécessitant un jet de Vigueur sauf s\'il fonctionne également sur les objets\nRésistances : au froid 10, à l\'électricité 10\nJets de sauvegarde : Vig +7, Réf +8, Vol +7\nVitesse de déplacement : 12m (8 cases), creuser 3m\nMêlée : masse en adamantite +1 de lancer de retour +20/+15/+10 (2d6+11/19–20/×3) et morsure +13 (1d10+3) ou\nMêlée : 2 coups +18 chacun (2d4+7) et morsure +13 (1d10+3)\nDistance : masque de jet en adamantite +1 +16 (2d6+11/19–20/×3)\nEspace : 3 m ; Portée 3 m\nAttaque de base/lutte : +12/+23\nOptions d\'attaque : Enchaînement, Attaque en puissance\nCapacités magiques : (NLS 18) :\nÀ volonté — $détection de la magie$ 7/jour — façonnage de la pierre 3/jour — $pierres acérées$ (DD 17)\nCaractéristiques : Force 24, Dex 16, Con —, Int 14, Sag 11, Cha 16\nParticularités : traits de créature artificielle, masse, réparation\nDons : #Enchaînement#, #Vigueur surhumaine#, #Science du critique# (masse), #Volonté de fer#, #Attaque en puissance#, #Arme de prédilection# (masse)\nCompétences : Estimation +14, Perception auditive +16, Fouille +18, Détection +16, Survie +16 (+18 après pistage)\nPossessions : Masse de jet en adamantite +1 qui revient à son lanceur\nMaul (Sur) Chaque percetombe est créé avec une maul adamantine +1 adaptée à sa taille. Entre les mains d\'un percetombe, cette arme gagne les capacités spéciales lancer et retour\nRéparation (Sur) Un effet de façonnage de la pierre répare des dégâts égaux à 1d8 + niveau du lanceur de sorts en points de vie s\'il est utilisé sur un percetombe. Une créature peut utiliser sa propre capacité magique pour se réparer', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2274);

-- 2275 — Phaerimm juvénile
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2275, 'Phaerimm juvénile', 21, NULL, 'PV : 18 (4 DV)\nNM Aberration de Petite taille\nInitiative : +2\nSens : vision complète (détection de l\'invisibilité) 36 m, vision nocturne ; Perception auditive +6, Détection +7\nLangues : télépathie 30 m\nClasse d\'armure : 19, toucher 13, pris au dépourvu 17 ; Esquive\nImmunités : métamorphose, pétrification\nRM : 14\nJets de sauvegarde : Vig +1, Réf +6, Vol +6\nVitesse de déplacement : vol 9 m (6 cases) (bon)\nMêlée : 2 griffes +3 chacune (1d3-1) et morsure -2 (1d6-1)\nEspace : 1,5m ; Portée 1,5ms (0 pied avec morsure)\nAttaque de base : +3 ; Lutte -2\nOptions d\'attaque : Tir à bout portant\nSorts d\'ensorceleur connus : (NLS 4e) :\n2ème (3/jour) —$Flèche acide de Melf$ (+6 au toucher à distance)\n1er (6/jour) — $charme-personne$ (DD 13), $Projectile magique$, $rayon affaiblissant$ (+6 au toucher à distance)\n0 (6/jour) — détection de la magie, destruction des morts-vivants (+6 au toucher à distance), $Manipulation à distance$, $Lecture de la magie$, $Résistance$, $Fatigue$ (+3 au toucher en mêlée)\nUn phaerimm lance ses sorts d\'ensorceleur comme s\'il s\'agissait de capacités semblables à des sorts, ne nécessitant ni composants verbaux, somatiques ou matériels\nCaractéristiques : Force 8, Dex 15, Con 10, Int 13, Sag 14, Cha 15\nParticularités : détection de la magie\nDons : #Esquive#, #Tir à bout portant#\nCompétences : Intimidation +7, Perception auditive +6, Art de la magie+8, Détection +7', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2275);

-- 2276 — Gargouilles Kir-Lanan
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2276, 'Gargouilles Kir-Lanan', 29, NULL, 'FR\nPV : 91 chacune (14 DV)\nGargouille kir-lanan mâle tourmenteur 10\nCM Humanoïde monstrueux de taille moyenne\nInitiative : +6\nSens : vision dans le noir 18m ; Perception auditive +1, Détection +1\nLangues : Commun\nClasse d\'armure : 20, toucher 12, pris au dépourvu 18\nRésistances : au métal\nJets de sauvegarde : Vig +5, Réf +9, Vol +10 ; +1 contre les sorts et les effets magiques\nFaiblesse : Blessé par l\'énergie positive\nVitesse de déplacement : 9m (6 cases), vol 27m (bon)\nMêlée : 2 griffes +21 chacune (1d6+6)\nAttaque de base/lutte : +14/+8\nOptions d\'attaque : Magie de guerre, Attaque en vol, toucher d\'énergie négative 3/jour (DD 13), contrôle mineur des morts-vivants 3/jour (+1, 2d6+5, 4e), tourment supérieur\nÉquipement de combat : potion d\'endurance de l\'ours, potion de protection contre les énergies destructives (feu), 2 potions de splendeur de l\'aigle, collier de boules de feu de type II (1×6, 2×4, 2×2), baguette infligeant des blessures légères (40 charges)\nSorts connus du tourmenteur (NLS 5 ; 1d20+7 pour surmonter la RM) :\n2ème (1/jour) - $force de taureau$, $simulacre de vie$, $image miroir$\n1er (2/jour) - $bouclier entropique$, $Repli expéditif$, $Identification$, $Protection contre le bien$\nCapacités magiques : (NLS 4) :\n3/jour — $rayon affaiblissant$ (+6 à l\'attaque à distance)\nCaractéristiques : Force 18, Dex 14, Con 13, Int 10, Sag 8, Cha 12\nParticularités : résistance profane, ardeur, appel de familier\nDons : Lancement en combat, #Attaque en vol#, #Science de l\'initiative#, Science de l\'armure naturelle, #Arme naturelle supérieure# (griffe), #Efficacité des sorts accrue#, #Arme de prédilection# (griffe)\nCompétences : Concentration +9, Évasion +5, Discrétion +8, Connaissances (mystères) +6, Perception auditive +1, Déplacement silencieux +4, Art de la magie+8, Détection +1, Utilisation d\'objets magiques +4 (+6 parchemins)\nPossessions : équipement de combat plus &bracelets d\'armure& +4, &amulette des poings invincibles& +2\nToucher d\'énergie négative (Sur). Trois fois par jour, le kir-lanan peut concentrer son énergie négative pour un effet similaire au sort $contact glacial$. S\'il réussit une attaque de contact au corps à corps, il inflige 2d6 points de dégâts ainsi qu\'un affaiblissement temporaire de 1 point de. Force (qui peut être évité par un jet de Vigueur DD 12 + modificateur de Cha du kir-lanan). Le kir-lanan regagne autant de points de vie qu\'il a causé de points de dégâts par cette attaque, bien qu\'il ne puisse dépasser son maximum de points de vie par ce moyen. Uiv kir-lanan peut attaquer avec ses griffes pour produire cet effet, mais il doit alor\'s.réussir une attaque de corps à corps normale. Les dégâts occasionnés paî les griffes ne lui font pas regagner de points de vie\nRayon affaiblissant (Mag). Trois fois par jour, le kir-lanan peut utiliser rayon affaiblissant comme un ensorceleur, de niveau 4\nIntimidation des morts-vivants (Sur). Un kir-lanan peut intimider ou contrôler les morts-vivants trois fois par jour comme un prêtre mauvais ayant autant de niveaux qu\'il a de DV\nBlessé par l\'énergie positive. À cause de l\'énergie négative qui parcourt leur organisme, les kir-lanans sont vulnérables aux attaques utilisant l\'énergie positive, tout comme les morts-vivants. Les sorts de soins, l\'eau bénite et les armes bénies les blessent. Ils ne peuvent être renvoyés, mais un tel déploiement d\'énergie positive les indispose et ils essaient.d\'éviter les prêtres qui pratiquent cet exercice. À l\'inverse, ils sont guéris par les sorts de blessure et autres manifestations d\'énergie négative\nTourment supérieur (Sur). Trois fois par jour, en tant qu\'action gratuite, un tourmenteur peut lancer une malédiction sur un ennemi. La cible doit être visible et se trouver à moins de 18m. La cible subit un malus de -4 aux jets d\'attaque, aux jets de sauvegarde, aux tests de caractéristiques, aux tests de compétences et aux jets de dégâts des armes pendant 1 heure. Un jet de sauvegarde de Volonté DD 16 réussi annule cet effet\nCourage (Ext) Si un tourmenteur réussit un jet de sauvegarde de Volonté ou de Vigueur contre une attaque qui aurait normalement un effet moindre, il annule cet effet.\nRésistance profane (Sur). Le tourmenteur obtient un bonus sur les jets de sauvegarde contre les sorts et les pouvoirs magiques égal à son bonus de Charisme (minimum de +1)\nArdeur (Ext). Le tourmenteur peut résister à la magie avec une détermination et un tonus remarquables. Lorsqu\'il réussit un jet de Vigueur ou de Volonté contre une attaque autorisant un jet de sauvegarde pour réduire ses effets (comme n\'importe quel sort dont la ligne Sauvegarde indique « Vigueur, partiel » ou « Volonté, partiel »), il ne subit aucun effet (plutôt que des effets réduits). Un tourmenteur inconscient ou endormi ne bénéficie pas des effets de ce pouvoir', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2276);

-- 2277 — Drullister
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2277, 'Drullister', 21, NULL, 'Mon\nPV : 97 (16 DV)\nRD : 10/magie\nPhaerimm adulte, adepte des ombres 4\nNM aberration de Grande taille\nInitiative : +0\nSens : vision complète (vision magique, détection de l\'invisibilité) 36m, vision nocturne ; Perception auditive +11, Détection +11\nLangues : télépathie 30 m\nClasse d\'armure : 27, toucher 9, pris au dépourvu 27\nImmunités : métamorphose, pétrification, sorts de niveau 4 ou inférieur (pierre ioun)\nRM : 23\nJets de sauvegarde : Vig +7, Réf +5, Vol +16 ; bonus profane de +1 contre l\'envoûtement, l\'illusion, la nécromancie et les sorts ayant le descripteur ténèbres\nVitesse de déplacement : 9m (6 cases) (bonne)\nMêlée : 4 griffes +13 chacune (1d6+4) et morsure +11 (2d6+2) et dard +11 (1d8+2 plus empoisonnement et implant)\nEspace : 3m ; Portée 3m (1,5m avec la morsure)\nAttaque de base/lutte : +10/+18\nOptions d\'attaque : Quintessence des sorts, Magie pernicieuse, Incantation rapide, empoisonnement (DD 18, paralysie 2d4 rounds/paralysie 1d3 heures)\nÉquipement de combat : &bâton d\'évocation& (42 charges), sceptre de métamagique mineur d\'Extension de portée, &baguette de soins intensifs& (20 charges)\nSorts d\'ensorceleur connus (NLS 18 ; 1d20+18 pour surmonter la RM) :\n8e (3/jour) — $Bouclier mystique$,$Anneau de foudre$,\n7e (5/jour) — $souhait limité$, $Téléportation suprême$, $Renvoi des sorts$\n6e (6/jour) — $sphère écrasante$ (NLS 15, DD 21), Soufflede sable (NLS 15, DD 21), symbole de persuasion* (DD 22)\n5e (7/jour) — $cône de froid$ (NLS 15, DD 20), $Domination$* (DD 21), $Brume mentale$* (DD 21), gyre réciproque (DD 20)\n4e (7/jour) — $tentacules noirs d\'Evard$, $Globe d\'invulnérabilité partielle$, Morsures magiques (NLS 15, +21 en mêlée), $Peau de pierre$\n3e (7/jour) — $Contrefeu$, $Vortex magique$ (NLS 15), Armure de mage majeure, $Rapidité$ (NLS 15), $Eclair$ (DD 17)\n2e (7/jour) — contrôle mineur des morts-vivants* (DD 18), $Vision dans le noir$ (NLS 15e), $Détection de pensées$ (DD 17), $Flèche acide de Melf$ (+10 au toucher à distance), $Rayon ardent$ (NLS 15e, +10 au toucher à distance)\n1er (8/jour) — $rayon affaiblissant$* (+10 au toucher à distance), $Décharge électrique$ (NLS 15, +14 au toucher en mêlée), onde sonore (NLS 15, DD 16 ; voir page 144), $repli expéditif$ rapide (NLS 15 ; voir page 143), $Coup au but$\n0 (6/jour) — aspersion acide (+10 en touchée à distance), caltrops (voir page 142), décharge électrique (NLS 15, +10 en touchée à distance ; voir page 143), lumière (ne peut pas lancer), manipulation à distance (NLS 15), message (NLS 15), rayon de givre (NLS 15, +10 en attaque de contact à distance), lecture de la magie, fatigue* (+14 en attaque de contact)\n* +1 au DD et au niveau du lanceur pour la résistance à la magie\nUn phaerimm lance ses sorts d\'ensorceleur comme s\'il s\'agissait de capacités semblables à des sorts, ne nécessitant ni composants verbaux, somatiques ou matériels\nCapacités semblables à des sorts (NLS 16) : À volonté — $détection de la magie$\nCaractéristiques : Force 18, Dex 11, Con 14, Int 18, Sag 20, Cha 21\nParticularités : défense contre les ombres +1\nDons : Création d\'objets merveilleux, #Magie insidieuse#B PG, #Quintessence des sorts#, #Attaques multiples#, #Magie pernicieuse#B PG, #Incantation rapide#, Toile d\'ombre MagiePG, #Efficacité des sorts accrue#, #Magie tenace#B PG\nCompétences : Estimation +4 (+6 alchimie, fabrication de pièges), Bluff +14, Concentration +21, Artisanat (alchimie) +13, Artisanat (fabrication de pièges) +10, Diplomatie +13, Déguisement +5 (+7 jeu d\'acteur), Renseignements +13, Intimidation +7, Connaissances (mystères) +23, Connaissances (histoire) +13, Connaissances (folklore local d\'Anauroch) +13, Perception auditive +11, Fouille +10, Art de la magie+25 (+27 parchemins), Détection +11, Survie +9 (+11 au pistage), Utilisation d\'objets magiques +21 (+23 parchemins)\nPossessions : équipement de combat plus &anneau de liberté de mouvement&, &anneau de barrière mentale&, pierre ioun ellipsoïdale lavande pâle. Remarque : toutes les possessions de Drullister sont des objets magiques de la Toile d\'ombre (voir encadré au chapitre 5, page 112)\nImplant (Ext). En tant qu\'action simple, un phaerimm adulte mature peut utiliser son dard pour pondre des oeufs à l\'intérieur d\'une créature paralysée. Les petits éclosent environ 90 jours plus tard, dévorant littéralement leur hôte de l\'intérieur. Un sort de guérison des maladies permet de débarrasser la victime des oeufs, tout comme un jet de Premiers secours réussi avec un DD de 20 effectué par un personnage ayant des rangs dans cette compétence. Si le jet échoue, le soigneur peut réessayer, mais chaque tentative (réussie ou non) inflige 1d4 points de dégâts au patient\nEmpoisonnement (Ext). Blessure, Vigueur DD 18, paralysie 2d4 rounds/paralysie 1d3 heures. Les créatures paralysées effectuent une lévitation, impuissantes, à quelques mètres du sol\nBouclier d\'ombres. Un Adepte de l’Ombre peut créer un disque mobile de Force pourpre/noir avec une action simple. Ce Bouclier d’ombres a l’effet d’un sort de Bouclier, et fournit également trois quarts de dissimulation (30% de chance d’échec) contre les attaques de l’autre coté du bouclier. Comme pour le sort de Bouclier, l’Adepte de l’Ombre peut changer la direction défensive du Bouclier d’ombres en une action libre une fois par round durant son tour. L’Adepte de l’Ombre peut voir et entendre à travers le bouclier, ainsi celui-ci ne fournit ni couverture, ni dissimulation aux adversaires. Le Bouclier d\'ombres dure 1 round par niveau du lanceur et par jour ; il n’a pas besoin d’être utilisé en entier d’un seul coup. Créer ou renvoyer le Bouclier d’Ombres est une action simple.\nAu 8e niveau, le bouclier acquiert également une résistance aux sorts de 12 + le niveau du personnage. Cela est effectif pour les attaques originaires de l’autre coté du bouclier, comme si l’Adepte de l’Ombre était sous l’effet d’un sort de Résistance à la Magie.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2277);

-- 2328 — Cultiste du Pic du Fracassement
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2328, 'Cultiste du Pic du Fracassement', 28, NULL, 'PV : 52 chacun (12 DV)\nHumain roublard 7 / Cultiste du Pic de Fraçassement 5\nLM Humanoïde de taille moyenne\nInitiative : +7\nSens : Perception auditive +2, Détection +10\nLangues : commun, Loross\nClasse d\'armure : 18, toucher 14, pris au dépourvu 18 ; +2 contre les pièges, esquive surnaturelle ; Esquive\nRésistances : évasion\nJets de sauvegarde : Vig +4, Réf +14 (+16 contre les pièges), Vol +6 ; +1 contre les sorts profanes\nVitesse de déplacement : 9m (6 cases)\nMêlée : +2 dague acérée +13/+8 (1d4+3/17?20) ; bonus moral +1 contre les lanceurs de sorts\nAttaque de base/lutte : +8/+9\nOptions d\'attaque : Combat en aveugle, attaque mortelle (DD 17), attaque sournoise +6d6, frappe du mage, zèle\nActions spéciales : Présence inquiétante\nSorts préparés par le cultiste (NLS 5) :\n2e (1/jour) - $Idiotie$ (DD 14, +12 en mélée)\n1er (3/jour) - endurance aux énergies destructives†, $Verrouillage$, $Bouclier$†\n0 (3/jour) - $résistance$† (3)\n† déjà lancé\nCaractéristiques : Force 13, Dex 17, Con 12, Int 14, Sag 10, Cha 8\nParticularités : détection des pièges, sens des pièges +2\nDons : #Vigilance#, #Combat en aveugle#, Esquive, #Science de l\'initiative#, #Réflexes surhumains#, #Attaque en finesse#\nCompétences : Équilibre +13, Bluff +4, Escalade +16, Décryptage +17, Désamorçage/sabotage +15, Déguisement +9, Renseignements +14, Discrétion +18, Intimidation +4, Connaissances (histoire) +17, Perception auditive +2, Déplacement silencieux +18, Crochetage +16, Détection +10\nPossessions : Armure de cuir +2, dague acérée +2, anneau de protection +1\nAttaque mortelle (Ext). Si le cultiste étudie sa cible pendant au moins 3 rounds puis réussit une attaque sournoise infligeant des dégâts, le coup peut paralyser ou tuer la victime (au choix de l’assassin). Tout au long de la phase d’observation, le personnage peut exécuter d’autres actions, à condition que son attention ne dévie pas de la cible et que cette dernière ne le repère pas (ou ne voit pas en lui un ennemi). Si la victime rate son jet de Vigueur (DD 15 + niveau du cultiste + modificateur d’Int du cultiste) contre un coup mortel, elle meurt. Si son agresseur cherchait juste à la paralyser, elle se retrouve sans défense, incapable d’agir pendant 1d6 rounds, + 1 round par niveau de l’assassin. Si la cible réussit son jet de sauvegarde, le coup inflige juste les dégâts normaux pour une attaque sournoise. Une fois que lle cultiste a étudié sa proie, il doit porter son attaque dans les 3 rounds qui suivent, sous peine de devoir recommencer à l’examiner. De même, si la victime réussit son jet de sauvegarde, 3 nouveaux rounds sont nécessaires au cultiste pour tenter une nouvelle attaque mortelle (à condition, bien sûr, que la cible n’ait pas remarqué d’où venait le coup précédent).\nÉvasion (Ext). Si un cultiste réussit son jet de Réflexes contre une attaque dont les dégâts sont normalement réduits de moitié en cas de jet de Réflexes réussi (comme c’est le cas pour une boule de feu ou le souffle enflammé d’un dragon rouge), il l’évite totalement et ne subit pas le moindre dégât. Un cultiste portant une armure intermédiaire ou lourde, ou qui se trouve sans défense (parce qu’il est inconscient ou paralysé, par exemple) perd les avantages de d’esquive totale.\nPrésence inquiétante (Ext). Lorsque des aventuriers ou des explorateurs sont proche de découvrir un grand secret netherisse, le cultiste préfère les effrayer plutôt que de les tuer, si possible. Le cultiste gagne un bonus égal à son niveau sur tous ses jets de Bluff et d\'Intimidation\nFrappe du mage (Sur). Une fois par jour, un cultiste peut tenter de frapper un lanceur de sorts profanes avec un jet d\'attaque normal. Le cultiste inflige 5 points de dégâts supplémentaires en cas d\'attaque réussie\nAttaque sournoise (Ext). Un cultiste inflige des dégâts supplémentaires lorsqu\'il flanque un adversaire ou à tout moment où la cible se voit refuser son bonus de Dex. Ces dégâts ne s\'appliquent aux attaques à distance que si la cible se trouve à moins de 9 mètres\nZèle (Ext). Un cultiste gagne un bonus moral de +1 aux jets d\'attaque contre les lanceurs de sorts profanes et un bonus moral de +1 aux jets de sauvegarde contre les sorts et effets profanes. Le bonus aux jets d\'attaque ne s\'applique pas à une crature qui possède des caractéristiques semblables à des sorts profanes, sauf si elle est également un lanceur de sorts profanes', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2328);

-- 2329 — Vesserabe
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2329, 'Vesserabe', 23, NULL, 'PV : 42 chacun (5 DV)\nN bête magique (extraplanaire) de Grande taille\nInitiative : +3\nSens : cécité, perception aveugle 73 m, odorat ; Perception auditive +10\nClasse d\'armure : 16, toucher 12, pris au dépourvu 13\nImmunités : contre les attaques de regard, les illusions, les effets visuels\nJets de sauvegarde : Vig +7, Réf +7, Vol +1\nVitesse de déplacement : 6m (4 cases), vol 36m (moyenne) ; attaque en vol\nMêlée : morsure +8 (1d8+4) et 2 griffes +6 chacune (1d6+2)\nEspace occupé/allonge : 3m/1,5m\nAttaque de base/lutte : +5/+13\nOptions d\'attaque : bond, griffe\nActions spéciales : souffle toxique\nCaractéristiques : Force 19, Dex 17, Con 17, Int 2, Sag 10, Cha 4\nDon #Attaque en vol#, #Attaques multiples#\nCompétences : Perception auditive +10, Déplacement silencieux +9\nPerception aveugle (Ext). Un vesserabe utilise l\'écholocation pour localiser les créatures situées à moins de 72m. Les adversaires bénéficient toujours d\'une dissimulation totale face à une créature dotée de la perception aveugle. Un sort de silence annule cette capacité et rend le vesserabe aveugle.\nBond (Ext). Lorsqu’un vesserabe bondit sur un ennemi au cours du premier round de combat, il peut effectuer une attaque complète.\nGriffure (Ext). Un vesserabe qui bondit sur un adversaire peut effectuer deux attaques de griffure (+6 en mêlée) avec ses pattes arrière, infligeant chacune 1d6+2 points de dégâts tranchants.\nSouffle toxique (Ext). En tant qu’action simple, un vesserabe peut expirer un nuage noir de fumées toxiques similaire au sort « nuage nauséabond » dans un cône de 6 mètres qui dure 10 rounds. Une fois qu’un vesserabe a utilisé son souffle toxique, il ne peut pas l’utiliser à nouveau avant 1d4 rounds. Les vesserabes sont immunisés contre les effets de leur propre souffle toxique et de celui des autres vesserabes. Le nuage obscurcit toute vision, y compris la vision dans le noir, au-delà de 1,5 mètre. Une créature située à moins de 1,5 mètre bénéficie d’une dissimulation. Les créatures plus éloignées bénéficient d’une dissimulation totale. Les créatures vivantes présentes dans le nuage sont prises de nausées. Cet état dure tant que la créature se trouve dans le nuage et pendant 1d4+1 rounds après qu’elle l’ait quitté. (Lancez un jet de sauvegarde séparément pour chaque personnage pris de nausées.) Toute créature qui réussit son jet de sauvegarde mais reste dans le nuage doit continuer à effectuer un jet de sauvegarde à chaque round pendant le tour du vesserabe. Un vent modéré (11+ mph) disperse le nuage en 4 rounds ; un vent fort (21+ mph) disperse le nuage en 1 round.\nOdorat (Ext). Les vesserabes possèdent la capacité d’odorat. Les créatures qui se recouvrent d’excréments de vesserabe peuvent facilement masquer leur odeur. Cela empêche le vesserabe de détecter ou d’effectuer correctement l’identification de la créature et augmente la difficulté de Survie pour le pistage à 20.\nCompétences Les vesserabes bénéficient d’un bonus racial de +4 aux tests de Perception auditive et de Déplacement silencieux.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2329);

-- 2330 — Mage Shadovar
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2330, 'Mage Shadovar', 28, NULL, 'PV : 40 chacun (10 DV)\nHumain ensorceleur 6 / adepte de l\'ombre 4\nLM Humanoïde de taille moyenne\nInitiative : +2\nSens : vision nocturne ; Perception auditive +0, Détection +0\nLangues : Commun, Loross\nClasse d\'armure : 13, toucher 12, pris au dépourvu 11 ; 20 avec bouclier et armure de mage\nJets de sauvegarde : Vig +5, Réf +6, Vol +10 ; bonus profane +1 contre les enchantements, les illusions, la nécromancie et les sorts ayant le descripteur \"ténèbres\"\nVitesse de déplacement : 9m (6 cases)\nAttaque de base/lutte : +4/+4\nActions spéciales : bouclier d\'ombres\nÉquipement de combat : baguette de rayon d\'épuisement (40 charges)\nSorts d\'ensorceleur préparées (NLS 10) :\n5e (3/jour) - $brume mortelle$ (DD 18)\n4e (5/jour) - $Peau de pierre$, convocation de monstres IV\n3e (7/jour) - état gazeux, $Rayon d\'épuisement$ (+6 au toucher à distance, DD 16), $Don des langues$\n2e (7/jour) - $Invisibilité$, résistance aux énergies destructives, invocation d\'essaim, vent murmurant\n1er (7/jour) - endurance aux énergies destructives, $Feuille morte$, $Armure de mage$†, $Protection contre le bien$, $Bouclier$†\n0 (6/jour) - $Signature magique$, $Hébêtement$, $Manipulation à distance$, $Réparation$, $Message$, $Ouverture/fermeture$, $Lecture de la magie$, $Résistance$, toucher de fatigue (+3 en mélée)\n† déjà lancé\nCaractéristiques : Force 8, Dex 14, Con 13, Int 12, Sag 10, Cha 17\nDons : Préparation de potions, Magie de guerre, Création de baguettes magiques, Extension de portée, Magie insidieuse, Magie pernicieuse, Toile d\'ombre, Magie tenace\nCompétences : Bluff +12, Concentration +14, Diplomatie +5, Discrétion +!4, Intimidation +5, Connaissances (profane) +10, Perception auditive +0, Art de la magie +12, Détection +0\nPossessions : équipement de combat plus bracelets d\'armure +1, cape de résistance +2\nRemarque les possessions des gardes Shadovar sont des objets magiques de Toile d\'ombre\nBouclier d\'ombres (Sur). Un adepte des ombres peut s\'entourer d\'un globe de force violet-noir en tant qu\'action standard. Ce bouclier d\'ombres fonctionne comme un sort de bouclier, accordant à l\'utilisateur un bonus de bouclier de +4 à sa CA et absorbant les projectiles magiques lancés contre lui. De plus, un bouclier d\'ombres offre une dissimulation contre les attaques de mélée et à distance. Un adepte des ombres peut voir et atteindre à travers le bouclier, qui n\'offre donc ni couverture ni dissimulation à ses adversaires. Un garde Shadovar peut utiliser un bouclier d\'ombres jusqu\'à 10 rounds par jour. Ces rounds ne doivent pas nécessairement être consécutifs. Créer ou renvoyer un bouclier d\'ombres est une action standard', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2330);

