-- 2340 — Kharantes
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2340, 'Kharantes', 25, NULL, 'PV : 139 (16 DV)\nRD : 10/magie\nDemi-démon yuan-ti abomination Mâle roublard 7\nCM Extérieur de grande taille\nInitiative : +7\nSens : vision dans le noir 18m, odorat ; Perception auditive +22, Détection +24\nLangues : Abyssal, céleste, commun, draconique, yuan-ti\nClasse d\'armure : 27, toucher 12, pris au dépourvu 24 ; Esquive, Souplesse du serpent, esquive surnaturelle\nImmunités : contre le poison\nRésistances : à l\'acide 10, au froid 10, à l\'électricité 10, au feu 10, à l\'évasion ; RM 26\nJets de sauvegarde : Vig +10, Réf +16, Vol +14\nVitesse de déplacement : 9m (6 cases), vol 9m (moyen), escalade 6m, natation 6m\nMêlée : falchion +2 +21/+16/+11 (2d6+11/18?20) et morsure +14 (2d6+3 plus poison) ou\nMêlée : 2 griffes +19/+14/+9 chacune (1d6+7) et morsure +14 (2d6+3 plus poison)\nDistance : arc long composite de maître +18/+13/+8 (2d6+7/×3)\nEspace occupé/allonge : 3m/3m\nAttaque de base/lutte : +14/+19\nOptions d\'attaque : Combat en aveugle, Attaques réflexes, Attaque éclair, Constriction 1d6+9, Saisie améliorée, Empoisonnement (DD 23, 1d6 Con/ 1d6 Con), Châtiment du bien 1/jour (+16 dégâts), Attaque sournoise +4d6, aversion, Production d\'acide\nCapacités de type sort (NLS 10) :\nÀ volonté - $Hypnose des animaux$ (DD 18), $Enchevêtrement$ (DD 17)\n3/jour - $Ténèbres$, $Ténèbres profondes$, $Empoisonnement$, suggestion(DD 19), $Aura maudite$\n1/jour - $Métamorphose funeste$ (DD 21 ; uniquement sous forme de serpent), $Blasphème$, $Contagion$, $profanation$, $Terreur$ (DD 20), $Flétrissure$, sanctification maléfique, $Ténèbres maudites$\nCaractéristiques : Force 23, Dex 19, Con 19, Int 24, Sag 20, Cha 20\nParticularités : forme alternative, pouvoir caméléon, détection du poison, sens des pièges +2, détection des pièges\nDons : #Vigilance#, #Combat en aveugle#, #Attaques réflexes#, #Esquive#, #Vigueur surhumaine#, #Science de l\'initiative#, #Souplesse du Serpent#, #Attaque éclair#\nCompétences : Estimation +17, Équilibre +16, Bluff +19, Concentration +18, Artisanat (fabrication de poison) +19, Diplomatie +28, Déguisement +17 (+19 en comédie), Évasion +14, Renseignements +19, Discrétion +19 (+29 avec le pouvoir caméléon), Intimidation +28, Saut +9, Connaissances (nature) +19, Connaissances (plans) +19, Perception auditive +22, Déplacement silencieux +23, Fouille +26, Escamotage +16, Détection +24, Survie +20 (+22 suivre des traces, +22 en surface ou sur d\'autres plans), Natation +17, Acrobaties +14, Maîtrise des cordes +4 (+6 avec des entraves)\nPossessions : +2 falchion, arc long composite de maître (+6 bonus de Force) avec 25 flèches +1, bracelets d\'armure +4, sac sans fond (type IV) avec une pierre porte-bonheur, 2 bougies d\'invocation, kit d\'empoisonneur (+2 bonus de circonstance pour fabriquer des poisons), 982 po, 14 gemmes d\'une valeur de 100 po chacune\nForme alternative (Mag). Kharantes peut prendre la forme d\'une vipère de taille très petite à grande (voir MM 280) grâce à sa capacité psionique. Il perd ses armes naturelles et acquiert celles de la vipère qu\'il incarne. Il utilise son propre venin plutôt que celui de la vipère\nDétection du poison (Mag). Kharantes possède la capacité psionique de détecter le poison comme le sort (niveau de lanceur de sorts 6)\nAversion (Mag). Kharantes peut créer psioniquement un effet de contrainte ciblant une créature dans un rayon de 9 mètres. La cible doit réussir un jet de sauvegarde de Volonté DD 24 ou développer une aversion pour les serpents pendant 10 minutes et doit rester à au moins 6 m de tout serpent ou yuan-ti, vivant ou mort ; si elle se trouve déjà à moins de 6 m, elle peut s\'éloigner. Si le sujet est incapable de s\'éloigner ou est attaqué par un serpent ou un yuan-ti, sa Dextérité est réduite de 4 jusqu\'à ce que l\'effet se dissipe ou qu\'il ne se trouve plus à moins de 6 m d\'un serpent ou d\'un yuan-ti\nConstriction (Ext). Kharantes inflige 1d6+9 points de dégâts lorsqu\'il réussit un test de lutte\nSaisie améliorée (Ext). Si Kharantes touche une créature de taille Grande ou plus petite avec son attaque de morsure, il peut alors commencer une lutte en tant qu\'action gratuite sans provoquer d\'attaques d\'opportunité. S\'il réussit le test de lutte, il établit une prise et peut étrangler\nProduire de l\'acide (Mag). Kharantes a la capacité psionique de sécréter de l\'acide par son corps, infligeant 3d6 points de dégâts d\'acide à la prochaine créature qu\'il touche, y compris une créature touchée par son attaque de morsure. S\'il est en train de lutter, de constrictionner ou d\'immobiliser un ennemi lorsqu\'il utilise ce pouvoir, sa prise inflige 5d6 points de dégâts d\'acide. L\'acide devient inerte lorsqu\'il quitte son corps, et il est immunisé contre ses effets\nPouvoir caméléon (Mag). Kharantes peut changer sa couleur et celle de son équipement pour se fondre dans son environnement, ce qui lui confère un bonus de circonstance de +10 aux tests de discrétion\nCompétences. Kharantes peut toujours prendre 10 aux tests d\'escalade ou de natation, même s\'il est pressé, menacé, distrait ou en danger', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2340);

-- 2341 — pilleur de tombe supérieur
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2341, 'pilleur de tombe supérieur', 3, NULL, 'PV : 150 chacun (20 DV)\nRD : 10/adamantite\nPercetombe avancé\nN Créature artificielle de Très grande taille\nInitiative : +2\nSens : cécité, vision aveugle 36 m, perception des vibrations 18 m ; Perception auditive +19, Détection +19\nLangues : commun, netherisse, Commun des profondeurs, télépathie 30 m\nClasse d\'armure : 35, toucher 8, pris au dépourvu 33 ;\nImmunités : contre le feu, les attaques de regard, les illusions, les effets visuels, les dégâts de capacité, le drain de capacité, les coups critiques, les effets mortels, la mort par dégâts massifs, les maladies, l\'absorption d\'énergie, l\'épuisement, la fatigue, la magie, les sorts et caractéristiques affectant l\'esprit (charmes, compulsions, fantasmes, schémas et effets sur le moral), effets de nécromancie, dégâts non mortels, paralysie, poison, effets de sommeil, étourdissement, tout effet nécessitant un jet de sauvegarde de Vigueur à moins qu\'il ne fonctionne également sur les objets\nRésistances : froid 10, électricité 10\nJets de sauvegarde : Vig +8, Réf +8, Vol +8\nVitesse de déplacement : 9 m (6 cases) en armure de pierre ; vitesse de base 12 m, creuser 3 m\nMêlée : marteau de lancer en adamantite boomerang de tonnerre +2 +27/+22/+17 (3d6+18/19?20/×3) et morsure +18 (2d6+5) ou\nMêlée : 2 coups +24 chacun (2d6+11) et morsure +18 (2d6+5)\nDistance : marteau de lancer en adamantite boomerang de tonnerre +2 +18 (3d6+18/19?20/×3)\nEspace occupé/allonge : 4,5m/4,5m\nAttaque de base/lutte : +15/+34\nOptions d\'attaque : Enchaînement, Succession d\'enchaînements, Attaque en puissance\nCapacités de type sort (NLS 22) :\nÀ volonté - $Détection de la magie$\n7/jour - $façonnage de la pierre$\n3/jour - $pierres acérées$ (DD 17)\nCaractéristiques : Force 32, Dex 14, Con ?, Int 14, Sag 11, Cha 16\nParticularités : traits de créature artificielle, masse, réparation\nDons : #Enchaînement#, #Succession d\'enchaînements#, #Vigueur surhumaine#, #Science du critique# (masse), #Volonté de fer#, #Attaque en puissance#, #Arme de prédilection# (masse)\nCompétences : Estimation +17, Perception auditive +19, Fouille +21, Détection +19, Survie +19 (+21 suivre des traces)\nPossessions : masse +2 , armure en pierre thaalud +3, l\'un possède un Anneau de contrôle des éléments (terre)\nMasse (Sur). Chaque grand percetombe est créé avec une masse adamantite +2 adaptée à sa taille. Entre les mains d\'un percetombe, l\'arme gagne les capacités spéciales de lancer, boomerang et de tonnerre\nRéparation (Sur). Un effet façonnage de la pierre répare des dégâts équivalents à 1d8 + niveau du lanceur de sorts points de vie s\'il est utilisé sur un percetombe. La créature peut utiliser sa propre capacité magique pour se réparer', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2341);

-- 2342 — Askilion
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2342, 'Askilion', 1, NULL, 'PV : 208 (32 DV)\nHorreur dévorante barde 11/hymnode funèbre 5\nNM Minuscule mort-vivant (essaim)\nInitiative : +4\nSens : vision dans le noir 18m ; Perception auditive +33, Détection +19\nLangues : Auran, commun, elfique, orque\nAura : terreur 18m (NLS 16, DD 24)\nClasse d\'armure : 14, toucher 14, pris au dépourvu 14\nImmunités : immunités des morts-vivants, sorts ciblés, dégâts des armes\nRésistances : effets d\'énergie positive 10\nJets de sauvegarde : Vig +9, Réf +13, Vol +21\nFaiblesse : vulnérabilité aux sorts de zone\nVitesse de déplacement : 12 m (8 cases), escalade 6 m\nMêlée : essaim (4d6 plus Mal dévorant)\nEspace occupé/allonge : 3 m/0 m\nAttaque de base : +19 ; Lutte ?\nOptions d\'attaque : Mal dévorant, création de rejetons, distraction (DD 24), musique bardique 11/jour (chant funèbre [chant de l\'éveil, chant de l\'horreur [DD 29], chant du deuil [DD 29], chant du réconfort, chant de la tristesse [DD 29], inspirer la grandeur, suggestion [DD 21], inspirer la compétence, inspirer le courage +2, fasciner 4 créatures, contre-chant)\nSorts de barde connus (NLS 11e) :\n4e (2/jour) - Porte dimensionnelle, Immobilisation de monstre (DD 20), Lueur d\'arc-en-ciel (DD 20)\n3e (4/jour) - Désespoir foudroyant (DD 19), Soins importants, détection de l\'invisibilité, Lenteur (DD 19)\n2e (5/jour) - cécité/surdité (DD 18), Flou, Détection de pensées (DD 18), Cacophonie (DD 18)\n1er (5/jour) - Charme-personne (DD 17), Détection des passages secrets, Hypnose (DD 17), Sommeil (DD 17)\n0 (3/jour) - Lumières dansantes, Détection de la magie, Illumination (DD 16), Berceuse (DD 16), Manipulation à distance, Ouverture/fermeture\nCaractéristiques : Force 1, Dex 11, Con ?, Int 16, Sag 10, Cha 22\nParticularités : connaissances bardiques +14, traits d\'essaim, traits de mort-vivant\nDons : Esquive, Sort d\'énervation (2 emplacements de sort supplémentaires, +50 % de dégâts contre les créatures vivantes grâce à l\'énergie négative), Renoncer aux matériaux, Science de l\'initiative, Résistance à l\'énergie positive, Requiem, Talent (Représentation (chant))\nCompétences : Équilibre +11, Escalade +38, Concentration +25, Diplomatie +8, Renseignements +17, Discrétion +42, Connaissances (religion) +22, Perception auditive +33, Déplacement silencieux +19, Représentation (chant) +28, Fouille +22, Psychologie +8, Art de la magie +14, Détection +19, Survie +19 (+21 suivre des pistages)\nMal dévorant (Sur). Maladie surnaturelle ? essaim, jet de sauvegarde de Vigueur 21, période d\'incubation 1 jour ; 1d6 points de dégâts à la Constitution. Contrairement aux maladies normales, mais à l\'instar de la pourriture des momies, la consommation totale se poursuit jusqu\'à ce que la Constitution de la créature affectée atteigne 0 (à ce moment-là, elle meurt) ou jusqu\'à ce qu\'un sort de guérison des maladies ou une magie similaire soit appliqué. Si une créature affectée meurt, elle se relève sous la forme d\'une nouvelle Horreur dévorante 1d4 rounds après sa mort\nCréation de rejetons (Sur). Toute créature vivante tuée par une Horreur dévorante se relève sous la forme d\'une nouvelle Horreur dévorante (typiquement non intelligente) dans un délai de 1d4 rounds\nDistraction (Ext). Toute créature vivante vulnérable aux dégâts infligés par l\'essaim qui commence son tour avec un essaim dans sa case est nauséeuse pendant 1 round ; un jet de sauvegarde de Vigueur DD 24 réussi annule l\'effet. Créature unique créée par le Gardien de Thaal à partir d\'un aventurier débutant, Askilion a réussi à conserver l\'intelligence et les caractéristiques de sa forme originale. En tant que barde hymnode funèbre, Askilion possède les caractéristiques de chant funèbre décrites aux pages 43-44 de Libris Mortis\nChant de chagrin. Tant qu\'il peut entendre le chant et pendant 5 rounds après, un ennemi subit une pénalité de -2 sur ses jets de sauvegarde de Volonté, ses jets d\'attaque et ses jets de dégâts. Un jet de sauvegarde de Volonté réussi annule l\'effet et rend la cible immunisée pendant 24 heures\nChant de renforcement. Tous les morts-vivants situés à moins de 9 mètres (y compris Askilion lui-même) gagnent +16 en résistance au tour tant que le hymnode funèbre chante et pendant 10 rounds après cela\nChant de chagrin. Les ennemis situés à moins de 60 pieds et capables d\'entendre le chant doivent réussir un jet de sauvegarde de Volonté ou être confus (comme le sort) tant que le hymnode funèbre chante et pendant 5 rounds après cela\nChant d\'horreur. Les ennemis situés à moins de 60 pieds et capables d\'entendre le chant doivent réussir un jet de sauvegarde de Volonté ou subir 1d6 points de dégâts à la Force et 1d6 points de dégâts à la Dextérité. Une créature affectée par le chant, ou qui réussit son jet de sauvegarde de Volonté, est immunisée contre les utilisations supplémentaires du chant pendant 24 heures', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2342);

-- 2343 — Éclaireurs aériens Shadovar
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2343, 'Éclaireurs aériens Shadovar', 28, NULL, 'PV : 62 chacun (11 DV)\nHomme ou femme humain guerrier 5/rôdeur 2/ensorceleur 4\nNM Humanoïde de taille moyenne\nInitiative : +8 avec grâce féline\nSens : Perception auditive +7, Détection +7\nLangues : Commun, elfique, netherisse\nClasse d\'armure : 26, toucher 17, pris au dépourvu 20 avec bouclier et grâce féline\nClasse d\'armure : 27, toucher 18, pris au dépourvu 21 avec bouclier, grâce féline et esquive\nJets de sauvegarde : Vig +9, Réf +7, Volonté +7\nVitesse de déplacement : 9 m (6 cases) ; attaque au passage\nMêlée : épée à deux mains +2 +14/+9 (2d6+6/19?20) ou\nMêlée : lance de maître +14/+9 (1d6+3/´3)\nDistance : arc long composite +2 +14/+9 (1d8+3/×3) avec grâce féline ou\nDistance : arc long composite +2 +12/+12/+7 (1d8+3/×3) avec Tir rapide et Grâce féline\nAttaque de base/lutte : +9/+12\nOptions d\'attaque : Combat monté, Attaque en puissance, Charge dévastatrice ; ennemi préféré elfes +2\nÉquipement de combat : Potion de soins légers, potion de soins modérés, 2 feux d\'alchimiste\nSorts de ensorceleur connus (niveau de lanceur de sorts 4 ; 20 % de chances d\'échec des sorts profanes) :\n2e (1/jour) - $Grâce féline$?\n1er (3/jour) - Endurance aux énergies destructices??, $Bouclier$?, $Coup au but$\n0 (6/jour) - $Détection de la magie$, $Destruction de mort-vivant$ (+11 au toucher à distance), $Lumière$, $Manipulation à distance$, $Message$, $Résistance$\n? déjà lancé\nCaractéristiques : Force 17, Dex 18, Con 13, Int 12, Sag 10, Cha 13 avec grâce féline\nParticularités : empathie sauvage +3 (?1 bêtes magiques)\nDons : #Vigilance#, #Discipline#, #Esquive#, #Science de l\'initiative#, #Combat monté#, #Attaque en puissance#, #Tir rapide#, #Attaque au Galop#, #Charge dévastatrice#, #Pistage#\nCompétences : Escalade +10, Concentration +10, Dressage +9, Saut +10, Connaissances (mystères) +3, Perception auditive +7, Équitation +12, Art de la magie+8, Détection +7, Survie +5, Maîtrise des cordes +3\nPossessions : équipement de combat plus armure de cuir cloutée +3, épée à deux mains +2, lance de maître, arc long composite +2 (+2 bonus de Force) avec 20 flèches, anneau de protection +2, anneau de feuille morte, 5 po', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2343);

-- 2344 — Adepte de l'ombre Sharéen
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2344, 'Adepte de l\'ombre Sharéen', 28, NULL, 'PV : 67 (12 DV)\nHumain, homme ou femme, prêtre 5 (Shar)/adepte de l\'ombre 7\nCM Humanoïde de taille moyenne\nInitiative : +4\nSens : vision dans le noir 18 m ; Perception auditive +5, Détection +5\nLangues : commun, netherisse\nClasse d\'armure : 24, toucher 12, pris au dépourvu 24 ; +4 et absorption des projectiles magiques avec bouclier d\'ombres\nChance de manquer 20 % (bouclier d\'ombres)\nJets de sauvegarde : Vig +8, Réf +3, Vol +14 ; +4 contre les illusions ; +2 contre les enchantements, la nécromancie et les sorts ayant le descripteur « ténèbres »\nVitesse de déplacement : 6m (4 cases) en armure complète +1, vitesse de base 9m\nMêlée : fléau d\'armes vicieux +1 +8/+3 (1d8+2 plus 2d6, plus 1d6 pour le porteur)\nDistance : arbalète lourde de maître +7 (1d10/19-20)\nAttaque de base/lutte : +6/+7\nOptions d\'attaque : Combat en aveugle\nActions spéciales : Intimidation des mort-vivants 4/jour (+3, 2d6+3, 5e), traversée des ombres, bouclier d\'ombres\nÉquipement de combat : parchemin de soins importants, antitoxine, gaz de sommeil, pierre de tonnerre\nSorts de prêtre préparées (NLS 12e ; 1d20+14 pour surmonter la RM) :\n6e - $Mise à mal$* (+7 en mêlée, DD 22), $Oeil indiscret$D* , $Mot de rappel$*\n5e - $éclair des ténèbres$D* (+6 en toucher à distance, DD 20), $Colonne de feu$* (DD 19), $Injonction suprême$* (DD 21), $Malédiction$ augmentée* (DD 21), $Exécution$ (DD 21)\n4e - $Marche dans les airs$ (NLS 11e), $Soins intensifs$* , $Liberté de mouvement$* , $Immobilisation de personne$ augmentée* (DD 20), $Ténèbres maudites$ D (NLS 12e, DD 19)\n3e - $Lueur noire$ D * (DD 18), $Soins importants$* (2), $Injonction$* renforcée (2, DD 19), négation de l?invisibilité (NLS 11e)\n2e - $Aide$* , $cécité/surdité$D* (DC 18), $Soins modérés$* , $Cacophonie$ (NLS 11e), $Arme spirituelle$ (2, +7 en mêlée, +6 à distance, NLS 11e)\n1er - $Bénédiction$* , $soins légers$* (2), $Faveur divine$ (NLS 11), $endurance aux énergies destructrices$* , $Bouclier entropique$* , $Protection contre le bien$D* (NLS 13), $Bouclier de la foi$*\n0 - $Soins superficiels$* (2), $Détection de la magie$* (2), $Assistance divine$* (2)\nD : Sort de domaine. Divinité : Shar. Domaines : Ténèbres, Mal\n* Jet de niveau de lanceur de sorts DD 23 contre les divination des utilisateurs de la Toile ; Jet de niveau de lanceur de sorts DD 27 contre les jets de dissipation des utilisateurs de la Toile, bonus de +4 aux jets de niveau de lanceur de sorts effectués pour vaincre la résistance à la magie des utilisateurs de la Toile\nCapacités de type sort (niveau de lanceur de sorts 7) :\n1/jour - $traversée des ombres$\nCaractéristiques : Force 13, Dex 10, Con 14, Int 10, Sag 20, Cha 12\nDons : #Magie de guerre#, #Magie insidieuse#, #Magie pernicieuse#, #Magie de la Toile d\'ombre#, #Efficacité des sorts accrue#, #Magie de guerre#, #Magie tenace#\nCompétences : Concentration +11, Discrétion +4, Connaissances (mystères) +10, Connaissances (religion) +10, Art de la magie+12\nPossessions : Équipement de combat plus armure complète +1, bouclier lourd en acier +1, fléau d\'armes +1 vicieux, arbalète lourde de maître avec 10 carreaux, médaillon de sagesse +2, amulette d\'armure naturelle +1, anneau de protection +2, symbole sacré en argent\nBouclier d\'ombres (Sur). Un adepte des ombres peut s\'entourer d\'un globe de force violet-noir en tant qu\'action standard. Ce bouclier fonctionne comme un sort de bouclier, accordant un bonus de bouclier de +4 à la CA et absorbant les projectiles magiques lancés sur l\'utilisateur. De plus, il offre une dissimulation contre les attaques de mêlée et à distance. Le bouclier peut être utilisé jusqu\'à 12 rounds par jour, mais le temps n\'a pas besoin d\'être consécutif', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2344);

-- 2345 — Soldat d'élite krinth
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2345, 'Soldat d\'élite krinth', 28, NULL, 'PV : 73 chacun (8 DV)\nKrinth mâle ou femelle Guerrier 8\nNM Humanoïde de taille moyenne (extraplanaire)\nInitiative : +1\nSens : vision dans le noir 18m ; Perception auditive +1, Détection +1\nLangues : Commun, Netherisse\nClasse d\'armure : 21, toucher 11, à plat 20 ; Esquive ou\nClasse d\'armure : 17, toucher 11, pris au dépourvu 17 en cotte de mailles\nImmunités : contre l\'état secoué\nJets de sauvegarde : Vig +10, Réf +4, Vol +4 ; +1 contre les sorts et effets ayant le descripteur ombre, +4 contre la peur\nVitesse de déplacement : 6m (4 carrés) en armure complète de maître, vitesse de base 9m\nMêlée : épée bâtarde de maître +2 +15/+10 (1d10+7/19?20 plus poison: 1d6 For/1d6 For, DD24)\nDistance : arc long composite de maître +1 +10/+5 (1d8+3/×3 plus poison: 1d6 For/1d6 For, DD24)\nAttaque de base/lutte : +8/+11\nOptions d\'attaque : Tir à bout portant, Attaque en puissance, Tir de précision ; poison (DD 24, 1d6 Force/2d6 Force)\nÉquipement de combat : 3 fioles d\'acide, 3 feux d\'alchimiste, 2 fioles d\'antitoxine, bâton fumigène, sac de tanglefoot, 2 pierres de tonnerre\nCaractéristiques : Force 17, Dex 13, Con 16, Int 10, Sag 12, Cha 6\nDons : #Esquive#, #Endurance#, #Maniement d\'une arme exotique#(épée bâtarde), #Tir à bout portant#, #Attaque en puissance#, #Tir de précision#, #Arme de prédilection# (épée bâtarde), #Spécialisation martiale# (épée bâtarde)\nCompétences : Escalade +2 (+7 en cotte de mailles), Dressage +3, Discrétion -5 (-3 dans l\'ombre, +0 en cotte de mailles ou +2 dans l\'ombre et en cotte de mailles), Saut +3 (+8 en cotte de mailles), Équitation +9\nPossessions : équipement de combat plus armure complète de maître, bouclier lourd en acier de maître, épée bâtarde de maître, arc long composite de maître (+3 bonus de Force) avec 20 flèches, 4 doses de venin de ver pourpre', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2345);

-- 2346 — Serpents de la mer de l'ombre
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2346, 'Serpents de la mer de l\'ombre', 23, NULL, 'PV : 162 chacun (12 DV)\nRD : 5/perforant\nNM Bête magique de très grande taille\nInitiative : +6\nSens : vision aveugle 18 m (73 m sous l\'eau), vision dans le noir 18 m, vision nocturne ; Perception auditive +11, Détection +11\nLangues : Netherisse\nClasse d\'armure : 25, toucher 16, pris au dépourvu 23\nRésistances : sonique 10\nJets de sauvegarde : Vig +18, Réf +12, Vol +5\nVitesse de déplacement : 6m (4 cases), natation 15m\nMêlée : morsure +20 (2d6+10) et coup de queue +16 (2d6+5)\nEspace occupé/allonge : 4,5m/3m\nAttaque de base/lutte : +12/+30\nOptions d\'attaque : Attaques réflexes ; lance sonique, onde sonique, croc-en-jambe\nCaractéristiques : Force 31, Dex 15, Con 26, Int 10, Sag 13, Cha 6\nDons : #Attaques réflexes#, #Vigueur surhumaine#, #Science de l\'initiative#, #Réflexes surhumains#, #Arme de prédilection# (coup de queue)\nCompétences : Discrétion +12, Perception auditive +11, Fouille +12, Détection +11, Natation +18\nPerception aveugle (Ext). Une mer de l\'ombre peut localiser les créatures sous l\'eau dans un rayon de 36m par des moyens non visuels (écholocation). Sous l\'eau, la portée est de 72m. Les adversaires qu\'un serpent de mer fantôme ne peut pas voir sont totalement dissimulés à ses yeux\nRetenir son souffle (Ext). Un serpent de mer fantôme peut retenir son souffle pendant un nombre de rounds égal à 8 × son score de Constitution avant de risquer de se noyer (voir DMG 304)\nLance sonique (Ext). Un serpent de mer de l\'ombre peut générer un rayon sonore d\'une portée de 36m sans incrément de portée. Le rayon inflige 6d6 points de dégâts soniques. Après avoir utilisé ce pouvoir, un serpent doit attendre 1d4 rounds avant de pouvoir l\'utiliser à nouveau. Sous l\'eau, la portée de la lance est de 72m\nOnde sonore (Ext). Une fois par heure, un serpent peut générer une onde sonore assourdissante dans un rayon de 40 mètres autour de lui. Toute créature vivante se trouvant dans ce rayon (à l\'exception des autres serpents) doit réussir un jet de sauvegarde de Vigueur (DD 24) ou être assourdie pendant 1d4 rounds. Sous l\'eau, la portée de l\'onde est de 72 mètres. Une créature soumise à plusieurs ondes à la fois n\'a besoin de faire qu\'un seul jet de sauvegarde\nCroc-en-jambe (Ext). Un serpent qui touche avec une attaque de morsure peut tenter de faire trébucher son adversaire (+18 modificateur de jet) sans utiliser d\'action, sans effectuer d\'attaque de contact et sans provoquer d\'attaques d\'opportunité. Si la tentative échoue, l\'adversaire ne peut pas réagir pour faire trébucher le serpent. Sous l\'eau, un adversaire déséquilibré qui est au moins d\'une catégorie de taille inférieure à celle du serpent est projeté à 10 pieds dans la direction choisie par le serpent par différence de catégorie de taille. Par exemple, un adversaire de taille Moyenne est projeté à 6 mètres\nDéviation (Mag). Un serpent de mer de l\'ombre génère un champ magique qui lui confère un bonus de déviation à sa classe d\'armure égal à son modificateur de Constitution (minimum +1). Ce pouvoir est toujours actif et a un niveau de lanceur de sorts égal aux dés de vie du serpent. Si le champ est annulé ou supprimé, le serpent peut le réactiver comme action gratuite lors de son prochain tour\nCompétences. Un serpent de la mer d\'ombre bénéficie d\'un bonus racial de +8 aux tests de Discrétion et d\'un bonus racial de +4 aux tests de Perception auditive, de Fouille et de Détection. Il bénéficie d\'un bonus racial de +8 aux tests de Natation pour effectuer une action spéciale ou éviter un danger. Il peut toujours prendre 10 à un test de Natation, même s\'il est distrait ou en danger. Il peut utiliser l\'action Courir tout en nageant, à condition de nager en ligne droite', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2346);

