INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2347, 'krinth Guerrier prêtre de Shar', 28, NULL, 'PV : 91 (11 DV)\nKrinth mâles et femelles Guerriers 6/expert 2/prêtre 3 (Shar)\nCM Humanoïde de taille moyenne (extraplanaire)\nInitiative : +4\nSens : vision dans le noir 18m ; Perception auditive +11, Détection +11\nLangues : commun, netherisse\nClasse d\'armure : 24, toucher 11, pris au dépourvu 24\nImmunités : contre l\'état secoué\nJets de sauvegarde : Vig +12, Réf +4, Vol +13 ; +1 contre les sorts et effets ayant le descripteur ombre, +4 contre la terreur\nVitesse de déplacement : 6m. (4 cases) en armure complète +2, vitesse de base 9m\nMêlée : +1 épée bâtarde +12/+7 (1d10+4/19?20)\nDistance : +1 arc long composite +10/+5 (1d8+2/×3)\nAttaque de base/lutte : +9/+10\nOptions d\'attaque : Combat en aveugle, Attaque en puissance\nActions spéciales : Intimidation des mort-vivants 3/jour (+0, 2d6+2, 3e)\nÉquipement de combat : 2 parchemins de soin des blessures légères, 2 parchemins de soins modérés, parchemin de fracassement, parchemin de ténèbres maudites, parchemin de zone de vérité\nSorts de prêtre préparés (NLS 3e) :\n2e - cécité/surditéD (DC 16), Force de taureau, Arme spirituelle (+10 en mêlée, +9 à distance)\n1er - Soins légers, Faveur divine, Brume de dissimulationD, Sanctuaire\n0 - Soins superficiels, Détection de la magie, Assistance divine, Résistance\nCaractéristiques : Force 13, Dex 10, Con 16, Int 10, Sag 18, Cha 11\nDons : Vigilance, Combat en aveugle, Endurance, Maniement d\'une arme exotique (épée bâtarde), Science de l\'initiative, Attaque en puissance, Magie de l\'ombre, Arme de prédilection (épée bâtarde), Spécialisation martiale (épée bâtarde)\nCompétences : Escalade -1, Concentration +9, Dressage +5, Discrétion -6 (-4 dans l\'ombre), Saut -1, Perception auditive +11, Équitation +7, Psychologie +6, Détection +11\nPossessions : équipement de combat plus +2 armure complète, +1 bouclier lourd en acier, +1 épée bâtarde, +1 arc long composite (+1 bonus de Force) avec 10 flèches, anneau de protection +1, médaillon de sagesse +2, symbole sacré en argent, 33 po', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2347);

-- 2348 — Phaerimm adulte
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2348, 'Phaerimm adulte', 21, NULL, 'PV : 84 chacun (13 DV) ; régénération/guérison rapide\nRD : 10/magie\nNM Aberration de Grande taille\nInitiative : +4\nSens : vision dans le noir 18 m ; vision magique 36 m, détection de la magie (NLS 13), détection de l\'invisibilité 36 m ; Perception auditive +15, Détection +15\nLangues : chondathien, commun, elfique, netherisse ; télépathie 30m\nClasse d\'armure : 27, toucher 9, pris au dépourvu 27\nImmunités : contre la pétrification, la métamorphose\nRM : 23\nJets de sauvegarde : Vig +8, Réf +6, Vol +13\nVitesse de déplacement : vol 10 m (6 cases) (parfait)\nMêlée : 4 griffes +12 chacune (1d6+4) et morsure +7 (2d6+2) et dard +7 (1d8+2 plus poison)\nEspace occupé/allonge : 3 m/3 m\nAttaque de base/lutte : +9/+17\nOptions d\'attaque : Extension d\'effet ; poison\nActions spéciales : implant\nSorts de ensorceleur connus (NLS 13 ; 1d20+15 pour surmonter la RM) :\n6e (4/jour) - $éclair multiple$ (DD 21), $Désintégration$ (DD 21)\n5e (7/jour) - $Brume mortelle$ (DD 20), $Immobilisation de monstre$ (DD 20), $Télékinésie$ (DD 20)\n4e (7/jour) - $Charme-monstre$ (DD 19), $Porte dimensionnelle$, $Assassin imaginaire$ (DD 19), $Mur de glace$\n3e (7/jour) - $Déplacement$, $éclair$(DD 18), $Tempête de neige$, $Baiser du vampire$ (+13 au toucher en mêlée)\n2e (7/jour) - $Baiser de la goule$ (+13 en mêlée, DD 17), $détection de l\'invisibilité$, $Main spectrale$ (+13 en mêlée), $Nuée grouillante$, $Fou rire de Tasha$ (DD 17)\n1er niveau (8/jour) - $Contact glacial$ (+13 en mêlée), $Graisse$, $Projectile magique$, $Rayon affaiblissant$ (+9 à distance), $Bouclier$\n0 (4/jour) - $Signature magique$, $Lumières dansantes$, $Détection de la magie$, $Destruction de mort-vivant$ (+9 à distance), $Son imaginaire$ (DD 15), $Manipulation à distance$, $Message$, $Ouverture/fermeture$, $Lecture de la magie$\nCapacités magiques : (niveau de lanceur de sorts 13) :\nÀ volonté - $Détection de la magie$\nCaractéristiques : Force 18, Dex 11, Con 14, Int 17, Sag 20, Cha 21\nDons : Extension d\'effet, #Vigueur surhumaine#, #Science de l\'initiative#, #Réflexes surhumains#, #Efficacité des sorts accrue#\nCompétences : Concentration +12, Diplomatie +7, Discrétion -4, Intimidation +15, Connaissances (mystères) +13, Perception auditive +15, Fouille +13, Psychologie +15, Art de la magie+15, Détection +15\nVol (Ext). Le corps d\'un phaerimm étant naturellement flottant, il peut voler à une vitesse de 9 mètres. Cette flottabilité confère également à la créature un effet permanent de feuille morte (comme le sort) avec une portée personnelle\nImplant (Ext). En tant qu\'action simple, un phaerimm adulte mature peut utiliser son dard pour pondre des oeufs à l\'intérieur d\'une créature paralysée. Les petits éclosent environ 90 jours plus tard, dévorant littéralement leur hôte de l\'intérieur. Un sort de guérison des maladies permet de débarrasser la victime des oeufs, tout comme un jet de Premiers secours réussi avec un DD de 20 effectué par un personnage ayant des rangs dans cette compétence. Si le jet échoue, le soigneur peut réessayer, mais chaque tentative (réussie ou non) inflige 1d4 points de dégâts au patient\nEmpoisonnement (Ext). Blessure, Vigueur DD 18, paralysie 2d4 rounds/paralysie 1d3 heures. Les créatures paralysées effectuent une lévitation, impuissantes, à quelques mètres du sol', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2348);

-- 2349 — Hadrhune
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2349, 'Hadrhune', 28, NULL, 'PV : 77 (+20 dans l\'obscurité ou l\'ombre) (20 DV) ; guérison rapide 2\nHumain reflet magicien 10 / adepte de l\'ombre 10\nNM Humanoïde de taille moyenne\nInitiative : +5\nSens : vision dans le noir 18m, vision nocturne ; voir l\'invisible ; Perception auditive +9, Détection +9\nLangues : chondathien, commun, draconique, netherisse, thorass\nClasse d\'armure : 29, toucher 19, pris au dépourvu 24 ; +4 et absorption des projectiles magiques avec bouclier supérieur des ombres\nChance de manquer 20 % (bouclier supérieur des ombres)\nImmunités : contre la divination, les effets détectant les émotions ou les pensées, les sorts et capacités affectant l\'esprit, la voyance\nRM : 31 dans les ténèbres ou l\'ombre ou\nRM : 22\nJets de sauvegarde : Vig +12 (+16 dans l\'obscurité ou les ombres), Réf +18 (+22 dans l\'obscurité ou les ombres), Vol +23 (+27 dans l\'obscurité ou les ombres) ; +5 contre les illusions ; +3 contre les enchantements, la nécromancie et les sorts ayant le descripteur « ténèbres »\nFaiblesse : perd ses capacités d\'ombre (vision dans le noir, vitesse accrue, foulée d\'ombre, guérison rapide, contrôle de la lumière, invisibilité, image d\'ombre) lorsqu\'elle n\'est pas dans l\'obscurité ou les ombres\nVitesse de déplacement : 9m (6 cases), 15m dans l\'obscurité ou les ombres, vol (grâce à un sort) 18 m (bon) ; foulée d\'ombre, traversée des ombres\nMêlée : -\nAttaque de base/lutte : +10/+10\nActions spéciales : contrôle de la lumière, bouclier d\'ombres, invisibilité, double d\'ombre, voyage dans l\'ombre\nSorts de magicien préparés (NLS 20 ; 1d20+22 pour surmonter la RM) :\n9e - $Domination universelle$* (DC 25), $Mot de pouvoir mortel$* , plainte d\'outretombe* (DC 25), $Ennemi subconscient$* (DC 25)\n8e - $esprit impénétrable$†, $magie des ombres suprême$* (2, DD 24) porte dimensionnelle accélérée, énergie négative accélérée* (+15 au toucher à distance)\n7e - $Doigt de mort$* (DD 23), $Mot de pouvoir étourdissant$* , $Dissipation suprême$ silencieuse, $Renvoi des sorts$\n6e - $Brume acide$, $Cercle de mort$* (DD 22), voile†\n5e - $Projectile magique$ (3, NLS 19e), $Magie des ombres$* (DD 21, NLS 19e), $Suggestion$ silencieuse* (DD 19)\n4e - $Confusion$* (DD 20), $Assassin imaginaire$* (2, DD 20), dissipation silencieuse de la magie, éclair funeste de Sinsabur (DD 20)\n3e - $Lueur noire$, $Vol$† (NLS 19), $Protection contre les énergies destructives$, $Suggestion$* (2, DC 19)\n2e - $Armure mortelle$, $Baiser de la goule$* (2, +10 en mêlée, DC 18), détection de l\'invisibilité†, $Main spectrale$* (+10 en mêlée), $Fou rire de Tasha$* (DC 18)\n1er niveau - $Projectile magique$ (2, NLS 19), $Protection contre le bien$, $Rayon affaiblissant$* (+15 au toucher à distance), $Bouclier$ (2)\n0 - $Détection de la magie$, $Manipulation à distance$ (NLS 19), $Message$ (NLS 19), $Prestidigitation$\n† déjà lancé\n* DD 35 test de niveau de lanceur de sorts contre les tests de dissipation des utilisateurs de Toile\nCapacités magiques : (NLS 20) :\n1/round - $invisibilité$ (dans les ténèbres ou dans l\'ombre uniquement)\n1/jour - $traversée des ombres$ (NLS 10)\n3/jour - image d\'ombre (comme image miroir, 1d4+6 images, dans les ténèbres ou les ombres uniquement)\nCaractéristiques : Force 10, Dex 20, Con 13 (15 dans les ténèbres ou les ombres), Int 21, Sag 14, Cha 14 (16 dans les ténèbres ou les ombres)\nDons : #Magie de guerre#, #Création de bâtons magiques#, #Création d\'objets merveilleux#, #Magie insidieuse#, #Maîtrise des nodes#, #Magie pernicieuse#, #Incantation rapide#, #Écriture de parchemins#, Magie des ombres, #Incantation silencieuse#, #Efficacité des sorts accrue#, Incantation statique, #Magie tenace#\nCompétences : Bluff +12, Concentration +21, Artisanat (alchimie) +15, Décryptage +15, Déguisement +12, Discrétion +25, Connaissances (mystères) +25, Connaissances (plans) +25, Perception auditive +9, Déplacement silencieux +13, Art de la magie+25, Détection +9\nPossessions : robe noire d\'archimage, gants de dextérité +6, bottes de vitesse, amulette d\'armure naturelle +5, cape de résistance +5, perle de pouvoir (niveau 7)\nGuérison rapide (Ext). Hadrhune guérit 2 points de dégâts par round, à condition qu\'il soit encore en vie et dans les ténèbres ou l\'ombre\nSaut d\'ombre (Mag). Dans les ténèbres ou l\'ombre, Hadrhune peut disparaître de l\'endroit où il se trouve et réapparaître dans n\'importe quelle zone ombragée dans un rayon de 90m, une fois tous les 2 rounds, en tant qu\'action de déplacement\nContrôle de la lumière (Mag). Dans une lumière tamisée, Hadrhune peut réduire le niveau de lumière dans un rayon de 30m jusqu\'à 100 %. Cet effet réduit la portée effective globale de la vision mystique des personnages et des créatures dépendants de la lumière du même pourcentage. Un personnage se trouvant dans la zone affectée bénéficie d\'un bonus de +1 aux jets de discrétion pour chaque réduction de 25 % de la lumière\nBouclier d\'ombres supérieur (Sur). Hadrhune peut s\'entourer d\'un globe de force violet-noir en tant qu\'action standard. Ce bouclier d\'ombres fonctionne comme un sort de bouclier, lui accordant un bonus de +4 à sa CA et absorbant les projectiles magiques lancés contre lui. De plus, un bouclier d\'ombres offre une dissimulation contre les attaques de mêlée ou à distance. Hadrhune peut voir et atteindre à travers le bouclier, qui n\'offre donc ni couverture ni dissimulation à ses adversaires. Hadrhune peut utiliser son bouclier d\'ombres jusqu\'à 20 rounds par jour. Cette durée ne doit pas nécessairement être consécutive et peut être divisée en incréments aussi petits que 1 round. Il peut le renvoyer en tant qu\'action standard\nVoyage dans l\'ombre (Mag). Une fois par jour, lorsqu\'il se trouve dans une zone d\'ombre, Hadrhune peut soit se téléporter sans erreur pour atteindre un lieu ombragé du même monde, soit changer de plan pour accéder au plan de l\'ombre\nCompétences. Hadrhune bénéficie d\'un bonus racial de +4 aux tests de Perception auditive et de Détection dans les ténèbres ou l\'ombre (pris en compte dans les statistiques ci-dessus), et d\'un bonus racial de +8 aux tests de Discrétion et de Déplacement silencieux. Il ne subit aucune pénalité due à un mauvais éclairage', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2349);

