-- 2351 — Delethyrsos
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2351, 'Delethyrsos', 11, NULL, 'PV : 275 (22 DV)\nRD : 10/magie\nDragon de l\'ombre adulte mature\nCM dragon (terre) de Grande taille\nInitiative : +6\nSens : perception aveugle 18m, vision dans le noir 36m ; Perception auditive +34, Détection +34\nAura : présence effrayante (DD 26)\nLangues : commun, damarien, draconique, géant, netherisse, commun des profondeurs\nClasse d\'armure : 40, toucher 11, pris au dépourvu 38\nRM : 25\nImmunités : contre les effets de sommeil magiques, la paralysie\nJets de sauvegarde : Vig +21, Réf +17, Vol +20\nVitesse de déplacement : 24m (16 cases), vol 45m (mauvais)\nMêlée : morsure +29 (2d6+6) et 2 griffes +27 (1d8+3) et 2 ailes +27 (1d6+3) et coup de queue +27 (1d8+9)\nEspace occupé/allonge : 3m/1,5m (3m avec morsure)\nAttaque de base/lutte : +22/+32\nOptions d\'attaque : Enchaînement, Attaque en vol, Attaque en puissance\nActions spéciales : Souffle\nSorts d\'ensorceleur connus : (NLS 7) :\n3e (5/jour) - $Clairaudience/clairvoyance$, héroïsme† 2e (7/jour) - endurance de l\'ours†, grâce féline†, $Détection de pensées$\n1er (8/jour) - $Repli expéditif$, $Armure de mage$†, $Protection contre le bien$, $Bouclier$, $Ventriloquie$\n0 (6/jour) - $Détection de la magie$, $Son imaginaire$, $Manipulation à distance$, $Message$, $Ouverture/fermeture$, $Lecture de la magie$, $Résistance$\n† déjà lancé\nCapacités de type sort (NLS 7e) :\n3/jour - $Image miroir$, antidétection†\n2/jour - $Porte dimensionnelle$\n1/jour - $Traversée des ombres$\n† déjà lancé\nCaractéristiques : Force 23, Dex 14, Con 23, Int 20, Sag 20, Cha 21\nParticularités : sens aiguisés, fusion avec les ombres\nDons : #Vigilance#, #Combat en aveugle#, #Enchaînement#, #Attaque en vol#, #Vol stationnaire#, #Science de l\'initiative#, #Attaques multiples#, #Attaque en puissance#\nCompétences : Concentration +33, Diplomatie +34, Dissimulation +25, Intimidation +32, Saut +33, Connaissances (mystères) +32, Perception auditive +34, Déplacement silencieux +29, Fouille +32, Psychologie +32, Détection +34\nSouffle (Ext). Une fois tous les 1d4 rounds, cône d\'ombre de 12m, quatre niveaux négatifs ; Réflexes DC 28 moitié\nPrésence effrayante (Ext) Rayon de 64m ; Volonté DD 26 annule. Grâce à ce pouvoir, les adversaires de la créature sont affectés par sa seule présence. L?effet se déclenche automatiquement quand la créature exécute une action pouvant impressionner. Tous les adversaires à portée et voyant la créature peuvent être effrayés ou secoués. Son effet dure souvent pendant 5d6 rounds. Ce pouvoir ne peut affecter que les adversaires ayant un nombre de niveaux ou de DV inférieur à celui de la créature. Tout adversaire réussissant son jet de Volonté est immunisé contre la présence terrifiante de la créature pendant 24 heures. Il s?agit d?un effet de terreur mental\nSens aiguisés (Ext). Un dragon de l\'ombre voit quatre fois mieux qu\'un humain dans l\'obscurité et deux fois mieux dans la lumière normale\nFusion avec les ombres (Sur). Dans toutes les conditions autres qu\'en pleine lumière du jour, un dragon de l\'ombre peut disparaître dans les ombres, ce qui lui confère une dissimulation totale. L\'éclairage artificiel, même un sort de lumière ou de flamme éternelle, ne neutralise pas cette capacité. Un sort de lumière du jour, en revanche, le fait', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2351);

-- 2352 — Golem de pierre avancé
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2352, 'Golem de pierre avancé', 3, NULL, 'PV : 129 (18 DV)\nRD : 10/adamantite\nN Créature artificielle de Grande taille\nInitiative : -1\nSens : vision dans le noir 18 m, vision nocture ; Perception auditive +0, Détection +0\nLangues : accepte les injonctions en elfique\nClasse d\'armure : 26, contact 8, pris au dépourvu 26\nImmunités : contre les dégâts de capacité, le drain de capacité, les coups critiques, les effets mortels, la mort par dégâts massifs, les maladies, l\'absorption d\'énergie, les sorts et capacités affectant l\'esprit, les effets de nécromancie, les dégâts non létaux, la paralysie, l\'empoisonnement, le sommeil, l\'étourdissement, tout effet nécessitant un jet de sauvegarde de Vigueur à moins qu\'il ne fonctionne également sur les objets ; immunité à la magie\nJets de sauvegarde : Vig +6, Réf +5, Vol +6\nFaiblesse : ne peut soigner ses dégâts, détruit à 0 PV ou moins\nVitesse de déplacement : 6m (4 cases)\nMêlée : 2 coups +21 (2d10+9)\nDistance : arc long composite +2 +13/+8/+3 (2d6+7/×3)\nEspace occupé/allonge : 3m/3m\nAttaque de base/lutte : +13/+26\nActions spéciales : lenteur\nCaractéristiques : For 29, Dex 9, Con -, Int -, Sag 11, Cha 1\nParticularités : créature artificielle, immunité contre la magie\nCompétences : #Maniement d\'une arme de guerre# (arc long)\nCompétences : Discrétion -5\nPossessions : arc long composite +2 (+5 bonus de For) avec 20 flèches\nImmunité contre la magie (Ext). Ce golem est immunisé contre tous les sorts et pouvoirs magiques affectés par la résistance à la magie. De plus, certains sorts et effets spécifiques affectent différemment la créature. Voici les sorts et leurs effets : Un sort de transmutation de la pierre en boue le ralentit (comme s?il subissait l?effet du sort lenteur) pendant 2d6 rounds, sans jet de sauvegarde, tandis que transmutation de la boue en pierre lui permet de récupérer tous les points de vie perdus. Sans modifier son organisme, transmutation de la pierre en chair annule sa réduction des dégâts et son immunité à la magie pendant 1 round entier\nLenteur (Sur). Le golem de pierre peut utiliser ce pouvoir, semblable au sort lenteur, tous les 2 rounds par une action libre. L?effet a une portée de 3 mètres et une durée de 7 rounds, il est annulé par un jet de Volonté réussi (DD 17). Le DD de sauvegarde est lié à la Constitution', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2352);

-- 2353 — Horreur guerrière
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2353, 'Horreur guerrière', 3, NULL, 'PV : 130 (20 DV)\nN Créature artificielle de taille moyenne\nInitiative : +6\nSens : vision dans le noir 18 m, vision dans la pénombre, détection de l\'invisibilité ; Perception auditive +20, Détection +21\nLangues : Elfe\nClasse d\'armure : 28, toucher 15, pris au dépourvu 26\nImmunités : contre les dégâts de capacité, le drain de capacité, les coups critiques, les effets mortels, la mort par dégâts massifs, les maladies, l\'absorption d\'énergie, les sorts et capacités affectant l\'esprit, les effets de nécromancie, les dégâts non mortels, la paralysie, l\'empoisonnement, le sommeil, l\'étourdissement, tout effet nécessitant un jet de sauvegarde de Vigueur sauf s\'il fonctionne également sur les objets ; immunités contre les sorts\nJets de sauvegarde : Vig +6, Réf +8, Vol +11\nFaiblesse : détruit à 0 PV ou moins\nVitesse de déplacement : 12m (8 cases), vol (marche dans les airs) 12m (bon)\nMêlée : épée à deux mains de maître +25/+20/+15 (2d6+12/17?20)\nDistance : arc long composite +2 +20/+15/+10 (1d8+10/´3)\nAttaque de base/lutte : +15/+23\nActions spéciales : puissance de l\'arme\nCapacités de type sort (NLS 7) :\nÀ volonté - $Projectile magique$\n3/jour - $Clignotement$\n1/jour - $Porte dimensionnelle$\nCaractéristiques : For 26, Dex 16, Con ?, Int 13, Sag 16, Cha 6\nParticularités créature artificielle, réparation rapide\nDons : #Enchainement#, #Vigueur surhumaine#, #Science du critique# (épée à deux mains), #Science de l\'initiative#, #Attaque en puissance#, #Robustesse#, #Arme de prédilection# (épée à deux mains)\nCompétences : Diplomatie +5, Perception auditive +20, Fouille +18, Psychologie +20, Détection +21, Survie +3 (+5 pour suivre des traces)\nPossessions : épée à deux mains de maître, arc long composite +2 (+8 bonus de Force) avec 20 flèches\nImmunité contre les sorts (Ext). Les horreurs guerrières sont immunisées contre les sorts projectile magique, boule de feu, éclair et désintégration\nPuissance de l\'arme. En tant qu\'action gratuite, une horreur guerrière peut imprégner son épée à deux mains de la capacité spéciale « tonnerre ». Il s\'agit d\'un pouvoir de la créature artificielle, et non de l\'arme\nRéparation rapide. Une horreur guerrière qui se repose pendant 1 heure entière récupère 1 point de vie, à condition qu\'il lui reste au moins 1 point de vie', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2353);

-- 2354 — Darcassan
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2354, 'Darcassan', 3, NULL, 'PV : 122 (15 DV)\nRD : 10/adamantine\nElfe solaire magicien(divin) 18 / expert 2 fusionné avec une tour\nCB construction artificielle de taille Très Grande\nInitiative : -5\nSens : vision dans le noir 18 m, vision nocturne ; Perception auditive +9, Détection +9\nLangues : chondathien, commun, géant, gnome, elfique, sylvestre ; télépathie 18m\nClasse d\'armure : -1, contact -7, pris au dépourvu -1\nImmunités : contre les dégâts de capacité, le drain de capacité, les coups critiques, les effets mortels, la mort par dégâts massifs, les maladies, l\'absorption d\'énergie, l\'épuisement, la fatigue, la magie, les sorts et capacités affectant l\'esprit (charmes, compulsions, fantasmes, schémas et effets sur le moral), les effets de nécromancie, les dégâts non létaux, la paralysie, l\'empoisonnement, les effets de sommeil, l\'étourdissement, tout effet nécessitant un jet de sauvegarde de Vigueur à moins qu\'il ne fonctionne également sur les objets\nJets de sauvegarde : Vig +5, Réf -, Vol +12\nFaiblesse : ne peut pas être soigné, détruit à 0 PV ou moins\nVitesse de déplacement : 0 m\nEspace occupé/allonge : 15 m/0 m\nAttaque de base : +10\nLutte : -\nSorts de magicien préparés : (NLS 18) : Aucun\nÉcole interdite : nécromancie\nCapacités de type sort (NLS 15) :\nÀ volonté - $clairaudience/clairvoyance$\nCaractéristiques : For -, Dex -, Con -, Int 17, Sag 12, Cha 13\nParticularités : créature artificielle, projection d\'ombre\nDons : #Vigilance#, Création d\'objets merveilleux, Forge d\'anneaux magiques, #Écriture de parchemins#, #Science de l\'initiative#, Talent accru (Bluff), Talent accru (Psychologie), #École renforcée# (illusion), #Efficacité des sorts accrue#\nCompétences : Bluff +8, Concentration +15, Artisanat (reliure) +7* , Artisanat (métallurgie) +7* , Artisanat (taille de pierre) +7* , Décryptage +15, Diplomatie +5, Discrétion ?8* , Connaissances (mystères) +16, Connaissances (histoire) +16, Perception auditive +9, Profession (scribe) +13, Psychologie +8, Art de la magie+17\n* Indique une compétence que Darcassan connaît, mais ne peut pas utiliser en tant que créature artificielle immobile\nLivre de sorts sorts préparés plus\n0 - tous sauf nécromancie\n1er - $Alarme$, $Esprit de l\'archer$, $Mains brûlantes$, $Charme-personne$, $Couleurs dansantes$, compréhension des langages, $Détection des passages secrets$, détection des morts-vivants, $Déguisement$, endurance aux énergies destructives, $Effacement$, $Repli expéditif$, $Feuille morte$, $Graisse$, $Hypnose$, $Identification$, armure du mage, missile magique, $Arme magique$, aura magique de Nystul, Aura indétectable de Nystul, $Brume de dissimulation$, $Protection contre le mal$, $Protection contre la loi$, Éclaboussure, $Bouclier$, Image silencieuse, $Coup au but$, $Serviteur invisible$, $Ventriloquie$\n2e niveau - $Modification d\'apparence$, $Bélier$, $Flou$, flamme continue, obscurité, $Lumière du jour$, $Détection de pensées$, $Sphère de feu$, $Poussière scintillante$, $Lueurs hypnotiques$, $Invisibilité$, $Déblocage$, $Piège de Léomund$, $Localisation d\'objet$, $Bouche magique$, $Flèche acide de Melf$, $Image imparfaite$, $Image miroir$, diversion, objet obscur, résistance à l\'énergie, tour de corde, $Brûlure$, vision de l\'invisible, jet d\'ombre, bris, invocation d\'essaim, $Fou rire de Tasha$, toile\n3e niveau - Analyse du portail, $Clignotement$, $Clairaudience/clairvoyance$, $Vision dans le noir$, $Dissipation de la magie$, $Boule de feu$, $Vol$, $Rapidité$, $Sphère d\'invisibilité$, $Affûtage$, éclair, $Cercle magique contre le mal$, $Cercle magique contre la Loi$, $Arme magique suprême$, image majeure, non-détection, protection contre l\'énergie, $Flèches inversées$, $Suggestion$, langues, $Mur de vent$\n4e niveau - $Oeil du mage$, contrecoup, $Confusion$, $Détection de la Scrutation$, $Porte dimensionnelle$, $Tentacules noirs d\'Evard$, $Bouclier de feu$, tempête de glace, $Mur illusoire$, $Invisibilité suprême$, $Localisation de créature$, sphère d\'isolement d\'Otiluke, $Assassin imaginaire$, scrutation, convocation d\'ombres, $Cri$, $Peau de pierre$, lance de tonnerre, $Mur de glace$\n5e niveau - $Main interposée de Bigby$, $Cône de froid$, $Contact avec les plans$, domination sur une personne, songe, débile, $Garde de fer mineur$, $Mirage$, Chien de garde de Mordenkainen, $Cauchemar$, $Image prédéterminée$, $Contrat intermédiaire$, $Oeil indiscret$, $Lien télépathique de Rary$, Envoi, $Convocation d\'ombres suprême$, $Matrice de sorts mineure$, $Télékinésie$, $Téléportation$, $Mur de force$, $Mur de pierre$\n6e niveau - $Tempête acide$, Analyse de sort, $Zone d\'antimagie$, $Main impérieuse de Bigby$, Dissipation supérieure, $Mythes et légendes$, $Remémoration de Mordenkainen$, $Image programmée$, Projection d\'image, $Champ de force$, Sceller le portail, Reflets d\'ombre, $Transformation de Tenser$, $Vision lucide$\n7e niveau - Poigne de Bigby, $Boule de feu à retardement$, $Forme éthérée$, scrutation suprême, $Souhait limité$, épée de Mordenkainen, ?il prismatique, rayons prismatiques, simulacre, $Renvoi des sorts$, vision\n---\nImmunité à la magie (Ext). Darcassan est immunisé contre tous les sorts ou capacités magiques qui permettent la résistance à la magie, à l\'exception des sorts qui ont le descripteur sonore et peuvent infliger des dégâts (tels que cri). Un sort qui a le descripteur lumière et qui est dirigé vers Darcassan répare 1d6 points de dégâts par niveau de sort\nProjection d\'ombre (Su). Darcassan peut créer jusqu\'à quatre duplicatas d\'ombre de son ancien moi. Ces projections peuvent être conservées à l\'intérieur de la matrice de son corps artificiel ou libérées pour agir comme des créatures indépendantes. Darcassan ne peut lancer des sorts que par l\'intermédiaire de ses projections d\'ombre. S\'il conserve une ou plusieurs projections dans son corps, Darcassan peut utiliser tous les sorts que ses projections d\'ombre ont préparés sur lui-même ou sur les sujets qu\'il peut toucher. Une seule projection d\'ombre peut être libérée à la fois pour fonctionner de manière indépendante. Une projection d\'ombre indépendante reste liée télépathiquement à Darcassan. Tout sort lancé par une projection provient de cette projection. Si une projection d\'ombre est détruite, Darcassan doit attendre 1d4 jours avant de pouvoir remplacer cette projection\nCompétences. Darcassan conserve ses modificateurs de compétences raciales d\'elfe en tant que créature artificielle (+2 aux tests de Perception auditive, de Fouille et de Détection)', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2354);

-- 2355 — Darcassan le Mage
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2355, 'Darcassan le Mage', 28, NULL, 'PV : 56 (20 DV)\nRD : 10/+3 (100 PV max, Renvoi des projectiles)\nElfe du soleil mâle magicien (devin) 18 / expert 2\nCB Humanoïde de taille moyenne\nInitiative : +9\nSens : vision nocturne ; Perception auditive +17, Détection +17\nLangues : chondathien, commun, elfique, géant, gnome, sylvestre ; télépathie 18m\nClasse d\'armure : 26 (28 avec Invisibilité suprême), contact 18 (20 avec Invisibilité suprême), pris au dépourvu 26 (28 avec Invisibilité suprême)\nChance d\'échapper à une attaque 50 % (existence fantomatique)\nImmunités : aux effets de sommeil magiques\nJets de sauvegarde : Vig +6, Réf +12, Vol +12 ; +14 contre les enchantements\nVitesse de déplacement : 9 m (6 cases), vol 9 m (parfait)\nMêlée : bâton +2 +11/+6 (1d8+4)\nDistance : -\nAttaque de base/lutte : +9/+9\nÉquipement de combat : &baton de surpuissance&\nSorts de magicien préparés : (NLS 18 ; 1d20+20 pour surmonter la RM)\n9e - (2+1) $Arrêt du temps$, $Main broyeuse de Bigby$, $Prémonition$\n8e - (3+1) Poing de Bigby, $Protection contre les sorts$, Anneau de foudre, $Moment de prescience$\n7e - (3+1) $œil prismatique$ (+6 au toucher à distance, DD 19), $Poigne de Bigby$, $Renvoi des sorts$,$Scrutation suprême$\n6e - (5+1) $Tempête acide$ (DD 22), $Zone d\'antimagie$, $Dissipation suprême$, $Flèche acide de Melf$ (2) (accélérée, +12 au toucher à distance), $Vision lucide$†\n5e - (5+1) $Main interposée de Bigby$, $Domination$ (DD 21), $Débilité$ (DD 21), $Matrice de sorts mineure$† (), $Télékinésie$ (+12 au toucher à distance, DD 21), $Lien télépathique de Rary$\n4e - (5+1) $Tentacules noirs d\'Evard$, $Invisibilité suprême$† (2), $Ecran de dissipation d’Otiluke$, $poussière d\'ombres$ (accru) (DD 21), $Cri$ (DD 20), $Lance Tonnerre$ (+13/+5 en mêlée)\n3e - (5+1) $Rapidité$, Eclair (2) (DD 19), $Arme magique suprême$ (2)†† , $Antidétection$ (jet de niveau du lanceur de sorts DD 28), $Renvoi des projectiles$†\n2e - (6+1) $Bélier$, $Lumière du jour$†, $Flèche acide de Melf$ (+12 en contact à distance), Brûlure (2)(DD 17), $Détection de l\'invisiblilité$, $Détection de pensées$ (DD 17)\n1er - (6+1) $Alarme$, $Projectile magique$ (4), $Bouclier$, $Esprit de l\'archer$\n0 - $Détection de la magie$, $Son imaginaire$ (DD 15), $Manipulation à distance$,$Fatigue$\n† déjà lancé\nÉcole interdite nécromancie\nCapacités magiques : (niveau d\'enchantement 20) :\nÀ volonté - $Clairaudience/clairvoyance$\nCaractéristiques : For 10, Dex 20, Con 11, Int 28, Sag 12, Cha 13\nDons : #Vigilance#, Augmentation d\'intensité, #Science de l\'initiative#, #Incantation rapide#, Écriture de parchemin, #Talent# (Bluff), #Attaque spéciale renforcée# (Psychologie), #École renforcée# (illusion), #Efficacité des sorts accrue#,#Magie de guerre#\nCompétences : Bluff +8, Concentration +20 (+24 pour lancer des sorts), Artisanat (reliure) +10, Artisanat (métallurgie) +10, Artisanat (taille de pierre) +10, Décryptage +25, Diplomatie +5, Discrétion +14, Connaissances (mystères) +29, Connaissances (histoire) +25, Perception auditive +21, Profession (scribe) +13, Fouille +14, Psychologie +10, Art de la magie+20, Détection +17\nPossessions : équipement de combat plus &amulette d\'armure naturelle& +3, &bracelets d\'armure& +5, &anneau de protection& +3, gants de dextérité +2, bandeau d\'intelligence +2\nExistence dans l\'ombre (Sur). Le mage Darcassan est à la fois semi-matériel et partiellement réel. Il peut traverser les objets physiques (mais pas les effets de force) tout comme une créature intangible. Toutes les attaques, même les sorts (à l\'exception des effets de force), ont 50 % de chances d\'échouer. Une arme spectral annule cette chance d\'échec. Une créature qui interagit avec lui peut tenter un jet de sauvegarde de Volonté DD 24 pour ne pas croire à la projection. Si elle y parvient, les attaques physiques de la projection (mais pas les sorts) n\'infligent que 80 % de leurs dégâts normaux. Vous pouvez calculer les dégâts réduits ou utiliser les valeurs suivantes : épée longue 1d8+2, arc long 1d6+2, attaque à mains nues 1d3–1. Dans une zone d\'antimagie, Darcassan perd sa vitesse de vol, sa capacité à traverser les objets solides, son bonus de déviation à la classe d\'armure et sa chance d\'échec. Il perd également son bonus racial de +8 aux tests de Perception auditive, de Fouille, de Détection et de Discrétion (voir ci-dessous).\nCompétences. Darcassan bénéficie d\'un bonus racial de +8 aux tests de Perception auditive, Fouille, Détection et Discrétion grâce à sa nature semi-matérielle. En tant qu\'elfe, il bénéficie d\'un bonus de +2 aux tests de Perception auditive, Fouille et Détection', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2355);

-- 2356 — Légion-en-peine supérieure
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2356, 'Légion-en-peine supérieure', 1, NULL, 'PV : 295 (35 DV)\nCM mort-vivant (immatériel) de grande taille\nInitiative : +6\nSens : vision dans le noir 18 m ; Écouter +39, Repérer +39\nAura : aura surnaturelle 27 mètres\nClasse d\'armure : 27, toucher 27, pris au dépourvu 25 ; Esquive, Mobilité\nImmunités : immunités des morts-vivants ; ne peut être blessé que par d\'autres créatures incorporelles, des armes magiques, des sorts, des capacités semblables à des sorts ou des capacités surnaturelles\nRésistances : 50 % de chances d\'ignorer tout dégât provenant d\'une source corporelle (à l\'exception des effets de force et des attaques effectuées avec des armes fantomatiques)\nJets de sauvegarde : Vig +10, Réf +12, Vol +21\nVitesse de déplacement : vol 18 m (12 cases) (parfait) ; peut traverser des objets solides (mais pas les effets de force) à volonté, se déplace silencieusement (ne peut être entendu avec des tests d\'écoute sauf s\'il le souhaite)\nMêlée : 2 touchers incorporels +19 chacune (1d8+1/19-20 plus 1d6 de drain de Constitution)\nDistance : rayon d\'affaiblissement +16 (1d4 niveaux négatifs/19-20)\nEspace occupé/allonge : 4,5 m/3 m\nAttaque de base : +15\nLutte : -\nOptions d\'attaque : #Combat en aveugle#, #Attaques réflexes#, #Attaque éclair#, Drain de Constitution (Fort NLS 32), Assimiler, Créer une progéniture, Rayon d\'affaiblissement\nCapacités de type sort (NLS 20) :\nÀ volonté - $Imprécation$ (NLS 18), $malédiction$ (NLS 20), $anathème$ (NLS 18), $terreur$ (NLS 21)\n3/jour - $Cercle de mort$ (NLS 23), $blessure légère de groupe$ (NLS 22)\n1/jour - $Destruction$ (NLS 24)\nCaractéristiques : For -, Dex 14, Con -, Int 18, Sag 18, Cha 25\nParticularités : traits incorporels, traits de mort-vivant\nDons : #Vigilance#, #Combat en aveugle#, #Attaques réflexes#, #Esquive#, #Science du Critique# (toucher incorporel), #Science du Critique# (rayon d\'énergie négative), #Science de l\'initiative#, #Souplesse du serpent#, #Attaque éclair#, #Spécialisation martiale# (toucher incorporel), #Spécialisation martiale#(rayon d\'énergie négative)\nCompétences : Concentration +40, Diplomatie +9, Discrétion +27, Intimidation +40, Connaissance (arcane) +15, Connaissance (donjon) +15, Connaissance (religion) +15, Perception auditive +39, Fouille +37, Psychologie +37, Détection +39\nAssimilation (Sur). Si une légion-en-peine tue une âme-en-peine, même l\'un de ses propres rejetons, elle assimile son énergie, devenant ainsi plus puissante. Elle ajoute les dés de vie de l\'âme-en-peine (normalement 5) aux siens, jusqu\'à un maximum de 60 DV. Elle gagne tous les bénéfices allant de pair avec les dés de vie additionnels selon les règles d\'évolution données dans le Manuel des Monstres. Quand une légion-en-peine arrive à 60 DV, elle se scinde en deux légions-cn-peine de 30 DV chacune.\nDiminution permanente de Constitution (Sur). Toute créature vivante touchée par le contact intangible d\'une légion-en-peine doit réussir un jet de Vigueur (DD 32) ou bien subir une diminution permanente de 1d6 points de Constitution.\nPouvoirs magiques : anathème, imprécation, malédiction, terreur à volonté ; cercle de douleur et cercle de mort 3 fois par jour ; destruction 1 fois par jour. Niveau de lanceur de sorts 20, jets de sauvegarde DD 17 + niveau du sort).\nRayon d\'énergie négative (Sur). Une légion-en-peine peut attaquer avec un éclair d\'énergie négative qui agit comme le sort énergie négative. C\'est une attaque de type rayon dont la portée maximale est de 18 mètres (pas de facteur de portée). Une créature frappée par le rayon acquiert 1d4 niveaux négatifs.\nAura de mort (Sur). Animaux sauvages et domestiques sentent l\'approche d\'une légion-en-peine à 27 mètres de distance. Ils refusent d\'approcher davantage du mort-vivant et paniquent si on les oblige à le faire. Cet état de panique dure tant qu\'ils se trouvent à moins de 27 mètres de la légion en peine.\nCréation de rejetons (Sur). Tout humanoïde tué par une légion-en-peine revient à la vie sous forme d’âme-en-peine 1d4 rounds après sa mort Les rejetons obéissent à la légion-en-peine qui les a créés et restent leurs esclaves jusqu\'à la destruction de celle-ci. La nouvelle âme-en-peine ne possède aucun des pouvoirs qu\'elle avait de son vivant.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2356);

-- 2357 — L'incantateur sans visage
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2357, 'L\'incantateur sans visage', 25, NULL, 'PV : 36 (+10 dans les ténèbres ou les ombres) (10 DV) ; guérison rapide 2\nReflet male simulacre mage 5 / adapte des ombres 5\nNM Exterieur de taille moyenne\nInitiative : +7\nSens : vision dans le noir 36m, vision nocturne ; Perception auditive +2 (+6 dans l\'obscurité), Détection +2 (+6 dans l\'obscurité ou les ombres)\nLangues : Commun, Draconique, Gobelin, Infernal, Néthésien, Thoross\nClasse d\'armure : 16, contact 13, pris au dépourvu 13 (20, contact 17, pris au dépourvu 17 dans les ténèbres ou les ombres)\nRM : 21\nJets de sauvegarde : Vig +4, Réf +8, Vol +11 ; +4 dans les ténèbres ; +1 contre les enchantements, les illusions, la nécromancie et les sorts ayant le descripteur ténèbres\nFaiblesse : perd les capacités d\'ombre (vision sombre, vitesse accrue, foulée de l\'ombre, guérison rapide, contrôle de la lumière, invisibilité, image de l\'ombre) lorsqu\'il n\'est pas dans l\'obscurité ou les ombres\nVitesse de déplacement : 9m (6 cases), 15m (10 cases) dans l\'obscurité ou les ombres ; marche de l\'ombre\nMêlée : bâton de maître +5 (+7 dans les ténèbres) (1d6 [1d6+2 dans les ténèbres])\nAttaque de base/lutte : +4/+4\nOptions d\'attaque : lancer de combat, magie insidieuse, magie pernicieuse, sort silencieux, magie tenace\nActions spéciales : contrôle de la lumière, bouclier des ombres, familier (aucun pour le moment)\nÉquipement de combat : Bâton de la nuit (17 charges)\nSorts de mage préparés (NLS 10) :\n5ème - $Brume mortelle$ (DD 20), $Débilité$* (DD 21), $Manoir somptueux de Mordenkainen$†\n4ème - $Malédiction$* (DD 20), $invisibilité suprême$* , tempête de glace (NLS 9), améliorateur mnémonique de Rary (NLS 9)\n3ème - $Déplacement$* , $Vol$ (NLS 9), $Suggestion$* (DD 19), $baiser du vampire$* (+4 toucher en mêlée)\n2ème - $Feuille morte$ (NLS 9ème), $ruse du renard$ (NLS 9ème), $baiser de la goule$* (+4 toucher en mêlée, DD 18), $Main spectrale$* , $fou rire de Tasha$* (DD 18)\n1er - $contact glacial$ * (+4 toucher en mêlée), $Compréhension des langues$, $Identification$, $Protection contre le bien$, emprise choquante (NLS 9, (NLS 9ème, +4 toucher en mêlée), true strike\n0 - $Détection de la magie$, perturbation des morts-vivants* (+7 toucher à distance), main de mage* , $Lecture de la magie$\n† déjà lancé\n* +1 au DD de sauvegarde et au niveau de lanceur de sorts pour la résistance aux sorts\nCapacités de type aux sorts (NLS 10) :\n1/round - $invisibilité$* (dans les ténèbres ou les ombres uniquement)\n3/jour - image d\'ombre * ($image miroir$, 1d4+3 images, dans les ténèbres ou les ombres uniquement)\n* +1 au DD de sauvegarde et au niveau de lanceur de sorts pour la résistance aux sorts\nCaractéristiques For 10, Dex 16, Con 13 (15 dans les ténèbres ou les ombres), Int 21, Sag 14, Cha 14 (16 dans les ténèbres ou les ombres)\nParticularités : traits d\'extérieur\nDons : #Magie de guerre#, #Science de l\'initiative#, #Réflexes surhumains#, #Magie pernicieuse#, #Magie insidieuse#, écriture de Parchemins, #Magie de la Toile d\'ombre#, #Incantation silencieuse#, #Magie tenace#\nCompétences : +5 (+7 alchimie, sculpture sur bois), Bluff +7 (+8 dans l\'obscurité), Concentration +14 (+15 dans l\'obscurité), Artisanat (alchimie) +13, Artisanat (sculpture sur bois) +13, Diplomatie +4 (+5 dans l\'obscurité), Déguisement +7 (+8 dans l\'obscurité/+9 en action/+10 en action dans l\'obscurité), Dissimulation +16, Intimidation +4 (+5 dans les ténèbres), Connaissance (arcanes) +13, Connaissance (histoire) +13, Connaissance (des plans) +13, Perception auditive +2 (+6 dans les ténèbres), Déplacement silencieux +11, Magie +20, Détection +2 (+6 dans les ténèbres), Survie +2 (+4 autres plans)\nPossessions : équipement de combat plus gants de dextérité +2, bottes de vitesse, amulette d\'armure naturelle +3, cape de résistance +1. Note : toutes les possessions de l\'Incantateur sans visage sont des objets magiques de la Toile d\'Ombre\nLivre de sorts : tout ce qui précède plus 0 rayon degivre, toucher de fatigue; 1er :peur, armure de mage, arme magique, monture, sommeil, serviteur invisible; 2e : flou, hébétement, détection des pensées, poussière scintillante, résistance à l\'énergie; 3e :minuscule hutte de Leomund, langues; 4e : scrutation, conjuration de l\'ombre; 5e: éclaircie\nMarche de l\'ombre (Spe). Lorsqu\'il est dans les ténèbres ou les ombres, l\'Incantateur sans visage peut disparaître de son emplacement actuel et réapparaître dans n\'importe quelle zone d\'ombre dans un rayon de 90 m, jusqu\'à une fois tous les 2 rounds, comme action de mouvement\nContrôle de la lumière (Spe). Lorsqu\'il se trouve dans une zone d\'ombre, l\'Incantateur sans visage peut réduire le niveau de lumière dans un rayon de 30m d\'un facteur allant jusqu\'à 100%. Cet effet diminue d\'autant la portée de vision des personnages et des créatures dépendant de la lumière. Un personnage situé dans la zone affectée gagne un bonus de +1 aux tests de Dissimulation pour chaque diminution de 25% de la lumière\nBouclier d\'ombres (Sur). L\'Incantateur sans visage peut s\'entourer d\'un globe de force noire et pourpre lors d\'une action standard. Ce bouclier fonctionne comme un sort de bouclier , accordant un bonus de bouclier de +4 à la CA et absorbant les projectiles magiques qui lui sont lancés. De plus, il permet de se dissimuler contre les attaques en mêlée et à distance. Il peut l\'utiliser jusqu\'à 5 rounds par jour, mais ces périodes ne sont pas nécessairement consécutives', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2357);

-- 2358 — Guerrier krinth
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2358, 'Guerrier krinth', 28, NULL, 'PV : 58 chacun (9 DV)\nKrinth mâle guerrier 9\nCM Humanoïde de taille moyenne (extraplanaire)\nInitiative : +5\nSens : vision dans le noir 18m ; Perception auditive +3, Détection +3\nLangues : Commun, Néthésien\nClasse d\'armure : 13, contact 11, pris au dépourvu 12 ; Esquive\nImmunités : à la condition Secoué\nJets de sauvegarde : Vig +9, Réf +5, Vol +4 ; +1 contre les sorts et effets ayant le descripteur ombre, +4 contre la peur\nVitesse de déplacement : 9 (6 casmes)\nMêlée : ranseur +2 de foudre +15/+10 (2d4+7 19-20/x3 plus 1d6 électricité) ou\nMêlée : dague de maître +12/+7 (1d4+2/×3)\nAttaque de base/lutte : +9/+11\nÉquipement de combat : potion de flou\nCaractéristiques : For 16, Dex 12, Con 14, Int 9,Sag 10, Cha 6\nDons : #Vigilance#, #Esquive#, Sciences de l\'initiative, #Arme de prédilection# (ranseur), #Spécialisation martiale# (ranseur), #Attaque en rotation#, #Science du critique# (ranseur)\nCompétences : Dissimulation +4 (+6 dans l\'ombre), Saut +10, Écoute +3, Repérage +3\nPossessions : équipement de combat plus harnais d\'armure +2 (comme les bracelets mais dans l\'emplacement du torse), ranseur +2 de foudre, dague de poing de maître', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2358);

-- 2381 — Hzerou
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2381, 'Hzerou', 25, NULL, 'Extérieur [Chaos, Extraplanaire, Mal, Tanar\'ri] de taille G\nDés de vie : 10d8+93 (138 pv)\nInitiative : +0\nVitesse de déplacement : 9 m (6 cases)\nClasse d\'armure : 23 (–1 taille, +14 naturelle), contact 9, pris au dépourvu 23\nAttaque de base/lutte : +10/+19\nAttaque : morsure (+14 corps à corps, 4d4+5)\nAttaque à outrance : morsure (+14 corps à corps, 4d4+5), 2 griffes (+9 corps à corps, 1d8+2)\nEspace occupé/allonge : 3 m/3 m\nAttaques spéciales : convocation de démons, étreinte, pouvoirs magiques, puanteur\nParticularités : immunité contre l\'électricité et le poison, réduction des dégâts (10/Bien), résistance à l\'acide (10, résistance au feu (10), résistance au froid (10), résistance à la magie (19), télépathie (30 m), vision dans le noir (18 m)\nJets de sauvegarde : Réf +7, Vig +16, Vol +9\nCaractéristiques : For 21, Dex 10, Con 29, Int 14, Sag 14, Cha 18\nCompétences : Art de la magie +15, Concentration+22, Déplacement silencieux+12, Détection+23, Discrétion+13, Escalade+18, Évasion+13, Fouille+15, Intimidation+17, Maîtrise des cordes+0 (+2 pour ligoter), Perception auditive+23, Survie+2 (+4 pour suivre des traces)\nDons : Attaque en puissance, Combat en aveugle, Enchaînement, Robustesse\nEnvironnement : Strates Infinies de l\'Abysse\nOrganisation sociale : solitaire ou groupe (2–4)\nFacteur de puissance : 11\nTrésor : normal\nAlignement : toujours chaotique mauvais\nÉvolution possible : 11–15 DV (taille G), 16–30 DV (taille TG)\nAjustement de niveau : +9\n***\nCette créature est un crapaud trapu vaguement humanoïde. Elle a des bras à la place des membres antérieurs. Sa large gueule aux machoires puissantes est garnies de nombreuses dents plates, et une rangée de pointes courent le long de sa colonne vertébrale\nLe hezrou occupe le poste de sergent dans les armées démoniaques ; c\'est lui qui relaye les ordres des officiers à la piétaille. Il ne bénéfice pas des instincts pour les complots qui sont la marque des démons plus puissants, mais il est néanmoins retors au combat.\nIl se déplace indifféremment à deux ou quatre pattes, mais combat toujours dressé sur ses pattes arrière.\nLe hezrou fait un peu plus de 2 mètres de haut et pèse environ 375 kg.\nLe hezrou aime encore plus se battre au corps à corps que le vrock. Il se jette sans attendre au contact de l\'ennemi, afin que la puanteur qui l\'environne puisse lui conférer l\'avantage le plus rapidement possible. Il commence habituellement une bataille par un blasphème, puis irrégulièrement d\'un marteau du Chaos ou d\'un ténèbres maudites, selon l\'alignement de ses ennemis.\nLes armes naturelles du hezrou, ainsi que les armes manufacturées qu\'il pourrait utiliser, sont considérées comme étant d\'alignement chaotique et mauvais pour ce qui est d\'ignorer la réduction des dégâts.\n***\nConvocation de démons (Mag). Une fois par jour, il peut tenter d\'appeler 4d10 dretchs ou 1 autre hezrou (35% de chances de succès). Ce pouvoir est équivalent à un sort du 4e niveau.\nÉtreinte (Ext). Pour utiliser ce pouvoir, le hezrou doit réussir ses deux attaques de griffe sur le même adversaire. Il peut alors tenter d\'engager une lutte par une action libre sans provoquer d\'attaque d\'opportunité.\nPouvoirs magiques. Marteau du Chaos (DD 18), téléportation suprême (uniquement lui-même et 25 kg d\'objets) et ténèbres maudites (DD 18) à volonté ; blasphème (DD 21) et état gazeux 3 fois par jour. Niveau 13 de lanceur de sorts. Les DD de sauvegarde sont liés au Charisme.\nPuanteur (Ext). Chaque fois qu\'il se trouve en situation de combat, la peau du hezrou sécrète un liquide toxique à l\'odeur nauséabonde. Toutes les créatures situées dans un rayon de 3 mètres (démons exceptés) doivent réussir un jet de Vigueur (DD 24) sous peine d\'être prises de nausée tant qu\'elles se trouvent dans la zone affectée et pendant 1d4 rounds après qu\'elles en sont sorties. Quiconque réussit son jet de sauvegarde est tout de même fiévreux tant qu\'il se trouve dans la zone d\'effet, mais la puanteur de ce hezrou ne peut plus l\'affecter pendant une journée entière. Les sorts ralentissement du poison et neutralisation du poison annulent les effets de cette odeur. Les créatures immunisées contre les effets du poison ne sont pas affectées par la puanteur et les bonus aux sauvegardes contre le poison s\'appliquent contre la puanteur. Le DD de sauvegarde est lié à la Constitution.\nCompétences. Cette créature bénéficie d\'un bonus racial de +8 aux tests de Détection et de Perception auditive.', '11', 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2381);

-- 2382 — Glabrezu
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2382, 'Glabrezu', 25, NULL, 'Extérieur [Chaos, Extraplanaire, Mal, Tanar\'ri] de taille TG\nDés de vie : 12d8+120 (174 pv)\nInitiative : +0\nVitesse de déplacement : 12 m (8 cases)\nClasse d\'armure : 27 (–2 taille, +19 naturelle), contact 8, pris au dépourvu 27\nAttaque de base/lutte : +12/+30\nAttaque : pince (+20 corps à corps, 2d8+10)\nAttaque à outrance : 2 pinces (+20 corps à corps, 2d8+10), 2 griffes (+18 corps à corps, 1d6+5), morsure (+18 corps à corps, 1d8+5)\nEspace occupé/allonge : 4,50 m/4,50 m\nAttaques spéciales : convocation de démons, étreinte, pouvoirs magiques\nParticularités : immunité contre l\'électricité et le poison, réduction des dégâts (10/Bien), résistance à l\'acide (10), résistance au feu (10), résistance au froid (10), résistance à la magie (21), télépathie (30 m), vision dans le noir (18 m), vision lucide\nJets de sauvegarde : Réf +8, Vig +18, Vol +11\nCaractéristiques : For 31, Dex 10, Con 31, Int 16, Sag 16, Cha 20\nCompétences : Art de la magie +18, Bluff+22, Concentration+25, Connaissances (deux au choix) +18, Déguisement+5 (+7 pour tenir un rôle), Déplacement silencieux+18, Détection+26, Diplomatie+9, Discrétion+2, Fouille+18, Intimidation+24, Perception auditive+26, Psychologie+18, Survie+3 (+5 pour suivre des traces)\nDons : Attaque en puissance, Attaques multiples, Enchaînement, Persuasion, Succession d\'enchaînements\nEnvironnement : Strates Infinies de l\'Abysse\nOrganisation sociale : solitaire ou groupe mixte (1 glabrezu, 1 succube et 2–5 vrocks)\nFacteur de puissance : 13\nTrésor : pièces normales, bien précieux normaux (x2), objets normaux\nAlignement : toujours chaotique mauvais\nÉvolution possible : 13–18 DV (taille TG), 19–36 DV (taille Gig)\nAjustement de niveau : —\n***\nTout comme le succube, le glabrezu a comme mission de tenter les mortels afin de les inciter à se damner, mais lui préfère leur offrir le pouvoir plutôt que la passion charnelle.\nLe glabrezu a des yeux violets qui percent l\'âme et la couleur sa peau varie du rouge sombre au noir de jais. Un glabrezu mesure 4,50 mètres de haut et pèse environ 2,75 tonnes.\nLe glabrezu préfère user de subterfuges plutôt que de combattre de face. Mais si la ruse ne suffit pas à fourvoyer l\'adversaire, il sait faire preuve d\'une grande violence. Il entame par une confusion, poursuit par des attaques de corps à corps et espère achever par un marteau du Chaos ou un ténèbres maudite.\nLes armes naturelles du glabrezu, ainsi que les armes manufacturées qu\'il pourrait utiliser, sont considérées comme étant d\'alignement chaotique et mauvais pour ce qui est d\'ignorer la réduction des dégâts.\n***\nÉtreinte (Ext). Pour utiliser ce pouvoir, le glabrezu doit réussir une attaque de pince sur une créature de taille M ou moins. Il peut alors tenter d\'engager une lutte par une action libre sans provoquer d\'attaque d\'opportunité.\nPouvoirs magiques. Confusion (DD 19), dissipation de la magie, image miroir, inversion de la gravité (DD 22), marteau du Chaos (DD 19), téléportation suprême (uniquement lui-même et 25 kg d\'objets) et ténèbres maudites (DD 19) à volonté ; mot de pouvoir étourdissant 1 fois par jour. Niveau 14 de lanceur de sorts. Les DD de sauvegarde sont liés au Charisme.\nUne fois par mois, un glabrezu peut accorder un souhait à un humanoïde mortel. Le démon utilise ce pouvoir pour offrir de satisfaire les désirs de sa proie, mais à moins que le souhait ne consiste à amener la misère et la souffrance sur le monde, le glabrezu exigera en paiement un acte profondément malveillant ou un sacrifice d\'importance.\nVision lucide (Sur). Le glabrezu bénéficie en permanence des effets du sort vision lucide (niveau 12 de lanceur de sorts).\nCompétences. Le glabrezu bénéficie d\'un bonus racial de +8 aux tests de Détection et de Perception auditive.', '13', 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2382);

-- 2383 — Dretch
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2383, 'Dretch', 25, NULL, 'Extérieur [Chaos, Extraplanaire, Mal, Tanar\'ri] de taille P\nDés de vie : 2d8+4 (13 pv)\nInitiative : +0\nVitesse de déplacement : 6 m (4 cases)\nClasse d\'armure : 16 (+1 taille, +5 naturelle), contact 11, pris au dépourvu 16\nAttaque de base/lutte : +2/–1\nAttaque : griffes (+4 corps à corps, 1d6+1)\nAttaque à outrance : 2 griffes (+4 corps à corps, 1d6+1), morsure (+2 corps à corps, 1d4)\nEspace occupé/allonge : 1,50 m/1,50 m\nAttaques spéciales : convocation de démons, pouvoirs magiques\nParticularités : immunité contre l\'électricité et le poison, réduction des dégâts (5/fer froid ou Bien), résistance à l\'acide (10), réssitance au feu (10), résistance au froid (10), télépathie (30 m), vision dans le noir (18 m)\nJets de sauvegarde : Réf +3, Vig +5, Vol +3\nCaractéristiques : For 12, Dex 10, Con 14, Int 5, Sag 11, Cha 11\nCompétences : Déplacement silencieux+5, Détection+5, Discrétion+9, Fouille+2, Perception auditive+5, Survie+0 (+2 pour suivre des traces)\nDons : #Attaques multiples#\nEnvironnement : Strates Infinies de l\'Abysse\nOrganisation sociale : solitaire, paire, groupe (2–4), bande (6–15) ou nuée (10–40)\nFacteur de puissance : 2\nTrésor : aucun\nAlignement : toujours chaotique mauvais\nÉvolution possible : 3–6 DV (taille P)\nAjustement de niveau : +2\n***\nLe corps de cette créature vaguement humanoïde est gros, presque dénué de pilosité et sa peau est maladivement blanchâtre. Sa petite bouche aux lèvres pendantes est garnie de dents pointues\nLes dretchs sont des créatures pathétiques, mais intrinsèquement malfaisantes, qui passent leur temps à errer en groupe innombrables, quand ils ne sont pas enrôlés de force dans les armées de leur maître tanar\'ri.\nIl fait environ 1,20 mètre de haut et pèse 30 kg.\nLe dretch est incapable de parler, mais il peut communiquer par télépathie.\nLes dretchs sont des combattants lents et stupides, ce qui les rend peu redoutables. En combat singulier, ils comptent sur leur réduction des dégâts pour rester en vie. En groupe, leur nombre, souvent très important, constitue leur seule force et ils appellent aussitôt d\'autres dretchs au moindre signe de combat. Ils s\'enfuient si l\'ennemi leur paraît trop dangereux, sauf si d\'autres démons plus puissants sont là pour les obliger à combattre. Les dretchs redoutent encore plus les autres démons que la mort.\nLes armes naturelles du dretch, ainsi que les armes manufacturées qu\'il pourrait utiliser, sont considérées comme étant d\'alignement chaotique et mauvais pour ce qui est d\'ignorer la réduction des dégâts.\n***\nConvocation de démons (Mag). Une fois par jour, un dretch peut tenter d\'en appeler un autre (35% de chances de succès). Ce pouvoir est équivalent à un sort du 1e niveau.\nPouvoirs magiques. Effroi (DD 12) et nuage nauséabond (DD 13) 1 fois par jour. Niveau 2 de lanceur de sorts. Les DD de sauvegarde sont liés au Charisme.\nTélépathie (Sur). Le dretch peut communiquer mentalement avec toute créature parlant l\'abyssal dans un rayon de 30 mètres.', '2', 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2383);

-- 2403 — Sysalok
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2403, 'Sysalok', 29, NULL, 'hp 131 (15 DV)\nAbomination yuan-ti male guerrier psychique 6\nCM Humanoïde monstrueux de Grande taille\nInitiative : +7\nSens : vision dans le noir 18m, détection du poison, odorat ; Perception auditive +23, Détection +16\nLangues : Abyssal, commun, draconique, yuan-ti\nClasse d\'armure : 37, toucher 12, pris au dépourvu 34 ; Esquive, Souplesse du serpent\nRM 18\nVig +14, Réf +13, Vol +13\nVitesse de déplacement : 6m (4 cases), escalade 4,5m, natation 4,5m ; emport\nMêlée : +4 cimeterre +24/+19/+14 (1d8+13/18–20) et morsure +20 (2d6+7 plus empoisonnement)\nDistance : arc long composite +4 +20/+15/+10 (2d6+9/´3)\nEspace : 3m ; Portée 3m.\nAttaque : de base +13 ; Lutte +21\nOptions d\'attaque : Combat en aveugle, Expertise du combat ; empoisonnement (DD 17, 1d6 Con/1d6 Con)\nActions spéciales : constriction 1d6+6, saisie améliorée, production d\'acide\nPouvoirs de guerrier psychique (ML 6e) : Points de puissance/jour : 11 ;\n2e - équilibre corporel, hustle, prouesse\n1er - explosion, écran de force, arme métaphysique\nCaractéristiques : psi-like (ML 15e) :\nÀ volonté — aversion (DD 22), caméléon, hébétement psionique (DD 18), détection d\'intention hostile, ectoplasme enchevêtrant, expiration du dragon noir\n3/jour -purification du corps, charme psionique (DD 22), dissimulation amorphe, ténèbres profondes, poussée mentale(DD 18), suggestion psionique(DD 19)\n1/jour - métamorphose funeste (DD 22)\nCaractéristiques : Force 24, Dex 16,\nDons : #Vigilance#, #Combat en aveugle#, #Essence physique#, #Expertise du combat#, #Manifestation de combat#, #Vigueur surhumaine#, #Science de l\'initiative#, #Réflexes surhumains#, #Souplesse du serpent#, #Spécialisation martiale# (cimeterre)\nCompétences : Équilibre +19, Escalade +13, Concentration +22, Discrétion +8*, Saut +17, Connaissances (histoire) +21, Connaissances (Anauroch local) +21, Perception auditive +23, Détection +16, Stabilisation +22\n* Lorsqu\'il utilise sa capacité de caméléon, Sysalok bénéficie d\'un bonus de circonstance de +10 aux tests de discrétion.\nPossessions : Cimeterre +4, arc long composite +4 (+5 bonus de Force) avec 20 flèches, bouclier lourd +4, cuirasse de rapidité +4\n***\nEmport. En tant qu\'action standard utilisable deux fois par jour, le bouclier d\'emport de Sysalok le transporte, lui et son équipement, à n\'importe quelle détection située à moins de 240m qu\'il peut visualiser ou spécifier, comme le pouvoir psionique porte dimensionnelle.\nIngestion corporelle. Son arme d\'Ingestion corporelle confère à Sysalok des points de vie temporaires égaux au total des dégâts infligés par un coup critique réussi. Ces points de vie temporaires durent 10 minutes. Ainsi, si Sysalok réussit un coup critique alors qu\'il bénéficie encore de points de vie temporaires provenant d\'un coup critique précédent, il ne gagne que la meilleure des deux valeurs : soit son nombre actuel de points de vie temporaires, soit le nouvel afflux de points de vie temporaires, selon la valeur la plus élevée.\nEssence physique. Sysalok peut récupérer 2 points de puissance en subissant 1 point de dégâts à chacune de ses caractéristiques Force, Dextérité et Constitution. Il peut récupérer des points de puissance supplémentaires pour un coût proportionnel ; par exemple, il peut choisir de récupérer 6 points de puissance en subissant 3 points de dégâts à ses caractéristiques Force, Dextérité et Constitution.\nAversion (Ps). Une abomination yuan-ti peut créer par voie psionique un effet de contrainte ciblant une créature située à moins de 9 mètres. La cible doit réussir un jet de sauvegarde de Volonté DD 22 ou développer une aversion pour les serpents pendant 10 minutes. Les créatures affectées doivent rester à au moins 6 mètres de tout serpent ou yuan-ti, vivant ou mort ; si elles se trouvent déjà à moins de 6 mètres, elles s\'éloignent. Une créature incapable de s\'éloigner, ou attaquée par des serpents ou des yuan-ti, est submergée par le dégoût. Ce dégoût réduit la Dextérité de la créature de 4 points jusqu\'à ce que l\'effet se dissipe ou que la créature ne se trouve plus à moins de 6 mètres d\'un serpent ou d\'un yuan-ti. Cette capacité est similaire à celle du sort Aversion (niveau de lanceur de sorts 16).\nConstriction (Ext). Sysalok inflige 1d6+6 points de dégâts avec un jet de lutte réussi.\nPrise améliorée (Ext). Pour utiliser cette capacité, Sysalok doit toucher une créature de taille Grande ou plus petite avec son attaque de morsure. Il peut alors tenter d\'engager une lutte en tant qu\'action gratuite sans provoquer d\'attaques d\'opportunité. S\'il réussit le jet de lutte, il établit une prise et peut étrangler.\nProduction d\'acide (Ps). Sysalok a la capacité psionique de sécréter de l\'acide par son corps, infligeant 3d6 points de dégâts d\'acide à la prochaine créature qu\'il touche, y compris une créature touchée par son attaque de morsure. Si Sysalok est en train de lutter, de constrictionner ou d\'immobiliser un ennemi lorsqu\'il utilise ce pouvoir, sa prise inflige 5d6 points de dégâts d\'acide. L\'acide devient inerte lorsqu\'il quitte son corps, et Sysalok est immunisé contre ses effets.\nCompétences. Sysalok peut toujours choisir de prendre 10 sur un jet d\'escalade, même s\'il est pressé ou menacé. Il bénéficie d\'un bonus racial de +8 sur tout jet de natation pour effectuer une action spéciale ou éviter un danger. Il peut toujours choisir de prendre 10 sur un jet de natation, même s\'il est distrait ou en danger. Il peut utiliser l\'action de course pendant qu\'il nage, à condition de nager en ligne droite.', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2403);

-- 2405 — Cushtal
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2405, 'Cushtal', 21, NULL, 'PV : 84 chacun (13 DV) ; régénération/guérison rapide\nRD : 10/magie\nNM Aberration de Grande taille\nInitiative : +4\nSens : vision dans le noir 18 m ; vision magique 36 m, détection de la magie (NLS 13), détection de l\'invisibilité 36 m ; Perception auditive +15, Détection +15\nLangues : télépathie 30m\nClasse d\'armure : 27, toucher 9, pris au dépourvu 27\nImmunités : contre la pétrification, la métamorphose\nRM : 23\nJets de sauvegarde : Vig +8, Réf +6, Vol +13\nVitesse de déplacement : vol 10 m (6 cases) (parfait)\nMêlée : 4 griffes +12 chacune (1d6+4) et morsure +7 (2d6+2) et dard +7 (1d8+2 plus poison)\nEspace occupé/allonge : 3 m/3 m\nAttaque de base/lutte : +9/+17\nOptions d\'attaque : Extension d\'effet ; poison\nActions spéciales : implant\nSorts de ensorceleur connus (NLS 13 ; 1d20+15 pour surmonter la RM) :\n6e (4/jour) - $éclair multiple$ (DD 21), $Désintégration$ (DD 21)\n5e (7/jour) - $Brume mortelle$ (DD 20), $Immobilisation de monstre$ (DD 20), $Télékinésie$ (DD 20)\n4e (7/jour) - $Charme-monstre$ (DD 19), $Porte dimensionnelle$, $Assassin imaginaire$ (DD 19), $Mur de glace$\n3e (7/jour) - $Déplacement$, $éclair$(DD 18), $Tempête de neige$, $Baiser du vampire$ (+13 au toucher en mêlée)\n2e (7/jour) - $Baiser de la goule$ (+13 en mêlée, DD 17), $détection de l\'invisibilité$, $Main spectrale$ (+13 en mêlée), $Nuée grouillante$, $Fou rire de Tasha$ (DD 17)\n1er niveau (8/jour) - $Contact glacial$ (+13 en mêlée), $Graisse$, $Projectile magique$, $Rayon affaiblissant$ (+9 à distance), $Bouclier$\n0 (4/jour) - $Signature magique$, $Lumières dansantes$, $Détection de la magie$, $Destruction de mort-vivant$ (+9 à distance), $Son imaginaire$ (DD 15), $Manipulation à distance$, $Message$, $Ouverture/fermeture$, $Lecture de la magie$\nCapacités magiques : (niveau de lanceur de sorts 13) :\nÀ volonté - $Détection de la magie$\nCaractéristiques : Force 18, Dex 11, Con 14, Int 17, Sag 20, Cha 21\nDons : Extension d\'effet, #Vigueur surhumaine#, #Science de l\'initiative#, #Réflexes surhumains#, #Efficacité des sorts accrue#\nCompétences : Concentration +12, Diplomatie +7, Discrétion -4, Intimidation +15, Connaissances (mystères) +13, Perception auditive +15, Fouille +13, Psychologie +15, Art de la magie+15, Détection +15\nVol (Ext). Le corps d\'un phaerimm étant naturellement flottant, il peut voler à une vitesse de 9 mètres. Cette flottabilité confère également à la créature un effet permanent de feuille morte (comme le sort) avec une portée personnelle\nImplant (Ext). En tant qu\'action simple, un phaerimm adulte mature peut utiliser son dard pour pondre des oeufs à l\'intérieur d\'une créature paralysée. Les petits éclosent environ 90 jours plus tard, dévorant littéralement leur hôte de l\'intérieur. Un sort de guérison des maladies permet de débarrasser la victime des oeufs, tout comme un jet de Premiers secours réussi avec un DD de 20 effectué par un personnage ayant des rangs dans cette compétence. Si le jet échoue, le soigneur peut réessayer, mais chaque tentative (réussie ou non) inflige 1d4 points de dégâts au patient\nEmpoisonnement (Ext). Blessure, Vigueur DD 18, paralysie 2d4 rounds/paralysie 1d3 heures. Les créatures paralysées effectuent une lévitation, impuissantes, à quelques mètres du sol', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2405);

-- 2406 — garde Shadovar
INSERT INTO dd_monstres (mo_id, mo_nom, mo_mocat_id, mo_mogr_id, mo_stats, mo_fp_id, mo_res_id, mo_camp_id, mo_public, mo_visible, mo_ruleset_var_id)
SELECT 2406, 'garde Shadovar', 28, NULL, 'PV 54 chacun (7 HD)\nhumain guerrier 6 / sorcier 1\nNM Humanoïde de taille moyenne\nInitiative : +1 ; Perception auditive +0, Détection +0\nLangues : Commun, Nétherisses\nClasse d\'armure : 20, toucher 11, pris au dépourvu 19\nJets de sauvegarde : Vig +7, Réf +3, Vol +6\nVitesse de déplacement : 7,5m (4 cases) en plaque complète, vitesse de base 9m.\nMêlée : hallebarde +1, +11/+6 (1d10+7/×3)\nDistance : Baguette de rayon ardent +7 toucher (4d6 feu)\nAttaque de base/lutte : +6/+9\nOptions de combat : combat aveugle, Enchainement, Attaque en puissance\nÉquipement de combat : baguette de rayon ardent (20 charges), potion de soins modérés, parchemin d’invisibilité accrue (test de NLS DD 8)\nSorts de sorcier connus : (NLS 5ème, 35% de chances d’échec des sorts) :\n1er (4/jour) - mains brûlantes (DD 12), coup au but*.\n0 (5/jour) - détection de la magie, lumière, rayon de givre (+7 toucher à distance), lecture de la magie.\nPas de composante somatique, donc pas de risque d’échec.\nCaractéristiques : For 16, Dex 13, Con 14, Int 8, Sag 10, Cha 12\nParticularités : Familier (aucun pour le moment)\nDons : #Combat en aveugle#, #Enchainement#, #Magie de guerre#, #Volonté de fer#, Attaque en puissance, Lanceur de sort polyvalentCAr, Arme de prélection (hallebarde), #Spécialisation martiale# (hallebarde).\nCompétences Concentration +4 (+8 pour les jets défensifs), Intimidation +6, Auditive +0, Équitation +6, Magie +3, Détection +0.\nPossessions équipement de combat plus plaque complète +1, hallebarde +1, 7 po, 12 pa', NULL, 88, 5, 1, 1, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM dd_monstres WHERE mo_id = 2406);
